(window.GIM_TS=window.GIM_TS||{})["Meilah.0"]={"from":0,"a":[["\u0003קדשי קדשים\u0004 שנפסלו קודם שנזרק דמם, כגון \u0003ששחטן ב\u0004צד \u0003דרום\u0004 של העזרה שבמקדש (ומקום שחיטתם הראוי הריהו בצפון) — אף שנפסלו, מכל מקום לא יצאו מכלל קדושתם לענין זה ש\u0003מועלין בהן\u0004 (יש בהם דין מעילה), שהנהנה מהם חייב קרבן (\"אשם מעילות\"), ותשלומי קרן וחומש. ובפרטי דין זה: \u0003שחטן בדרום\u0004 שלא כהלכתם, ואולם \u0003קיבל דמן בצפון\u0004 כהלכתם — יש בהם דין מעילה (שהרי קבלת הדם שהיא עיקר העבודה נעשתה בצפון), ואף אם שחטם \u0003בצפון וקיבל דמן בדרום,\u0004 שעיקר העבודה נעשתה שלא כדין — אף אלו יש בהם דין מעילה.","וכשם שדין זה נוהג בשינוי מקום העבודה, כך הוא נוהג בשינוי זמן העבודה, שאם \u0003שחט\u0004 את הקרבנות הללו \u0003ביום\u0004 (שהוא הזמן הראוי לשחיטה) וזרק את דמם \u0003בלילה\u0004 (שאינו זמן הראוי לעבודה), ובודאי אם שחטם \u0003בלילה וזרק\u0004 את דמם \u0003ביום\u0004 — יש בהם דין מעילה. \u0003או\u0004 כמו כן יש דין מעילה בקרבנות שנפסלו משום פיגול, שבזמן \u0003ששחטן\u0004 חשב שיאכל את בשרם, או יזרוק את דמם, או יקריב את אימוריהם \u0003חוץ לזמנו,\u0004 כלומר, שלא בזמן הראוי להם, או \u0003חוץ למקומו,\u0004 שלא במקום הראוי להם (כגון מחוץ לעזרה) — בכל אלה \u0003מועלין בהן.\u0004","\u0003כלל אמר ר' יהושע\u0004 בענין מעילה בקדשים שנפסלו: \u0003כל שהיה לה\u0004 (לבהמת הקרבן) כבר \u0003שעת היתר\u0004 (אכילה) \u0003לכהנים\u0004 לפני שנפסלה — \u0003אין מועלין בה\u0004 עוד, כיון שעיקרה של מעילה היא דווקא בקדשים המוגדרים כ\"קדשי ה' \" — שאין בהם צד היתר הנאה לאדם, ומשעה שהותר הקרבן לאכילה לכהנים, שוב אינו בכלל זה, אף שחזר ונפסל אחר כך מאכילה. \u0003ו\u0004אילו \u0003כל שלא היה לה שעת היתר לכהנים\u0004 לפני שנפסלה — הרי היא עדיין בכלל \"קדשי ה' \", ומועלין בה. ומסבירים:","\u0003איזו היא שהיה לה שעת היתר לכהנים?\u0004 — כגון \u0003ש\u0004לאחר זריקת הדם \u0003לנה\u0004 (עבר לילה על הבשר בלא שנאכל, ונעשה בכך נותר), או \u0003נטמאה\u0004 בשר הקרבן, או \u0003שיצאה\u0004 אל מחוץ לעזרה — אין בכל אלו דין מעילה, אף שבשר הקרבן עתה אסור לכהנים, כיון שהיתה שעה שהיה הבשר מותר באכילה לפני שנפסל.","\u0003ואיזו היא שלא היה לה שעת היתר לכהנים?\u0004 — \u0003ש\u0004בזמן ש\u0003נשחטה\u0004 חשב עליה לאוכלה או לזרוק את דמה או להקטיר את אימוריה \u0003חוץ לזמנה,\u0004 או \u0003חוץ למקומה, ו\u0004כן \u0003שקיבלו\u0004 את דם הקרבן כהנים ה\u0003פסולין\u0004 לעבודה בשל היותם בעלי מומים, \u0003ו\u0004כן אם \u0003זרקו\u0004 הפסולים \u0003את דמה.\u0004 שבכל אלו, כיון שלא היתה שעה שבשר הקרבן היה מותר באכילה, הרי זה בכלל \"מקדשי ה' \", ומועלים בו.","\u0003קתני\u0004 \u0005[שנה]\u0006 במשנה: \u0003קדשי קדשים ששחטן בדרום\u0004 — \u0003מועלין בהן.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, וכי \u0003משום\u0004 ש\u0003שחיטתן\u0004 נעשתה \u0003בדרום,\u0004 אף שאין זו שחיטה ראויה, \u0003אפיקינון\u0004 \u0005[הוציא אותם]\u0006 בכך \u0003מידי\u0004 דין \u0003מעילה?\u0004","ומשיבים: איצטריך \u0005[הוצרך\u0006 הדבר\u0005]\u0006 להישנות, שאם לא כן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה\u0006 על \u0005דעתך\u0006 לומר\u0005]\u0006 כי \u0003הואיל ואמר עולא, אמר ר' יוחנן: קדשים שמתו\u0004 מעצמם, לפני שנשחטו כדינם — \u0003יצאו\u0004 בכך \u0003מידי\u0004 דין \u0003מעילה דבר תורה\u0004 (מדין תורה), שמן התורה אין דין מעילה אלא בקדשים חיים, מעתה אם כן הייתי אומר כי \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 קרבנות \u0003קדשי קדשים לגבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 שחיטתם ב\u0003דרום\u0004 העזרה, \u0003כמה דחנקינון דמי\u0004 \u0005[כאילו שחנקם\u0006 הם \u0005נחשבים],\u0006 ואין בהם דין מעילה מדין תורה.","לכן באה משנתנו ו\u0003קא משמע לן\u0004 \u0005[השמיעה לנו]\u0006 שאף שנשחטו שלא כדין, אינם נחשבים כמי שמתו, ויש בהם דין מעילה מן התורה. וטעם ההבדל: שכן \u0003קדשים שמתו\u0004 — \u0003לא חזו\u0004 \u0005[אינם ראויים]\u0006 \u0003כלל\u0004 להקרבה. \u0003אבל\u0004 שחיטת קרבנות ב\u0003דרום\u0004 — \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003אינו ראוי לקדשי קדשים, אבל\u0004 ככלל אינה שחיטה פסולה, שהרי \u0003ראוי הוא לקדשים קלים\u0004 שנשחטים אף בדרום.","ועוד בבירור המשנה, שואלים: \u0003למה לי למיתני\u0004 \u0005[לשנות]\u0006 את \u0003כל הני\u0004 \u0005[אלה]\u0006 המקרים הנזכרים בה, והלא היה יכול להשמיענו מקרה אחד, וממנו נלמד את העיקרון שאף שנפסל הקרבן — יש בו דין מעילה!","ומשיבים: \u0003צריכי\u0004 \u0005[נצרכו]\u0006 להישנות כולם, שממקרה אחד לא היינו למדים ביחס לשאר המקרים. ומפרטים: \u0003אי תנא\u0004 \u0005[אם היה שונה]\u0006 רק את המקרה הנזכר ראשון במשנה, כאשר \u0003שחטן בדרום וקיבל דמן בצפון,\u0004 הייתי אומר כי רק \u0003הכא\u0004 \u0005[כאן]\u0006 הדין הוא \u0003דאית בהו\u0004 \u0005[שיש בהם]\u0006 דין \u0003מעילה, משום\u0004 שאף שנשחטו שלא כדין, מכל מקום כיון שה\u0003קבלה\u0004 של הדם \u0003בצפון הוא,\u0004 לכן יהא בהם דין מעילה. \u0003אבל\u0004 אם \u0003שחטן בצפון וקיבל\u0004 את \u0003דמן בדרום, הואיל וקיבל\u0004 את דמם \u0003בדרום הוא,\u0004 שהקבלה, נעשתה שלא כהלכתה — הייתי אומר כי \u0003נפיק\u0004 \u0005[יוצא]\u0006 הקרבן בכך \u0003מידי\u0004 דין \u0003מעילה.\u0004 לכך שנתה המשנה גם דין זה.","\u0003ואי תנא האי\u0004 \u0005[ואם היה שונה\u0006 את \u0005זה,\u0006 שני המקרים הללו בלבד\u0005]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי דווקא במקרים אלו יש בקרבנות דין מעילה, משום שהעבודה בהם נעשתה ביום, ו\u0003יממא\u0004 \u0005[היום] זמן\u0006 ה\u0003הקרבה\u0004 הראוי \u0003הוא. אבל\u0004 אם \u0003שחטה בלילה וזרק\u0004 דמה \u0003ביום\u0004 — \u0003לילה לאו\u0004 \u0005[לא]\u0006 \u0003זמן הקרבה\u0004 הוא כלל, \u0003ו\u0004לכן \u0003האי\u0004 \u0005[זה]\u0006 כיון ש\u0003שחט בלילה\u0004 — אמור \u0003דנפיק\u0004 \u0005[שיוצא]\u0006 בכך הקרבן \u0003מידי מעילה!\u0004","וממשיכים עוד, \u0003ואי תנא\u0004 \u0005[ואם היה שונה]\u0006 במשנתנו שיש בה דין מעילה רק כאשר \u0003שחטה בלילה\u0004 וקיבל דמה ביום, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי דווקא במקרה זה, \u0003הואיל וקבל דמה ביום\u0004 שהוא הזמן הראוי לעבודה — \u0003אית\u0004 \u0005[יש] בה\u0006 דין \u0003מעילה, אבל\u0004 במקרה ש\u0003שחטן ביום ו\u0004קיבל ו\u0003זרק דמן\u0004 (שזה עיקר העבודה) \u0003בלילה, הואיל ו\u0004הלילה \u0003לאו\u0004 \u0005[לא]\u0006 \u0003זמן הקרבה הוא\u0004 — \u0003כמאן דחנקינון דמי\u0004 \u0005[כמי שחנקם\u0006 הם \u0005נחשבים],\u0006 \u0003ולא אית בהו\u0004 \u0005[ואין בהם]\u0006 דין \u0003מעילה,\u0004 לכן \u0003קמשמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 את כל המקרים הללו במשנתנו.","ועוד בבירור המשנה. שנינו שגם אם שחטם במחשבה לאוכלם \u0003חוץ לזמנו\u0004 או \u0003חוץ למקומו,\u0004 מועלים בהם. ושואלים: קרבנות אלה נפסלו כפיגול, ואם כן \u0003למאי חזו\u0004 \u0005[למה\u0006 איפוא הם \u0005ראויים]?\u0006 שהרי אינם ראויים לא להקרבה ולא לאכילה, ומדוע שיחול בהם דין מעילה האמור בקדשים?","ומשיבים: \u0003הואיל ומרצין\u0004 \u0003ל\u0004ענין ה\u0003פיגולין,\u0004 שכל שלא נזרק דם הקרבן כהלכתו — אינו נחשב כפיגול, ולא יצא לגמרי הקרבן מקדושתו, ולכן יש בו דין מעילה."],["\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: קרבנות שעשה בהם עבודה שלא במקום הראוי, והריהם פסולים מלהקריב על המזבח, \u0003אי\u0004 \u0005[אם]\u0006 קרה ו\u0003עלו\u0004 על המזבח להקרבה, \u0003מהו\u0004 דינם, האם אומרים אנו \u0003שירדו\u0004 (שיורידו אותם) מן המזבח, בלא להקריבם, שהרי פסולים הם. או שאומרים שכיון שיש בהם צד קדושה, כיון שעלו — שוב לא ירדו. ונחלקו חכמים בדבר, \u0003רבה אמר: אם עלו\u0004 — \u0003ירדו, רב יוסף אמר: אם עלו\u0004 — \u0003לא ירדו.\u0004","ומסבירים את שיטותיהם: \u0003אליבא\u0004 \u0005[לשיטתו]\u0006 של \u0003ר' יהודה\u0004 במשנה במסכת זבחים (סד,א) הלומד מדרשת הכתובים שבהמת קדשים שנפסלה אם עלתה לראש המזבח — תרד, \u0003לא תיבעי לך\u0004 \u0005[לא תישאל,\u0006 תסתפק \u0005לך],\u0006 שכן \u0003דכולי עלמא לא פליגי\u0004 \u0005[לדעת הכל\u0006 רבה ורב יוסף \u0005אינם חלוקים]\u0006 שכך הוא הדין גם בפסולים הנזכרים במשנתנו, שאף \u0003אם\u0004 כבר \u0003עלו\u0004 על המזבח — \u0003ירדו\u0004 ממנו בלא הקרבה. ואולם \u0003כי פליגי אליבא\u0004 \u0005[כאשר נחלקו\u0006 רבה ורב יוסף, הרי זה \u0005לשיטתו]\u0006 של \u0003ר' שמעון\u0004 החולק על ר' יהודה וסבור שכל הפסולים שמנה ר' יהודה וכן חטאת העוף שנתן את דמה למעלה מחוט הסיקרא (שבאמצעו של המזבח), או עולת העוף שנתן את דמה למטה מחוט הסיקרא שלא כדינם ונפסלו בכך, אם עלו לא ירדו.","\u0003רב יוסף\u0004 סבור \u0003כ\u0004שיטת \u0003ר' שמעון,\u0004 שאף במקרים השנויים במשנתנו אם עלו — לא ירדו. ואילו \u0003רבה אמר לך\u0004 \u0005[יכול לומר לך]:\u0006 אף לשיטת ר' שמעון, אין דין הנשחטים בדרום כדין מקרים אלו, משום ש\u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר הוא]\u0006 \u0003ר' שמעון\u0004 שאם עלו לא ירדו, \u0003אלא ב\u0004קרבנות כגון חטאת העוף שדמיהם \u0003ניתנין למטה\u0004 מחוט הסיקרא, \u0003שנתנן\u0004 שלא כדין \u0003למעלה\u0004 מחוט הסיקרא, \u0003או ב\u0004קרבנות כגון עולת העוף שדמיהם \u0003ניתנין למעלה שנתנן למטה,\u0004 ששינה רק את מקומה של הזאת הדם במזבח,","\u0003ולעולם\u0004 מדובר בקרבנות ש\u0003שחטן וקבל דמן בצפון\u0004 כראוי, ורק נתינת הדם היתה שלא כראוי, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בקרבנות שנשחטו שלא במקומם הראוי, \u0003כיון\u0004 ששינה במקום שחיטתם ו\u0003שחטן בדרום\u0004 — \u0003כמאן דחנקינון דמי\u0004 \u0005[כמו שחנקם נחשבים]\u0006 וכאילו לא נשחטו כלל, ואם עלו — ירדו.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003קדשי קדשים ששחטן בדרום\u0004 — \u0003מועלין בהן.\u0004 ומעתה נדון בדבר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב יוסף\u0004 — \u0003ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005],\u0006 שכן הוא סבור שלא יצאו על ידי כך מקדושתם, וכשם שאם עלו, לא ירדו — אף מועלים בהם. \u0003אלא לרבה\u0004 הסבור שאם עלו — ירדו, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדוע יש בהם דין מעילה! ומשיבים: לדעת רבה \u0003מאי\u0004 \u0005[מה]\u0006 משמעות \u0003\"מועלין בהן\"\u0004 האמור במשנה? — \u0003מדרבנן\u0004 \u0005[מדברי חכמים],\u0006 ומן התורה אכן אין בהם מעילה.","ומסבירים: \u0003מאי איכא\u0004 \u0005[מה\u0006 איזה הבדל מעשי \u0005יש]\u0006 \u0003בין\u0004 מעילה \u0003דאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003ל\u0004מעילה מדברי \u0003רבנן\u0004 \u0005[חכמים]?\u0006 — במעילה \u0003דאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003משלמין חומש\u0004 (חמישית) בנוסף על תשלום הקרן, ואילו במעילה \u0003דרבנן\u0004 \u0005[מדברי חכמים]\u0006 — \u0003לא\u0004 מוסיפים חומש.","ותוהים: \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 \u0003מעילה מדרבנן\u0004 \u0005[מדברי חכמים]?\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 שכן אמר עולא, אמר ר' יוחנן: \u0003קדשים שמתו\u0004 — \u0003יצאו\u0004 בכך \u0003מידי\u0004 דין \u0003מעילה דבר תורה.\u0004 ונדייק מדבריו: \u0003אלמא מדאורייתא לא אית להון\u0004 \u0005[מכאן\u0006 שדווקא \u0005מן התורה אין להם]\u0006 דין מעילה, אבל \u0003בדרבנן אית בהון\u0004 \u0005[מדברי חכמים יש בהם]\u0006 דין מעילה, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 במשנתנו שיש מעילה בנשחטים שלא במקומם, הכוונה היא — \u0003מדרבנן\u0004 \u0005[מדברי חכמים].\u0006","ושואלים על כך: להסברו של רבה שדין המעילה שבמשנתנו הוא מדברי חכמים, \u0003לימא תנינא להא\u0004 \u0005[האם לומר\u0006 שכבר \u0005שנינו\u0006 במשנתנו \u0005את\u0006 העיקרון \u0005הזה]\u0006 שאמר \u0003עולא, אמר ר' יוחנן,\u0004 ואם כן מה השמיענו בכך עולא? ומשיבים: \u0003אף על גב דתנינא\u0004 \u0005[אף על פי ש\u0006אמנם ניתן ללמוד ממה \u0005ששנינו]\u0006 במשנה שיש מעילה מדברי חכמים, עדיין \u0003איצטריך\u0004 \u0005[צריך]\u0006 את דברי \u0003עולא,\u0004 משום ש\u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה\u0006 על \u0005דעתך\u0006 להבדיל ו\u0005לומר]\u0006 כי דווקא \u0003הכא\u0004 \u0005[כאן]\u0006 בקרבנות שנשחטו שלא במקומם אומרים אנו שיש בהם מעילה מדברי חכמים, משום ש\u0003לא בדילין מנהון\u0004 \u0005[לא בדלים,\u0006 פורשים \u0005מהם]\u0006 אנשים, שהרי הם נראים כשאר הקדשים, ואין הדבר ניכר.","ומשום כך גזרו בהם חכמים, \u0003אבל\u0004 ב\u0003קדשים שמתו, הואיל ובדילין מנהון\u0004 \u0005[ובדלים מהם]\u0006 האנשים, שהרי הכל יודעים שנבילות הן אלו, ומאוסות הן, לא ייהנו מהן. ואם כן \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003אפילו מעילה מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 \u0003לא\u0004 תהיה בהם. לכן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 עולא בשם ר' יוחנן \u0005משמיע לנו]\u0006 שאף באלו יש מעילה מדברי חכמים.","ומקשים על כך: אף דין זה שקדשים ש\u0003מתו\u0004 יש בהם מעילה מדברי חכמים \u0003נמי תנינא\u0004 \u0005[גם כן\u0006 כבר \u0005שנינו],\u0006 שכן שנינו: \u0003הנהנה מן החטאת\u0004 שהיא בעלת מום, ועומדת להיפדות, \u0003כשהיא חיה\u0004 עדיין, וכגון שתלש מצמרה — \u0003לא מעל\u0004 בהנאה זו \u0003עד שיפגום\u0004 (שיחסיר משוויה שווה פרוטה). \u0003ו\u0004אילו הנהנה מקרבן החטאת \u0003כשהיא\u0004 כבר \u0003מתה\u0004 ושוב אין בה דין פדיון, ולא הפחית איפוא מדמיה — \u0003כיון\u0004 ש\u0003נהנה כל שהוא\u0004 — \u0003מעל.\u0004 והרי מעילה זו ודאי שמדברי חכמים היא, שהרי מן התורה אין דין מעילה בבהמת קדשים לאחר שמתה. ונמצא שדברים אלה שאמר עולא בשם ר' יוחנן שנויים כבר במשנה!","ומשיבים: אין ללמוד כן, משום ש\u0003סלקא דעתך\u0004 \u0005[היה עולה\u0006 על \u0005דעתך]\u0006"],["\u0003אמינא\u0004 \u0005[לומר]\u0006 כי אין דין זה נוהג אלא בקרבן \u0003חטאת,\u0004 וטעם הדבר — \u0003הואיל ולכפרה קא אתיא\u0004 \u0005[הוא בא],\u0006 משום כך בדלים אנשים ממנה כל עוד היא בחיים ועומדת לכפרה, ואולם משמתה ושוב אינה עומדת לכפרה — שוב \u0003לא בדילין מינה\u0004 \u0005[לא בדלים ממנה],\u0006 ולכן גזרו חכמים שיהיה בה דין מעילה, שלא יבואו ליהנות ממנה. \u0003אבל\u0004 בשאר \u0003קדשים,\u0004 כגון אשם ושלמי ציבור, \u0003הואיל ולאו\u0004 \u0005[ולא]\u0006 \u0003לכפרה קאתי\u0004 \u0005[הם באים]\u0006 ומלכתחילה בדלים מהם בלא קשר לכפרה — \u0003בדילי מנהון\u0004 \u0005[בדלים מהם]\u0006 אנשים, אף כשהם מתים, \u0003ו\u0004לכן \u0003לית בהו\u0004 \u0005[אין\u0006 מקום לגזור \u0005בהם]\u0006 דין \u0003מעילה\u0004 מדברי חכמים, משום כך עולא בשמו של ר' יוחנן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאף בשאר הקדשים שמתו נוהג דין מעילה מדברי חכמים.","ושואלים מצד אחר: \u0003וחטאת שמתה מי אית\u0004 \u0005[האם יש]\u0006 \u0003בה\u0004 דין \u0003מעילה? והתנן\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חטאות המתות\u0004 (אותן חמש חטאות שאינן ראויות להיקרב על המזבח, ואסורות בהנאה, שגורמים להן שימותו. וראה עיונים), \u0003ו\u0004כן ה\u0003מעות ה\u0004אסורות בהנאה, שדינן ש\u0003הולכות לים המלח\u0004 לאיבוד (ראה עיונים) שמלכתחילה \u0003לא נהנין\u0004 מהן, \u0003ו\u0004אולם אם נהנו מהן — \u0003לא מועלין\u0004 בהן, שמאחר שנועדו לאיבוד אינן נחשבות כהקדש לענין המעילה. הרי שאין דין מעילה בחטאות העומדות למיתה, וקשה על דברי עולא בשם ר' יוחנן שיש דין מעילה מדברי חכמים בחטאות שמתו!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לשאלה זו: יש להבחין בין אלו חמש החטאות המתות (העומדות למיתה) לשאר חטאות שמתו, שכן חמש \u0003חטאות המתות\u0004 — כבר \u0003בחייהן בדילין מנהון\u0004 \u0005[בדלים מהם]\u0006 האנשים, מאחר שמלכתחילה אינן עומדות להקרבה, ואין בהן כפרה הריהם נזהרים מלמעול בהן. ולכן לא גזרו בהם חכמים דין מעילה משמתו. ו\u0003לאפוקי היכא\u0004 \u0005[להוציא\u0006 מכלל זה \u0005היכן,\u0006 במקרה\u0005]\u0006 של קרבנות החטאת ש\u0003מחיים,\u0004 \u0003דלא בדילין מיניה\u0004 \u0005[שאין בדלים מהם]\u0006 האנשים, שהרי לכפרתם הן עומדות, ומשום כך גזרו בהם חכמים דין מעילה גם לאחר שמתו.","ושבים למחלוקת בדין הקרבנות השנויים במשנתנו שנפסלו בשינוי מקום שחיטתם, אם עלו על המזבח, האם מוקרבים הם או שמורדים ממנו בלא הקרבה, שלדעת רבה אף שעלו — ירדו, ולדעת רב יוסף כיון שעלו — לא ירדו. ודנים עוד: \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב יוסף לרבה חדא מגו חדא, וחדא מגו חדא\u0004 \u0005[אחת מתוך אחת, ואחת מתוך אחת],\u0006 כלומר, שהיה רב יוסף צריך לדקדק בכמה משניות שבמסכת זבחים זו מתוך זו עד שהגיע לקושיה.","שנינו במשנה: \u0003וכולן\u0004 (כל המקרים שנמנו לפני כן בקרבנות העוף (החטאת והעולה) שנעשה בהם שינוי מדרך עבודתם הראויה, אף שהם פסולים ואסורים בהקרבה ובאכילה, מכל מקום \u0003אין\u0004 הם \u0003מטמאים בגדים\u0004 של האוכל מהם, כשאר נבלת עוף טהור כשכזית ממנה נתון ב\u0003בית הבליעה\u0004 שלו, שכן מליקתם הוציאה אותם מכלל נבילה. \u0003ו\u0004מכל מקום, כיון שלא הותרו לכהנים — הנהנים מהם \u0003מועלין בהן.\u0004","\u0003חוץ מחטאת העוף שעשה\u0004 אותה \u0003למטה,\u0004 במחצית התחתונה של המזבח, שהוא מקומה הראוי, ו\u0003כמעשה חטאת העוף\u0004 (במליקה ובהזאה) לשם חטאת, שכיון שנעשתה כראוי, והרי היא מותרת מעתה באכילה לכהנים, שוב אין בה דין מעילה.","\u0003וקתני עילויה\u0004 \u0005[ושנינו עליה],\u0006 לאחר משנה זו משנה אחרת: \u0003כל\u0004 קרבן \u0003שהיה פסולו\u0004 (שנפסל) \u0003בקדש,\u0004 תוך כדי עבודה במקדש, אלא שנפסל משום סיבה אחרת, וכגון שנמלק בלילה — \u0003אינו מטמא בגדים\u0004 בהיות כזית ממנו נתון ב\u0003בית הבליעה,\u0004 שכן הועילה המליקה שלא ייחשב עוף זה כנבלת עוף טהור. \u0003וכל שלא היה פסולו בקדש,\u0004 שפסולו היה קודם שבא לעזרה, וכגון מחוסר אבר, שאין ראוי להקרבה — הרי זה \u0003מטמא\u0004 את ה\u0003בגדים\u0004 של האוכל בהיות כזית ממנו נתון ב\u0003בית הבליעה\u0004 שלו, כשאר נבלת עוף טהור.","\u0003וקתני\u0004 \u0005[ושנה]\u0006 במשנה נוספת במסכת זבחים כלל זה: \u0003כל\u0004 קרבן \u0003שהיה פסולו בקדש\u0004 — הקודש מקבלו, לאמור, ש\u0003אם עלו\u0004 על המזבח, אף שפסולים להקרבה — \u0003לא ירדו,\u0004 אלא יוקרבו. והעולה משלוש משניות אלה: מן המשנה הראשונה למדים ששינוי מקום (כגון זו של החטאת) אינו מביא את הקרבן הנפסל לטמא בגדים. ומן המשנה שאחריה למדים שאותם קרבנות פסולים שאין מטמאים בגדים מוגדרים כמי ש\"היה פסולם בקודש\". ומן המשנה השלישית למדים שכל המוגדר כמי ש\"היה פסולו בקודש\" — אם עלו לא ירדו. הרי איפוא שקרבן שנפסל בשל שינוי מקום שחיטתו, דינו שאם עלה לא ירד, והרי זו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003רבה!\u0004 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא, ונדחו דבריו.","ומעירים: \u0003והא דפליגי\u0004 \u0005[ו\u0006מחלוקת \u0005זו שחלוקים]\u0006 \u0003בה רבה ורב יוסף\u0004 בדין הקרבנות שנפסלו בשל שינוי מקום שחיטתם ועלו למזבח \u0003פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 \u0003לר' אלעזר\u0004 מה דינם. שכן \u0003אמר ר' אלעזר: עולת במת יחיד,\u0004 שהקדיש עולה כדי להקריבה בבמת יחיד (שלא במקדש או במשכן), ונמלך ו\u0003הכניסה לפנים\u0004 אל בין המחיצות —"],["\u0003קלטוה\u0004 את העולה הזו מחיצות העזרה, שמכאן והלאה יחולו עליה \u0003לכל דבר\u0004 דיני העולה הקריבה במקדש, ומתוך הלכה זו","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אלעזר: עולת במת יחיד ש\u0004נמלך ו\u0003הכניסה\u0004 לעזרה, ואחר \u0003ש\u0004הכניסה \u0003נפסלה\u0004 בעבודתה, וכגון ששחטה בדרום העזרה (שלא במקומה הראוי לשחיטה, בצפון) ו\u0003עלו\u0004 איבריה להקרבה על המזבח, \u0003מהו\u0004 הדין בכגון זה, האם אומרים אנו \u0003שירדו?\u0004 שכן אף שנפסלה בשינוי מקום במקדש, אך אילו היתה נשחטת בדרום בבמת היחיד — לא היתה נפסלת בכך.","ונסיק מתוך כך: \u0003מ\u0004תוך \u0003דקמיבעיא ליה לחדא\u0004 \u0005[שהיה מסופק לו\u0006 לר' אלעזר דווקא \u0005ב\u0006מקרה \u0005האחד\u0006 הזה\u0005],\u0006 \u0003מכלל\u0004 הדבר נלמד \u0003דאידך\u0004 \u0005[ש\u0006במקרה \u0005האחר],\u0006 במקדיש עולה לכתחילה למקדש, ונפסלה לעבודה במקדש, וכגון שנשחטה בדרום, \u0003פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 מה הדין כשעלו איבריה למזבח, \u0003אי\u0004 \u0005[או] כ\u0006דעת \u0003רבה\u0004 שאין הם קרבים, \u0003אי\u0004 \u0005[או] כ\u0006דעת \u0003רב יוסף\u0004 שקרבים.","ודוחים קביעה זו: מכאן אין להוכיח שלר' אלעזר היה ברור מה הדין בעולה שהקדישה מלכתחילה למקדש, ונפסלה לעבודה, שאפשר לומר שאף במקרה זה אין הוא יודע, ו\u0003חדא מגו חדא קמיבעיא ליה\u0004 \u0005[\u0006ובמקרה \u0005אחד מתוך\u0006 המקרה \u0005אחד\u0006 נוסף \u0005נשאלה לו\u0006 השאלה\u0005],\u0006 כלומר, ששאלתו מורכבת משני המקרים יחד, בין שדעתו כרבה ובין שדעתו כר' יוסף במקרה האחד, עדיין יש לשאול מהו הדין במקרה השני.","ומסבירים: מצד אחד אף אם נאמר כשיטת רבה שאין האיברים הפסולים שעלו לראש המזבח קרבים, עדיין יש מקום להבחין ולומר כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רבה התם\u0004 \u0005[שם]\u0006 ש\u0003אם עלו ירדו,\u0004 אלא משום שהוא סבור שכאשר מתחילה הקדיש את הקרבן להקריבו בתוך ה\u0003מחיצה\u0004 של העזרה (שבה השחיטה נעשית רק בצפון) \u0003כתיקנה\u0004 (כהלכתן), בכגון זה השחיטה בדרום","\u0003פסלה\u0004 \u0005[פוסלת]\u0006 לגמרי את הקרבן, ולכן אף אם עלה למזבח — ירד. ואילו כאשר מתחילה הוקדש להקרבה בבמת יחיד, שהוא \u0003שלא כתיקנה,\u0004 בכגון זה שחיטת דרום \u0003לא פסלה\u0004 \u0005[איננה פוסלת]\u0006 לגמרי את הקרבן, ולכן אם עלו למזבח — לא ירדו.","\u0003או דילמא\u0004 \u0005[שמא]\u0006 נאמר להיפך: \u0003אפילו ל\u0004דעת \u0003רב יוסף\u0004 שאמר ש\u0003אם עלתה\u0004 — \u0003לא תרד,\u0004 אפשר לומר שדין זה נאמר דווקא ב\u0003מחיצה כתיקנה,\u0004 כאשר מתחילה הקדיש את הקרבן להקריבו בתוך מחיצת העזרה — שמאחר וההקדשה נעשתה כתיקונה הריהי \u0003קלטה\u0004 \u0005[קולטת]\u0006 את הקרבן לקדושה, לענין זה שאם נפסל ובכל זאת עלה למזבח — לא ירד, אבל מחיצה בהקרבה \u0003שלא כתיקנה,\u0004 כגון בקרבן שהוקדש תחילה לבמת יחיד — \u0003לא קלטה\u0004 \u0005[אינה קולטת]\u0006 אותו המחיצה כלל, ואף אם עלה — ירד. שאלה זו לא נפתרה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ועוד בדין מעילה בקרבנות שנפסלו. \u0003אמר רב גידל, אמר רב: זריקת\u0004 דמו של קרבן שבשעה שנשחט חשב לאכול את בשרו מחוץ לזמנו הראוי, והריהו איפוא \u0003פיגול,\u0004 זריקה זו \u0003אינו מוציא\u0004 (מפקיע) את הקרבן \u0003מידי\u0004 דין \u0003מעילה בקדשי קדשים,\u0004 שהרי לא פסק מלהיקרא \"קדשי ה' \" שכן דין מעילה בקדשי קדשים אינו בטל עד שיותר הקרבן לאכילת הכהנים, וקרבן זה כיון שלא התירתו הזריקה לאכילת הכהנים עדיין דין מעילה עליו. וכן מעשה זריקה זה \u0003אינו מביא\u0004 את הקרבן \u0003לידי\u0004 חלות דין \u0003מעילה\u0004 על האימורים (החלקים המוקרבים על המזבח) מכאן והלאה, \u0003בקדשים קלים.\u0004 שכן זריקת הדם היא המחילה דין מעילה על האימורים בקדשים קלים, וזו כיון שהיתה פסולה — לא הועילה לכך.","ונמסר כי כאשר \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003אביי וקאמר לה להא שמעתא\u0004 \u0005[ואמר את ההלכה הזו\u0006 שאמר רב גידל בשם רב\u0005],\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב פפא לאביי\u0004 על הלכה זו ממה ששנינו במשנה במסכת מנחות: \u0003השוחט את\u0004 קרבן \u0003התודה לפנים\u0004 (בתוך העזרה), כדינה, \u0003ו\u0004אולם \u0003לחמה\u0004 (ארבעים החלות הבאות עם התודה) היה באותה שעה \u0003חוץ לחומה\u0004 — לא קדש בשחיטה זו \u0003את הלחם,\u0004 כיון שבשעת השחיטה היו החלות במקום שאסור לאוכלן.","וכן אם \u0003שחטה\u0004 את התודה \u0003עד שלא\u0004 (בטרם) \u0003קרמו פניה,\u0004 (החלו בהתקשות פני העיסה הנאפית) \u0003בתנור, ואפילו קרמו\u0004 פני \u0003כולן,\u0004 כל החלות, \u0003חוץ מאחת מהן\u0004 — \u0003לא קדש הלחם,\u0004 ואף לא אלו שקרמו פניהם. ואם \u0003שחטה\u0004 את התודה במחשבה לאכול את בשרה או להקטיר את אימוריה \u0003חוץ לזמנה,\u0004 או \u0003חוץ למקומה\u0004 ונעשתה איפוא פיגול — \u0003קדש הלחם\u0004 לענין זה שמועלים בו.","ונסיק: \u0003אלמא\u0004 \u0005[מכאן]\u0006 שמחשבת \u0003פיגול מייתי לה\u0004 \u0005[מביא אותה]\u0006 את הקדשים הקלים בכלל, \u0003לידי מעילה,\u0004 וקשה על דברי אביי בשם רב גידל בשם רב! ונמסר ש\u0003אישתיק\u0004 \u0005[שתק]\u0006 אביי ולא מצא דרך להשיב לרב פפא על שאלתו זו.","ואולם \u0003כי אתא לקמיה\u0004 \u0005[כאשר בא\u0006 אביי \u0005לפני]\u0006 \u0003ר' אבא\u0004 ואמר לו את קושייתו של רב פפא, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבא לאביי: אין זו קושיה, שכן רב גידל אמר שפיגול אינו מביא לידי מעילה בקדשים קלים רק כאשר מחשבת הפיגול היתה \u0003ב\u0004שעת ה\u0003זריקה,\u0004 שרק בשעה זו מחשבת הפיגול פוסלת את הקרבן, ולכן שוב אין יכול לחול דין מעילה עליהם. אבל המשנה במנחות עוסקת במחשבת פיגול בשעת השחיטה, ובשעת הזריקה היתה מחשבתו ראויה, ובמקרה זה זריקת הדם אכן מביאה לידי מעילה בקדשים קלים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרבא\u0004 בשאלה על הסבר זה בדברי רב גידל: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר עולא: קומץ\u0004 המנחה שהוא \u0003פיגול,\u0004 והריהו פסול להקרבה, \u0003שהעלו\u0004 אותו להקטירו \u0003לגבי מזבח\u0004 וכבר שלטה בו אש המזבח — \u0003פקע פיגולו ממנו,\u0004 והריהו כשר להקרבה, ומעתה יש לשאול: בדין זה למדים שמחשבה פסולה אכן מחילה דין פיגול.","\u0003ו\u0004הלא מעשה ה\u0003קמיצה\u0004 במנחות \u0003היינו\u0004 \u0005[הרי זה]\u0006 כמעשה ה\u0003שחיטה\u0004 בקרבנות, וכשם שהקמיצה במנחות די בה כדי לפגל, אף השחיטה בקרבנות כך. ויתקדשו אם כן אימורי קדשים קלים בזריקה שלאחר שחיטה המפגלת ויהיה בהם דין מעילה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרב אשי: מכאן אין להקשות, שכן מה שנאמר בדברי עולא בקומץ המנחה שהוא פיגול, אין כוונתו ששם פיגול חל על הקומץ, אלא שנעשה בו מעשה \u0003איסורא דמייתי\u0004 \u0005[איסור שמביא]\u0006 \u0003לידי פיגול,\u0004 ואולם אין הוא נעשה פיגול גמור אלא כשמחשבת הפיגול היתה בשעת ההקטרה."],["ושואלים על תשובתו של רבא לרב אשי, \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 עולא בהסבר שיטתו: \u0003אם\u0004 את ה\u0003אחרים,\u0004 שיירי המנחה, \u0003מביא\u0004 הקומץ במחשבת חוץ לזמנו \u0003לידי פיגול, הוא עצמו,\u0004 הקומץ, \u0003לא כל שכן\u0004 שנעשה פיגול במחשבה זו. ואם כן הוא הדין לכאורה בקדשים קלים שנשחטו במחשבת פיגול שתהא בהם מעילה!","ומשיבים: \u0003הא נמי איסורא דמייתי\u0004 \u0005[זה גם כן\u0006 אין הכוונה לפיגול ממש, אלא ל\u0005איסור שמביא]\u0006 \u0003לידי פיגול.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 והרי יש מחלוקת חכמים במשנה (במסכת זבחים כט,ב), שלדעת ר' יהודה אם הקדים מחשבת זמן (אכילה שלא בזמנו הראוי של הקרבן, שמחשבה זו מפגלת את הקרבן ומחייבת את האוכלו כרת) למחשבת מקום (אכילה שלא במקומו הראוי, שמחשבה זו אינה מפגלת אלא פוסלת את הקרבן ואין באכילתו כרת) — הרי זה פיגול. ואולם אם הקדים מחשבת מקום למחשבת זמן — אין זה פיגול, אלא פסול בלבד. ואילו לדעת חכמים בשני אופנים אלו — הרי זה פסול בלבד. \u0003ו\u0004בהסבר הדברים \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003אילפא:\u0004 מחלוקת זו אמורה \u0003בשתי עבודות\u0004 שונות, ו","\u0003כגון\u0004 ש\u0003אמר\u0004 בשחיטה: \u0003\"הריני שוחט סימן ראשון\u0004 של הבהמה, (קנה או ושט), על מנת לאכול את בשר הקרבן \u0003חוץ לזמנו, ו\u0004בשחיטת ה\u0003סימן\u0004 ה\u0003שני\u0004 אמר ששוחטו על מנת לאכול את בשר הקרבן \u0003חוץ למקומו, אבל\u0004 אם חשב שתי מחשבות אלו \u0003בעבודה אחת,\u0004 כגון בשחיטת אותו סימן — דכולי עלמא \u0005[לדעת הכל]\u0006 \u0003עירובי מחשבות הואי\u0004 \u0005[הינם],\u0006 ואף לדעת ר' יהודה אין כאן עבודה במחשבת פיגול, הרי שבשחיטה מתפגל הקרבן. ושלא כדברי רב גידל!","השיב רב אשי לרבינא: \u0003הכי נמי\u0004 \u0005[\u0006אכן \u0005כך גם כן],\u0006 כדברים הללו אומר גם רב גידל, שאכן אין בשחיטה כשלעצמה כדי להחשיב את הדבר לפיגול, ו\u0003לכי זריק תיגלי מילתא\u0004 \u0005[\u0006ו\u0005כאשר יזרוק\u0006 את הדם אחר כך \u0005יתגלה הדבר]\u0006 שהפיגול חל משעת שחיטת סימן ראשון. \u0003אי\u0004 \u0005[אם]\u0006 \u0003בעבודה אחת\u0004 עירב שתי מחשבות אלה — לדעת הכל אין זה פיגול ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003בשתי עבודות\u0004 היו שתי המחשבות, מחלוקת חכמים היא אם פיגול או פסול הוא.","ומקשים על כך: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003תודה\u0004 ששנינו שאם שחטה במחשבת חוץ לזמנה קדש הלחם, \u0003נמי\u0004 \u0005[גם כן]\u0006 אין מחשבת חוץ לזמנו מפגלת \u0003עד דזריק\u0004 \u0005[שיזרוק]\u0006 את הדם, ומשיזרוק הריהו פיגול גמור, וקשה לרב גידל איך קדש הלחם, והרי לדעתו שחיטת פיגול אינה מביאה לידי מעילה!","ומסבירים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"קדש\u0004 הלחם\" — לא לענין מעילה אלא \u0003ליפסל, דבעי\u0004 \u0005[שצריך]\u0006 \u0003שריפה\u0004 אחר כך.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 כי אפשר \u0005לסייע לדבריו],\u0006 של רב גידל ממה ששנינו: \u0003הפיגול לעולם מועלין בו. לאו אף על גב דאיזריק\u0004 \u0005[האם לא\u0006 הכוונה היא: \u0005אף על פי ש\u0006כבר \u0005נזרק]\u0006 ה\u0003דם\u0004 אחר שנשחט במחשבת חוץ לזמנו, בכל זאת מועלים בו, ולא יצא מידי מעילה על ידי הזריקה, \u0003ו\u0004הרי זה איפוא \u0003מסייע ליה\u0004 \u0005[לו]\u0006 לרב גידל הסובר כך!","ודוחים: \u0003לא,\u0004 אין להביא מכאן ראיה, שאפשר לומר כי מדובר בברייתא זו כשעדיין \u0003לא זרק\u0004 את \u0003הדם,\u0004 ומשום כך יש בו דין מעילה. ואפשר לומר שאם נזרק הדם, יצא בכך מכלל דין מעילה. ומקשים על דחייה זו: \u0003אי\u0004 \u0005[אם]\u0006 מדובר בברייתא, כשעדיין \u0003לא זרק\u0004 את \u0003הדם, מאי למימרא\u0004 \u0005[מה\u0006 בא \u0005לומר\u0006 בזה\u0005]?\u0006 והלא וודאי לא יצא מידי מעילה, ובכלל \"קדשי ה' \" הוא!","\u0003אלא\u0004 דוחים בצורה אחרת: \u0003לעולם\u0004 מדובר בברייתא באופן \u0003דזריק\u0004 \u0005[שנזרק]\u0006 הדם, \u0003ו\u0004אולם אין להביא ממנה ראיה לדעת רב גידל, שכן \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 הרי היא \u0003ב\u0004קרבן \u0003עולה,\u0004 שנוהג בו דין מעילה אף לאחר זריקה (שהרי אין הזריקה מתירה את בשרו לאכילת הכהנים). ומקשים אף על דחייה זו: \u0003אי\u0004 \u0005[אם]\u0006 מדובר בה \u0003ב\u0004קרבן \u0003עולה,\u0004 אין בה כל חידוש, שהרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא הדבר, שיש בה דין מעילה אף לאחר זריקה, שכן ל\u0003גבוה היא כולה,\u0004 שכולה עולה למזבח, ואין חלק ממנה נאכל."],["\u0003ועוד\u0004 יש להוכיח כדעת רב גידל, \u0003דקתני סיפא\u0004 \u0005[ש\u0006כן \u0005שנה\u0006 התנא ב\u0005סוף] אותה ברייתא:\u0006 \u0003לן דמה\u0004 של בהמת הקרבן, שעבר הלילה בלא שיזרק על המזבח, \u0003אף על פי שחזר\u0004 למחרת היום, וזרקו את הדם על המזבח — \u0003מועלין בו.\u0004","ומעתה נדון בדבר: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שמדובר בברייתא זו \u0003בחטאת\u0004 — \u0003שפיר\u0004 \u0005[יפה],\u0006 שכיון שנפסלה הזריקה בלינת הדם, מועלים בקרבן, כיון שלא הוציאה אותה הזריקה מכלל \"קדשי ה' \". ואולם אם לא היה לן דמה, אין מועלים בה, שכן הזריקה הוציאה את החטאת מכלל מעילה, שמשעה שנזרק דמה כדין הריהי מותרת לכהנים ואין בה דין מעילה.","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שמדובר \u0003ב\u0004קרבן \u0003עולה\u0004 — יש לתמוה: וכי \u0003צריכא למימר\u0004 \u0005[צריך\u0006 הדבר \u0005להיאמר]?\u0006 והלא בעולה בכל אופן אין דין מעילה פוקע, שהרי אינה ניתרת באכילה גם אם נזרק דמה כדין!","ומעירים: \u0003סיפא ודאי מסייע ליה\u0004 \u0005[הסוף\u0006 של הברייתא \u0005ודאי מסייע לו\u0006 לרב גידל\u0005],\u0006 שכן ראיה ברורה היא שזריקה שאינה כשרה אינה מוציאה מידי דין מעילה. ואולם יש לדון ביחס ל\u0003רישא\u0004 \u0005[ההתחלה]\u0006 של הברייתא האומרת כי הפיגול לעולם מועלים בו, \u0003מאי\u0004 \u0005[מה],\u0006 האם גם ממנה יש סיוע לרב גידל, שכן יש לומר \u0003הואיל ומסייע ליה סיפא\u0004 \u0005[לו הסוף]\u0006 של הברייתא, \u0003מסייע ליה נמי רישא\u0004 \u0005[לו גם כן תחילת\u0006 הברייתא\u0005]?\u0006","ודוחים: אפשר לומר שאף \u0003סיפא לאו ודאי מסייע ליה\u0004 \u0005[סוף\u0006 הברייתא \u0005אינו מסייע לו,\u0006 לרב גידל\u0005],\u0006 שכן יש לומר כי זריקה שלאחר לינת הדם אינה מוציאה מידי מעילה, ואולם זריקה שלאחר פיגול מוציאה מידי מעילה, ואם כן אין ראיה לדעת רב גידל. ומסבירים את ההבחנה שבין זריקות אלה: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 נבדלת\u0005]\u0006 הזריקה שלאחר ה\u0003הלנה\u0004 שאינה מוציאה מידי מעילה — \u0003דקעביד\u0004 \u0005[ש\u0006כן \u0005עושה]\u0006 הוא מעשה \u0003בידים\u0004 (ראה עיונים), ומשום כך אפשר לומר ש\u0003לא מהני\u0004 \u0005[לא מועילה]\u0006 ה\u0003זריקה לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מידי מעילה.\u0004","ואולם בזריקה שלאחר פיגול, שהוא פסול הבא במחשבה, ש\u0003לא קא עביד\u0004 \u0005[שאינו עושה]\u0006 דבר \u0003בידים\u0004 — יש מקום לומר ש\u0003מהני ליה\u0004 \u0005[מועילה לו]\u0006 \u0003זריקה לאפוקי\u0004 \u0005[להוציא]\u0006 אותו \u0003מידי מעילה.\u0004","ומציעים עוד: \u0003לימא הא מסייע ליה\u0004 \u0005[האם נאמר\u0006 כי ברייתא \u0005זו מסייעת לו]\u0006 לרב גידל, שכך שנינו: \u0003הפיגול בקדשי קדשים\u0004 — \u0003מועלין בו.\u0004 ונדון בדברים: \u0003לאו אף על גב\u0004 \u0005[האם לא\u0006 מדובר בברייתא זו \u0003אף על פי]\u0004 שכבר \u0003זרק\u0004 את הדם, ולא הועילה הזריקה להוציא מידי מעילה, \u0003ו\u0004אם כן הרי זה \u0003מסייע ליה\u0004 \u0005[לו,\u0006 לרב גידל\u0005]!\u0006 ודוחים: \u0003לא,\u0004 אפשר לומר כי בברייתא זו מדובר כשעדיין \u0003לא זרק.\u0004","ושואלים על כך: \u0003אבל\u0004 לפי זה במקרה שכבר \u0003זרק מאי\u0004 \u0005[מה\u0006 יהא\u0005]\u0006 הדין, לדעת הברייתא? \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003אין מועלין בו.\u0004 ואם כן יש לשאול: \u0003אמאי קתני סיפא\u0004 \u0005[מדוע שנה בסוף\u0006 הברייתא\u0005]\u0006 להבדיל מדין קדשי הקדשים כי \u0003בקדשים קלים\u0004 — \u0003אין מועלין בו!\u0004","שאם אכן יש חלוקה בין זרק ולא זרק, עדיף הוא \u0003ליפלוג ברישא\u0004 \u0005[שיחלק\u0006 התנא בברייתא כבר \u0005בתחילתה,\u0006 בקדשי קדשים עצמם\u0005],\u0006 \u0003וליתני\u0004 \u0005[וישנה]\u0006 באופן זה: \u0003לפני זריקה\u0004 — \u0003מועלין בו, לאחר זריקה\u0004 — \u0003אין מועלין בו!\u0004 ומסכמים: אכן, הדין \u0003ההוא\u0004 שנאמר בסוף הברייתא \u0003ודאי\u0004 ש\u0003מסייע ליה\u0004 \u0005[לו,\u0006 לרב גידל\u0005], ואולם יש לדון: האם\u0006","\u0003לימא\u0004 \u0005[לומר]\u0006 ש\u0003הואיל ומסייע ליה סיפא\u0004 \u0005[לו הסוף\u0006 של הברייתא\u0005]\u0006 \u0003מסייע ליה נמי רישא\u0004 \u0005[מסייעת לו גם כן ההתחלה\u0006 של הברייתא\u0005]?\u0006 ומשיבים: אין זו ראיה גמורה, שכן אפשר לומר, שמדובר בה כשלא זרק עדיין. ובאשר לשאלה מדוע הובאה חלוקה זו שבין קדשי קדשים לקדשים קלים ולא הובאה החלוקה בקדשי קדשים עצמם, יש להשיב כי העדיף התנא לשנות באופן זה משום ש\u0003קדשים קלים\u0004 — \u0003פסיקא ליה\u0004 \u0005[פסוק,\u0006 ברור ומוחלט \u0005לו]\u0006 שבכל אופן קדשים קלים שנתפגלו אין מועלים בהם, בעוד ש\u0003הכא\u0004 \u0005[כאן,\u0006 בקדשי קדשים\u0005]\u0006 — \u0003לא פסיקא ליה\u0004 \u0005[אינו פסוק לו],\u0006 מפני שיש שנוהג בהם דין מעילה אף לאחר זריקה, כבקרבן עולה.","שנינו במשנה בענין מעילה בקדשים שנפסלו כי \u0003כלל אמר ר' יהושע: כל שהיתה לה\u0004 (לבהמת הקרבן) \u0003שעת היתר\u0004 (אכילה) \u0003לכהנים\u0004 לפני שנפסלה — \u0003אין מועלין בה\u0004 עוד, כיון שעיקרה של מעילה היא דווקא בקדשים המוגדרים כ\"קדשי ה' \", שאין בהם צד היתר לאדם, ובשעה שהותר לכהנים, שוב אין הקרבן בדין מעילה, אף שחזר ונפסל אחר כך מאכילה. \u0003ו\u0004אילו \u0003כל שלא היתה לה\u0004 עדיין \u0003שעת היתר לכהנים\u0004 לפני שנפסלה — הרי היא עדיין בכלל \"קדשי ה' \", ו\u0003מועלין בה.\u0004","ומסבירים: \u0003איזוהי שהיתה לה שעת היתר לכהנים?\u0004 — כגון \u0003ש\u0004לאחר שנעשתה בה עבודתה כתיקנה \u0003לנה\u0004 (עבר לילה על הבשר בלא שנאכל, ונעשה בכך נותר), \u0003ו\u0004כן זו \u0003שנטמאת\u0004 בשר הקרבן לאחר שנעשתה בו עבודתו הראויה, \u0003ו\u0004כן \u0003שיצאת\u0004 (שיצא) לאחר עבודתו אל מחוץ לעזרת המקדש — אין בכל אלו דין מעילה. שאף שבשר הקרבן עתה אסור לכהנים, מכל מקום כיון שהיתה שעה, לפני שנפסל הבשר, שהיה מותר באכילה, שוב אינו בכלל \"קדשי ה' \" ואין בו דין מעילה.","\u0003ואיזוהי שלא היתה לה שעת היתר לכהנים?\u0004 — \u0003ש\u0004בזמן ש\u0003נשחטה\u0004 חשב עליה לאוכלה או לזרוק את דמה או להקטיר את אימוריה \u0003חוץ לזמנה,\u0004 \u0003ו\u0004כן אם חשב לעשות כן \u0003חוץ למקומה\u0004 הראוי כדינה, \u0003ו\u0004כן \u0003שקבלו\u0004 את דם הקרבן מי שהם \u0003פסולין\u0004 לעבודה, \u0003ו\u0004כן אם \u0003זרקו\u0004 הפסולים לעבודה \u0003את דמה.\u0004 שבכל אלו, כיון שנפסלה קודם הזריקה (שהיא המתירתה לאכילה), לא היתה שעה שבשר הקרבן היה מותר באכילה, והרי זה בכלל \"קדשי ה' \", ומועלים בו.","ובענין זה מסופר ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 החכם \u0003בר קפרא לבר פדת: בן אחותי, ראה\u0004 (התבונן) \u0003מה\u0004 ש\u0003אתה שואלני למחר בבית המדרש\u0004 בכוונת דברי ר' יהושע שבמשנתנו \"כל שהיה לה שעת היתר לכהנים\": האם \u0003היתר שחיטה שנינו,\u0004 שכיון שנשחטה כתיקנה, בלא פסול, אף שלאחר מכן נפסלה — יצא בכך בשרה מידי דין מעילה."],["\u0003או\u0004 שאין די בשחיטה כתיקנה כדי להגדיר את הקרבן כזה ש\"היתה לו שעת היתר\" אלא אם כן היתה לאחר השחיטה קבלת דם כראוי, והדם עומד עתה להיזרק כדין, והזריקה היא שתוציא את הבשר מידי דין מעילה. ואף שעדיין לא נזרק הדם הריהו נחשב כזרוק, ואם כן \u0003היתר זריקה,\u0004 היא \"שעת היתר\" ש\u0003שנינו. או\u0004 שמא רק אם היתה לאחר מכן גם זריקה בפועל כתיקנה, שהיא המעמידה את בשר הקרבן ב\u0003היתר אכילה\u0004 לכהנים, ומפקיעתו מדין המעילה, היא \"שעת היתר\" ש\u0003שנינו\u0004 במשנתנו. ובעקבות שאלה זו, הובאו דעות חכמים שנחלקו בדבר. החכם \u0003חזקיה אמר: היתר שחיטה שנינו,\u0004 ואילו \u0003ר' יוחנן אמר: היתר אכילה שנינו.\u0004 ודנים בשיטותיהם.","\u0003אמר ר' זירא: לא דייקא מתניתין\u0004 \u0005[אין משנתנו מדוייקת],\u0006 כלומר, אם נדקדק בלשון המשנה ניווכח שהסבר הביטוי \"שעת היתר\" הוא \u0003לא כ\u0004הסברו של \u0003חזקיה ולא כ\u0004הסברו של \u0003ר' יוחנן.\u0004","שכן \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 בפירוט הפסולים שנעשו לאחר שכבר היתה לה שעת היתר: \u0003שלנה\u0004 (ונעשתה נותר), \u0003ושנטמאת\u0004 (בשר הקרבן), \u0003ושיצאת\u0004 (יצא) בשרה אל מחוץ לעזרה. ונדון בדבר: \u0003לאו\u0004 \u0005[האם אין]\u0006 הכווונה ב\"לנה\" — ש\u0003לן\u0004 ה\u0003דם,\u0004 שלאחר שנתקבל בכוס עבר עליו לילה בלא שנזרק. \u0003וקתני\u0004 \u0005[ושנינו]\u0006 שכיון שהיה לה שעת הכושר — שוב \u0003אין מועלין בו,\u0004","\u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שכיון שהיו השחיטה וקבלת הדם כתיקנן, אף שלא נזרק הדם בפועל, די ב\u0003היתר זריקה\u0004 כדי להחשיב את הדבר כ\"שעת היתר\" המפקיעה מדין המעילה, ש\u0003שנינו\u0004 בדברי ר' יהושע. והרי זה שלא כחזקיה ולא כר' יוחנן!","ודוחים דיוק זה: \u0003לא,\u0004 אין המשנה מדברת בלינת הדם שטרם נזרק, אלא ש\u0003לן\u0004 ה\u0003בשר, אבל\u0004 ה\u0003דם\u0004 כבר \u0003איזדריק\u0004 \u0005[נזרק]\u0006 כראוי, ורק אחר כך נפסל הבשר בלינה, ורק \u0003משום הכי\u0004 \u0005[כך]\u0006 שהיתה שעת היתר לאכילה \u0003קתני\u0004 \u0005[שנה]\u0006 ר' יהושע ש\u0003אין מועלין בו.\u0004 ודנים עוד בהסבר כוונת דברי ר' יהושע \"שעת היתר\" מדיוק דברי משנתנו.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003ואיזו היא שלא היתה לה שעת הכושר לכהנים?\u0004 — \u0003שנשחטה\u0004 במחשבת \u0003חוץ לזמנה,\u0004 או במחשבת \u0003חוץ למקומה, ו\u0004כן כ\u0003שקבלו פסולין\u0004 לעבודה את דמה, וזרקו הפסולים \u0003את דמה.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]\u0006 בענין זה של קבלת וזריקת הפסולים, \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא ש\u0003זרקוהו פסולין ו\u0004גם \u0003קבלוהו פסולין\u0004 — על כך יש לתמוה: \u0003למה לי עד דאיכא תרתי\u0004 \u0005[שיש שתים],\u0006 שתי פעולות פוסלות, גם קבלה וגם זריקה שנעשו בפסול, והלא מכיון שקבלו הפסולים כבר נפסל הקרבן!","אלא לאו \u0005[האם לא]\u0006 הכוונה היא ש\u0003קבלוהו פסולין וזרקוהו כשרים, וקתני\u0004 \u0005[ושנה]\u0006 בו ש\u0003מועלין\u0004 (שיש עדיין דין מעילה) \u0003בו,\u0004 והרי זה משום שעדיין לא היתה לו שעת היתר, אבל אם היתה לו שעת היתר, וכגון שקבלוהו כשרים ומותר בזריקה — אין מועלים בו.","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003היתר זריקה שנינו,\u0004 שלא כהסברו של חזקיה ושלא כהסברו של ר' יוחנן.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על פירוש זה של המשנה\u0005]\u0006 \u0003רב יוסף: ואי סלקא דעתך איכא לפלוגי הכי\u0004 \u0005[ואם עולה על דעתך\u0006 ש\u0005יש לחלק כך]\u0006 במשנה, בין קבלוהו פסולים וזרקוהו כשרים לבין קבלוהו כשרים וזרקוהו פסולים, אם כן \u0003הא דתנן התם\u0004 \u0005[\u0006הלכה \u0005זו ששנינו שם\u0006 במשנה במסכת זבחים\u0005]:\u0006 דם קרבן","\u0003חטאת פסולה\u0004 שניתז על הבגד — \u0003אין דמה טעון\u0004 (מחייב) \u0003כיבוס\u0004 הבגד (שלא כדין דם חטאת כשרה שניתז על בגד שהריהו מחייבו בכיבוס), \u0003בין שהיתה לה\u0004 לחטאת זו \u0003שעת הכושר\u0004 (שעת היתר) \u0003ונפסלה\u0004 לאחר מכן, \u0003ובין שלא היתה לה שעת הכושר ונפסלה.\u0004 שכן כיון שעתה היא פסולה — אין דמה שניתז על הבגד מחייב בכיבוס.","ומסבירים: \u0003אי זו היא שהיתה לה שעת הכושר ונפסלה?\u0004 — כגון \u0003שלנה,\u0004 או \u0003שנטמאת, או שיצאה\u0004 אל מחוץ לעזרה.","\u0003איזוהי שלא היתה לה שעת הכושר?\u0004 — \u0003שנשחטה\u0004 במחשבת \u0003חוץ למקומה,\u0004 או במחשבת \u0003חוץ לזמנה, ו\u0004כן כ\u0003שקבלו פסולין\u0004 לעבודה את דמה \u0003וזרקו\u0004 הפסולים לעבודה \u0003את דמה.\u0004","ונברר את דברי המשנה הללו: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר],\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שלשון המשנה הוא בדווקא, שרק באופן ש\u0003קבלוהו פסולין ו\u0004גם \u0003זרקו\u0004 אותו \u0003פסולין\u0004 — \u0003הוא\u0004 ש\u0003אין דמה\u0004 של החטאת הפסולה \u0003טעון כיבוס,\u0004 ונסיק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם לא נעשו גם הקבלה וגם הזריקה על ידי פסולים, וכגון ש\u0003קבלוהו\u0004 כשרים וזרקוהו פסולים, או שקבלוהו פסולים \u0003וזרקו כשרים\u0004 — \u0003דמה טעון כיבוס.\u0004","ואולם מסקנה שכזו אינה נכונה, שהרי \u0003קרי\u0004 \u0005[קרא,\u0006 אמר\u0005]\u0006 \u0003כאן\u0004 בתורה בדין דם החטאת המחייב כיבוס הבגד עליו ניתז: \u0003\"אשר יזה מדמה\u0004 על הבגד אשר יזה עליה תכבס במקום קדוש\" (ויקרא ו, כ), ולמדנו מכאן כי דין זה אינו נוהג אלא בדם החטאת העומד להזאה, \u0003ולא\u0004 בדם החטאת \u0003שכבר הוזה\u0004 דמה? \u0003אלא\u0004 מכאן נלמד כי לשון המשנה בענין דם חטאת הריהי \u0003לאו\u0004 \u0005[לא]\u0006 ב\u0003דוקא,\u0004"],["ואם כן, יש לומר כי \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 משנתנו שנויה בסגנון \u0003לאו דוקא,\u0004 ואין לדייק ממנה שדין מעילה נוהג דווקא כאשר קבלו הפסולים את הדם, אלא הריהו נוהג גם כאשר קבלו כשרים, וזאת משום ש\"היתר לכהנים\" הוא היתר אכילה. \u0003אמר רב אסי\u0004 בדחיית דברי רב יוסף: \u0003אם כן,\u0004 כדבריך שמשנתנו היא שלא בדווקא, יש לשאול: \u0003למה לי למיתני תרתי\u0004 \u0005[לשנות שתים]\u0006 שתי משניות אלה בסגנון שכזה?","\u0003אלא\u0004 יש לומר כי \u0003לעולם\u0004 רק משנה אחת היא השנויה בלאו דווקא, המשנה במסכת זבחים בענין דם החטאת, ואילו משנתנו שבדין ה\u0003מעילה\u0004 הריהי \u0003דוקא,\u0004 ויש לדייק ממנה, ולהסיק ש\"שעת היתר\" הכוונה היא להיתר זריקה.","\u0003ו\u0004אילו במשנה בזבחים שנקטה באופן שקבלו פסולים, אף שכך הוא הדין גם בקבלו כשרים — \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר זה השמיעה לנו]: שקבלת הדם של ה\u0003פסול\u0004 לעבודה \u0003עושה\u0004 בכך את כל הדם, ואף זה שלא קבלו, ל\u0003שיריים,\u0004 שדינו כדין שאריות הדם של הקרבן הכשר לאחר שנזרק מדמו על המזבח.","וללמדנו ש\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 שלאחר ש\u0003קיבל\u0004 ה\u0003פסול\u0004 לעבודה את הדם \u0003וזרק\u0004 אותו על גבי המזבח, עמד \u0003וקיבל\u0004 כהן אחר ה\u0003כשר\u0004 לעבודה מדם קרבן זה \u0003וזרק\u0004 אותו על גבי המזבח — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כלום היא,\u0004 ופעולתו זו של הכהן הכשר אינה נחשבת. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003שיריים נינהו\u0004 \u0005[הם].\u0006","ושואלים על דברים אלה: \u0003והא\u0004 \u0005[והרי]\u0006 בענין זה עצמו \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ריש לקיש מר' יוחנן:\u0004 כהן \u0003פסול, מהו\u0004 דינו לענין \u0003שיעשה\u0004 בזריקתו את שאר הדם ל\u0003שיריים?\u0004","\u0003ואמר ליה\u0004 ר' יוחנן בתשובה: \u0003אין לך דבר שיעשה\u0004 (יחול) בו דין \u0003שיריים, אלא\u0004 כאשר חשב בשעת זריקת מקצת הדם לאכול מן הקרבן מ\u0003חוץ לזמנו\u0004 (מחשבת פיגול) או מ\u0003חוץ למקומו\u0004 (מחשבת פסול). שאף אם זרק את שאר הדם במחשבה הראויה — נחשב דם זה כשיריים, \u0003הואיל\u0004 שזריקה זו במחשבת פיגול או פסול כבר \u0003מרצין\u0004 (קובעים, מחילים) \u0003ל\u0004ענין \u0003פיגולן\u0004 של בשר הקרבן.","ומעתה נעיין בדברי ר' יוחנן: \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 כוונת דבריו, שאין עושה השיריים אלא במחשבת פיגול בלבד, \u0003בר\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004כהן \u0003פסול\u0004 שאינו קובע דין שיריים בקבלתו את הדם, ושלא כדברי רב אסי! ודוחים: \u0003לא,\u0004 אלא \u0003אפילו\u0004 קבלת הדם של ה\u0003פסול\u0004 עושה את הדם שיריים.","ושואלים על כך: \u0003והא\u0004 \u0005[והרי]\u0006 לשון \u0003\"אין לך\u0004 דבר שיעשה שיריים אלא חוץ לזמנו וחוץ למקומו\" \u0003קתני\u0004 \u0005[שנה]\u0006 ר' יוחנן, לומר שבאופנים אלו בלבד יש דין שיריים!","ומשיבים: \u0003הכי קתני\u0004 \u0005[כך אמר],\u0006 זו כוונת ר' יוחנן בדבריו: \u0003אין לך\u0004 בין הקדשים \u0003דבר\u0004 הפסול להקרבה ו\u0003שאינו מרצה ב\u0004קרבן \u0003ציבור,\u0004 \u0003ו\u0004שהוא \u0003עושה שיריים, אלא\u0004 בחושב מחשבת פיגול של אכילת \u0003חוץ לזמנו ו\u0004כן \u0003חוץ למקומו,\u0004 שאף שאינם קרבים הריהם עושים שיריים בקרבן ציבור. ואולם שאר הפסולים כיון שאינם קרבים בקרבן ציבור — גם אינם עושים שיריים. \u0003אבל טמא\u0004 — כיון \u0003דאיתיה\u0004 \u0005[שישנו]\u0006 \u0003בציבור,\u0004 שאם רוב הציבור טמא, מקריבים קרבן אף שהוא בטומאה — הריהו \u0003משוי\u0004 \u0005[עושה]\u0006 את הדם \u0003שיריים,\u0004 ואילו","\u0003שאר פסולין דלא איתנון\u0004 \u0005[שאינם]\u0006 \u0003ב\u0004קרבן \u0003ציבור\u0004 — \u0003לא משוין\u0004 \u0005[אין עושים]\u0006 \u0003שיריים.\u0004 וכוונת דברי רב אסי שאמר שהמשנה במסכת זבחים באה להשמיענו שהפסול עושה שיריים, היתה רק לפסול טמא ולא לשאר הפסולים.","וחוזרים לדון בכוונת דברי ר' יהושע \"שעת היתר לכהנים\". \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: קרבן קדשי קדשים שנשחט במחשבת \u0003הפיגול\u0004 — אין דין המעילה שבו פוקע ו\u0003לעולם מועלין בו.\u0004","ונדון בדבר: \u0003לאו\u0004 \u0005[האם אין]\u0006 המדובר כאן שקיבל את הדם אבל עדיין \u0003לא זרק\u0004 אותו, ללמדנו שדווקא קבלת הדם שנעשתה לאחר מחשבת פיגול אינה מפקיעה את הקרבן מדין מעילה שבו. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שקבלת דם במחשבה הראויה, שהוא עומד לזריקה, מפקיעה את דין המעילה מן הקרבן, והרי איפוא מכאן ראיה ש\u0003היתר זרקה שנינו\u0004 במשנתנו!","ודוחים: \u0003לא,\u0004 אין להביא ראיה מכאן, משום שמדובר פה באופן ש\u0003זרקה\u0004 את הדם על המזבח, ומשמיעתנו הברייתא שאין דין מעילה פוקע אף שכבר נזרק הדם, משום מחשבת הפיגול בשעת השחיטה, אבל אילו היתה זו זריקה כשירה — היה פוקע דין מעילה, והרי זה כהבנה ש\"שעת היתר\" הינה השעה שמותר בה הבשר באכילה (\"היתר אכילה\"), שהיא לאחר זריקת הדם.","\u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש הלשון שבברייתא \u0003\"לעולם\u0004 מועלין\" — \u0003הא קא משמע לן\u0004 \u0005[\u0006הלכה \u0005זו משמיעה לנו]\u0006 הברייתא בכך: שההלכה \u0003כ\u0004דברי \u0003רב גידל.\u0004 ש\u0003אמר רב גידל, אמר רב: זריקת\u0004 דם קרבן קדשי קדשים שנשחט במחשבת \u0003פיגול\u0004 והתפגל בכך — \u0003אינו מוציא\u0004 (מפקיע) את הבשר \u0003מידי מעילה, ו\u0004כמו כן \u0003אינו מביא\u0004 בזריקה זו את אימורי קדשים קלים \u0003לידי\u0004 דין \u0003מעילה.\u0004"],["ומביאים עוד ראיה לפתרון השאלה, מה כוונת דברי ר' יהושע שבמשנתנו \"שעת היתר לכהנים\". \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא, \u0003ר' שמעון אומר: יש נותר\u0004 (בשר קדשים, שעבר הלילה על הדם שנתקבל, בלא שנעשתה עבודתו, ונפסל) \u0003שמועלין\u0004 (שיש דין מעילה) \u0003בו, ויש נותר שאין מועלין בו.\u0004","ומפרט: \u0003כיצד?\u0004 — \u0003לן\u0004 הדם ונזרק רק למחרת, אם נאכל הבשר \u0003לפני\u0004 שנעשתה בדם זה \u0003זריקה\u0004 — עדיין \u0003מועלין\u0004 בו. ואולם אם נאכל \u0003לאחר זריקה,\u0004 אף שנפסל בלינה — \u0003אין מועלין\u0004 בו, שהועילה הזריקה להוציאו מכלל מעילה.","ונדון בדבר, \u0003קתני מיהת\u0004 \u0005[שנה\u0006 ר' שמעון \u0005על כל פנים]\u0006 שאם נאכל הבשר לפני זריקת הדם שלן — \u0003מועלין בו, לאו\u0004 \u0005[האם לא]\u0006 מדובר פה בכגון \u0003דהוה\u0004 \u0005[שהיתה]\u0006 \u0003שהות\u0004 מספקת ביום ויכול היה \u0003למיזרקיה\u0004 \u0005[לזרוק אותו\u0006 דם כראוי\u0005],\u0006 כיון שכבר התקבל הדם בכוס, כדין, \u0003דאי בעי\u0004 \u0005[שאם היה רוצה]\u0006 — \u0003זריק\u0004 \u0005[היה זורק],\u0006 ובכל זאת עדיין מועלים בו, הרי שקבלת הדם בכוס כשלעצמה אינה מפקיעה מדין מעילה, אלא רק זריקת הדם המתירה את הבשר באכילה,","\u0003ושמע מינה\u0004 \u0005[ולמד\u0006 איפוא \u0005מכאן]\u0006 ש\"שעת היתר לכהנים\" \u0003היתר אכילה\u0004 הוא ש\u0003שנינו!\u0004","ודוחים: \u0003לא,\u0004 אין מדובר פה שהיתה שהות ביום לזריקת הדם, אלא בכגון \u0003דקבליה\u0004 \u0005[שקיבל אותו,\u0006 את הדם\u0005]\u0006 ב\u0003סמוך לשקיעת החמה,\u0004 ש\u0003לא היה שהות למזרק\u0004 \u0005[לזרוק]\u0006 אותו ביום. ומשום שלא היה הדם ראוי לזריקה — עדיין מועלים בו, אבל אילו היתה לו שהות ביום לזורקו, ועומד היה לזריקה (\"היתר זריקה\") — היה נפקע בכך מדין מעילה.","ושואלים על כך: \u0003אבל\u0004 אם \u0003היה שהות\u0004 ביום לזרוק את הדם, \u0003מאי\u0004 \u0005[מה]\u0006 הדין לדבריך? \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ששוב \u0003אין מועלין\u0004 בו, אם כן","\u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מהו זה\u0005]\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 ר' שמעון בברייתא זו את ההבחנה בין אכילת הבשר \u0003לפני זריקה\u0004 שעדיין מועלים בו, ולאחר זריקה ששוב אין מועלים בו, \u0003ליתני\u0004 \u0005[שישנה]\u0006 הבחנה יותר מדוייקת, שבין קבלת הדם \u0003קודם שקיעה\u0004 שהיתה לו שהות לזריקה, ולן — שאין מועלים בו, \u0003ו\u0004בין קבלת הדם ש\u0003לאחר שקיעה\u0004 — שעדיין מועלים בו!","ומשיבים: \u0003הכי נמי קתני\u0004 \u0005[\u0006אכן \u0005כך גם כן שנה]\u0006 ר' שמעון, כך צריך להבין את דבריו שבברייתא: \u0003קודם שיראה\u0004 (שיהיה ראוי) \u0003לזריקה\u0004 — יש בו עדיין דין מעילה, \u0003ולאחר שיראה לזריקה\u0004 — אין בו שוב דין מעילה. ומציעים עוד ראיה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בדומה לברייתא הקודמת, \u0003ר' שמעון אומר: יש\u0004 קרבן קדשי קדשים הנפסל במחשבת \u0003פיגול שמועלין בו, ויש פיגול שאין מועלין בו.\u0004","ומפרט: \u0003כיצד?\u0004 — אם נאכל בשרו \u0003לפני זריקה\u0004 של הדם — עדיין \u0003מועלין\u0004 בו. ואולם אם נאכל הבשר \u0003לאחר זריקה,\u0004 אף שנפסל בפיגול — \u0003אין\u0004 \u0003מועלין\u0004 בבשר הקרבן, שהועילה הזריקה להוציאו מכלל מעילה.","ונדון בדבר: \u0003קתני מיהת\u0004 \u0005[שנה\u0006 ר' שמעון \u0005על כל פנים]\u0006 ש\u0003לפני זריקה\u0004 של דם קרבן זה שהתפגל — \u0003מועלין בו, לאו\u0004 \u0005[האם לא]\u0006 מדובר פה בכגון \u0003דהוה\u0004 \u0005[שהיתה]\u0006 \u0003שהות\u0004 מספקת ביום \u0003למיזרקיה\u0004 \u0005[לזרוק אותו\u0006 דם\u0005],\u0006 כיון שכבר התקבל בכוס, כדין, \u0003דאי בעי\u0004 \u0005[שאם היה רוצה]\u0006 — \u0003זריק\u0004 \u0005[היה זורק],\u0006 ובכל זאת מועלים בו, הרי שקבלת הדם בכוס כשלעצמה אינה מפקיעה מדין מעילה, אלא רק זריקת הדם המתירה את הבשר באכילה, \u0003וקתני\u0004 \u0005[ושנה]\u0006 בדינו ש\u0003מועלין בו, ושמע מינה\u0004 \u0005[ולמד\u0006 איפוא \u0005מכאן]\u0006 ש\"שעת היתר\" שאמר ר' שמעון במשנתנו \u0003היתר אכילה\u0004 הוא ש\u0003שנינו\u0004 במשנתנו, שהיא המפקיעה את בשר קדשי הקדשים מדין מעילה!","ודוחים: \u0003לא,\u0004 מדובר בכגון ש\u0003לא הוה\u0004 \u0005[היתה]\u0006 \u0003שהות למיזרקיה\u0004 \u0005[לזורקו]\u0006 את הדם ביום. ומשום שלא היה ראוי לזריקה — עדיין מועלים בו, אבל אילו היתה לו שהות ביום — היה יוצא בכך מדין מעילה. ושואלים על כך: \u0003אבל\u0004 אם \u0003הוה\u0004 \u0005[היתה]\u0006 \u0003שהות\u0004 ביום \u0003למיזרקיה\u0004 \u0005[לזרוק אותו]\u0006 את הדם, \u0003מאי\u0004 \u0005[מה]\u0006 הדין לדבריך? \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר \u0003דנפק\u0004 \u0005[שיצא]\u0006 בכך מדין מעילה, אם כן \u0003מאי\u0004","\u0003איריא\u0004 \u0005[מה שייך,\u0006 מדוע\u0005]\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 ר' שמעון בברייתא זו את ההבחנה בדין הנותר בין האכילה לפני זריקה שעדיין מועלים בו, ו\u0003לאחר זריקה\u0004 ששוב אין מועלים בו, \u0003ליתני\u0004 \u0005[שישנה]\u0006 הבחנה יותר מדוייקת, זו שבין קבלת הדם \u0003קודם שקיעה\u0004 שהיתה לו שהות לזריקה, ולן — שאין מועלים בו, \u0003ו\u0004בין קבלת הדם ש\u0003לאחר שקיעה\u0004 ולן, שכיון ולא היתה שהות לזריקה עדיין דין מעילה בבשר הקרבן!","ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[\u0006אכן \u0005כך גם כן אמר]\u0006 ר' שמעון, שכך צריך להבין את דבריו שבברייתא: \u0003קודם שיראה\u0004 (שיהיה ראוי) \u0003לזריקה\u0004 — יש בו עדיין דין מעילה, ו\u0003לאחר שיראה לזריקה\u0004 — שוב אין בו דין מעילה.","ומציעים עוד ראיה. \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0003שמע]\u0004 ממה ששנינו: \u0003הפיגול בקדשי קדשים\u0004 — \u0003מועלין\u0004 (יש בו דין מעילה). ודנים בכוונת הדברים, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר שכבר \u0003זרק\u0004 את הדם, ונסיק מכאן שבקרבן כשר, כשנזרק הדם — אין מועלים בו, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ש\"שעת היתר\" שאמר ר' יהושע במשנתנו \u0003היתר אכילה\u0004 הוא ש\u0003שנינו,\u0004 שהיא המפקיעה את בשר קדשי הקדשים ממעילה! ודוחים: \u0003לא,\u0004 אין ראיה מברייתא זו, שכן מדובר בה כאשר \u0003לא זרק\u0004 עדיין.","ושואלים: \u0003אבל\u0004 אם \u0003זרק מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יהא הדין ש\u0003אין מועלין בו.\u0004 ואם כן \u0003מאי איריא דתני\u0004 \u0005[מה שייך ששנה]\u0006 בסוף הברייתא ש\u0003ב\u0004אימורי \u0003קדשים קלים אין מועלין בו,\u0004","\u0003ליתני\u0004 \u0005[שישנה]\u0006 ויחלק בבשר קדשי קדשים עצמם, ובאופן זה: \u0003כאן\u0004 שמועלים בהם — הרי זה כשפיגל \u0003לפני זריקה, כאן\u0004 שאין מועלים בהם — הרי זה כשפיגל \u0003לאחר זריקה!\u0004","ומשיבים: אכן אף כך היה יכול לחלק, ואולם \u0003הא\u0004 \u0005[\u0006חלוקה \u0005זו]\u0006 שהביא בין קדשי קדשים לקדשים קלים \u0003אתיא לאשמועינן\u0004 \u0005[באה להשמיענו,\u0006 ללמדנו\u0005]\u0006 כלל זה בדיני המעילה: \u0003כל\u0004 שענינו הוא \u0003לאיתויי\u0004 \u0005[להביא]\u0006 את הקרבן \u0003לידי מעילה,\u0004 כאימורי קדשים קלים, שעד הזריקה אינם בכלל דין מעילה, רק \u0003זריקה כתיקנה\u0004 היא ש\u0003מייתי\u0004 \u0005[מביאה]\u0006 \u0003לידי מעילה.\u0004","ואילו \u0003כל\u0004 זריקה שבאה \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מידי מעילה,\u0004 כבשר קדשי הקדשים — \u0003אפילו\u0004 זריקה \u0003שלא כתיקנה נמי מפקע\u0004 \u0005[גם כן מפקעת]\u0006 \u0003מידי מעילה.\u0004"],["\u0003בשר\u0004 קרבנות \u0003קדשי קדשים\u0004 שמשעה שנזרק דמם, והותרו לכהנים יצאו מכלל המעילה, נשאלה השאלה ביחס אליו האם יש בו דין מעילה במקרה \u0003שיצא\u0004 אל מחוץ לעזרה \u0003לפני זריקת דמים\u0004 וחזר ונכנס.","ונחלקו בדבר, \u0003ר' אליעזר אומר:\u0004 אין זריקה זו נחשבת כלל, ולכן אינה מועילה להוציאו מדין מעילה, ו\u0003מועלין בו. ו\u0004כמו כן \u0003אין חייבין עליו משום פיגול. ו\u0004אף אינו חייב כרת על אכילת בשר אם \u0003נותר\u0004 לאחר זמן אכילתו הראוי. \u0003ו\u0004כן אינו חייב משום \u0003טמא,\u0004 אם אכלו בטומאת הגוף. שמאחר והזריקה לא היתה ראויה, ולא הותר הבשר בזריקה זו לאכילת הכהנים, לא יצא מכלל \"קדשי ה' \", ואין לחייב את האוכלו לאחר זמנו או בטומאה.","ואילו \u0003ר' עקיבא אומר:\u0004 זריקה זו נחשבת אף שיצא הבשר אל מחוץ לעזרה ונפסל. ולכן \u0003אין מועלין בו ו\u0004כן מועילה היא שמעתה חלים עליו כל דיני הקרבן שנזרק דמו כראוי, ולכן \u0003חייבין עליו משום פיגול ונותר וטמא.\u0004","וכראיה לשיטתו זו שהזריקה מועילה אף שיצא הבשר אל מחוץ למקומו, \u0003אמר ר' עקיבא: והרי המפריש\u0004 בהמה ל\u0003חטאתו, ואבדה, ו\u0004חזר ו\u0003הפריש אחרת תחתיה\u0004 (במקומה), \u0003ואחר כך נמצאת הראשונה. והרי שתיהן עומדות\u0004 איפוא להקרבה, ושחט את שתיהן באותו זמן, וזרק את דמה של אחת מהן, ונמצא שהשניה נפסלה להקרבה משום מותר חטאת.","ויש לדון מה דין בשר השניה לענין מעילה, האם \u0003לא כשם שדמה\u0004 של זו שנזרק \u0003פוטר את בשרה\u0004 מדין מעילה, \u0003כך הוא פוטר\u0004 גם את בשר חברתה, שכיון שיכול היה לזרוק את דם כל אחת מהן לפי בחירתו, הרי שתיהן כקרבן אחד, וכדין האחת כך גם דין השניה. ומאחר וכן, נדון בקל וחומר לענין הזריקה בקרבן שיצא בשרו וחזר ונכנס:","\u0003אם פטר\u0004 זריקת דמה של זו \u0003את בשר חברתה מן המעילה, דין\u0004 (קל וחומר) \u0003הוא שיפטר את בשר עצמה\u0004 מדין המעילה אף שיצא אל מחוץ לעזרה!","וכשם שנחלקו ר' אליעזר ור' עקיבא בשאלה אם יש בזריקת הדם של בשר שיצא כדי להפקיע את הבשר מכלל מעילה, כך נחלקו אף בדינם של \u0003אימורי\u0004 (חלקי הקרבן העולים למזבח) של \u0003קדשים קלים שיצאו\u0004 אל מחוץ לעזרה \u0003לפני זריקת דמים,\u0004 האם יש בזריקה זו כדי להחיל עליהם דין מעילה?","\u0003ר' אליעזר אומר:\u0004 אין זריקה זו נחשבת כלל, ומשום כך \u0003אין\u0004 \u0003מועלין בהן. ואין חייבין עליהן משום פיגול נותר וטמא.\u0004 ואילו ר' עקיבא אומר: זריקה זו נחשבת ולכן \u0003מועלין בהן, וחייבין עליהן משום פיגול נותר וטמא.\u0004","ושואלים: \u0003והני תרתי\u0004 \u0005[ואותן שתים],\u0006 שתי המחלוקות שהובאו במשנה, גם בבשר קדשי קדשים וגם באימורי קדשים קלים \u0003למה לי\u0004 לשנותן, והרי מחלוקת אחת היא ביסודה!","ומשיבים: \u0003צריכי\u0004 \u0005[צריכות\u0006 שתיהן להישנות\u0005],\u0006 משום \u0003דאי איתמר\u0004 \u0005[שאם היתה נאמרת]\u0006 המחלוקת רק \u0003בקדשי קדשים, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי דווקא \u0003בהא קא אמר\u0004 \u0005[בזה אמר]\u0006 \u0003ר' אליעזר\u0004 ש\u0003מועלין בו משום\u0004 ש\u0003זריקה כתיקנה מפקא\u0004 \u0005[מוציאה]\u0006 את בשר קדשי קדשים \u0003מידי מעילה\u0004 ואילו זריקה \u0003שלא כתיקנה,\u0004 כגון זו שנעשתה על בשר שיצא אל מחוץ לעזרה — \u0003לא מפקא\u0004 \u0005[אינה מוציאה]\u0006 אותו \u0003מידי מעילה.\u0004","\u0003אבל\u0004 בזריקה האמורה \u0003לאיתויי\u0004 \u0005[להביא,\u0006 להחיל\u0005]\u0006 \u0003לידי מעילה\u0004 על קרבנות שעדיין לא היו בגדר זה, וכגון אימורי קדשים קלים, \u0003מודי\u0004 \u0005[מודה\u0006 הוא\u0005]\u0006 \u0003לר' עקיבא\u0004 ש\u0003אפילו\u0004 זריקה \u0003שלא כתיקנה\u0004 כגון זו \u0003מייתא\u0004 \u0005[מביאה]\u0006 \u0003לידי מעילה. ו\u0004להיפך,","\u0003אי איתמר\u0004 \u0005[אם היתה נאמרת]\u0006 המחלוקת רק \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003קדשים קלים, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי דווקא \u0003גבי\u0004 \u0005[אצל]\u0006 אימורי \u0003קדשים קלים הוא\u0004 ש\u0003אמר ר' עקיבא\u0004 ש\u0003מועלין בהן,\u0004 משום שאולי לענין זה \u0003אפילו זריקה שלא כתיקנה מייתא\u0004 \u0005[מביאה]\u0006 \u0003לידי מעילה,\u0004","\u0003אבל\u0004 בבשר \u0003קדשי קדשים\u0004 שדין הזריקה בהם \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 מדין מעילה \u0003הוא,\u0004 יש מקום לומר שזריקה \u0003שלא כתיקנה\u0004 — \u0003לא מפקא\u0004 \u0005[לא מוציאה]\u0006 \u0003מידי מעילה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו\u0006 התנא במשנתנו\u0005]\u0006 שנחלקו בשני המקרים.","בהסבר שיטת ר' עקיבא במשנה \u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים. \u0003אמר ר' יוחנן: כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' עקיבא\u0004 את שיטתו זו ש\u0003זריקה מועלת\u0004 (מועילה) \u0003ל\u0004בשר קדשי הקדשים או אימורי קדשים קלים ה\u0003יוצא\u0004 אל מחוץ לעזרה לענין המעילה — הרי זה דווקא כ\u0003שיצא מקצתו\u0004 וחלקו נשאר בעזרה, שמתוך שהועילה הזריקה לחלק שנשאר בעזרה, הריהי מועילה אף לחלק שיצא אל מחוץ לה, \u0003אבל\u0004 אם \u0003יוצא כולו\u0004 אל מחוץ לעזרה — במקרה זה \u0003לא אמר ר' עקיבא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אסי לר' יוחנן: כבר לימדוני חבירי שבגולה\u0004 (תלמידי חכמים שבבבל) כי"],["\u0003מחשבין,\u0004 כלומר, חל דין פיגול כשחשב בשעת זריקת הדם להקטיר את האימורים שלא בזמנם, אף \u0003על האבוד,\u0004 האימורים האבודים שאינם לפנינו, \u0003ועל השרוף,\u0004 שאבדו כליל.","\u0003ו\u0004נדון בדבר: \u0003הא\u0004 \u0005[הרי]\u0006 ה\u0003אבוד ו\u0004ה\u0003שרוף לא איתינון\u0004 \u0005[נמצאים]\u0006 \u0003בעולם, ואפילו הכי קתני\u0004 \u0005[כך שנינו]\u0006 ש\u0003מחשבין\u0004 עליהם, לפיגול, ונסיק מכאן שבזמן שיצאו האימורים כולם, והרי הם כמי שאינם לפנינו, תועיל הזריקה (לשיטת ר' עקיבא) לענין המעילה בהם. ושלא כהסברו של ר' יוחנן בשיטת ר' עקיבא.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב אסי הכי\u0004 \u0005[כך],\u0006 האם הוא סבור שאף אם יצאו הבשר והאימורים כולם אל מחוץ לעזרה, לשיטת ר' עקיבא הזריקה מועילה? \u0003הא בעא מיניה\u0004 \u0005[הרי שאל אותו]\u0006 \u0003רב אסי מר' יוחנן\u0004 שאלה זו: אם בשעת עבודת הקרבן \u0003חישב\u0004 הכהן על שיירי הדם מן הזריקה שדינם שהם \u0003נשפכין\u0004 ליסוד המזבח מיד בסמוך לזריקה עצמה, לשופכם \u0003למחר,\u0004 שלא כדינם, \u0003מהו\u0004 שיעשה הקרבן פיגול בכך, וצדדי השאלה: האם מחשבה זו היא כעין מחשבה לזרוק מן הדם הנזרק למחר, והרי זה פיגול. או שמא מאחר שאין זה הדם הנזרק על המזבח, אין זה פיגול.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא\u0004 לרב אסי בתשובה לשאלתו זו: \u0003כבר שנית לנו\u0004 במסכת חולין, בעניין טומאת אוכלים וטומאת נבילות, שדברים שהם עצמם אינם נאכלים, אם הם מחוברים לבשר, הריהם מצטרפים להשלים לשיעור (כביצה) המטמא טומאת אוכלים, ובכלל אלה אף ה\u0003אלל\u0004 (שאריות בשר הדבוקות בעור הבהמה), שאינו נחשב לאוכל, ואינו מיטמא לעצמו בטומאת אוכלין, ואף אינו מצטרף להשלים לשיעור (כזית) המטמא בשר הנבילה. \u0003אלמא\u0004 \u0005[מכאן]\u0006 נסיק ש\u0003האי\u0004 \u0005[זה]\u0006 ה\u0003אלל,\u0004 \u0003כיון דלית ביה מששא\u0004 \u0005[שאין בו ממשות,\u0006 חשיבות עצמית\u0005]\u0006 — \u0003לא קיבל\u0004 \u0005[אין הוא מקבל]\u0006 \u0003טומאה,\u0004 ונלמד מכאן שלדעת רב אסי, כל דבר שאין בו חשיבות דינו כן, ואף","\u0003הני\u0004 \u0005[אותם]\u0006 הדמים ה\u0003נשפכין נמי\u0004 \u0005[גם כן]\u0006 \u0003כיון\u0004 ש\u0003לאיבוד אזלי\u0004 \u0005[הולכים]\u0006 — \u0003בהו\u0004 \u0005[בהם]\u0006 \u0003מחשבה לא מהניא\u0004 \u0005[אינה מועילה]\u0006 שיתפגל הקרבן על ידה. ולפיכך צריך לומר שלדעת רב אסי, כשיצא כולו אל מחוץ לעזרה, והרי הוא עומד לשריפה, וכמי שהולך לאיבוד, אין הזריקה מחילה עליו דין מעילה. וכהסברו של ר' יוחנן בשיטת ר' עקיבא, שלא נאמרה שיטה זו אלא בשיצא חלקו, ולא בשיצא כולו!","ושואלים: ובכל זאת, \u0003אלא\u0004 ברייתא זו \u0003דקתני\u0004 \u0005[ששנה]\u0006 בה שמחשבים \u0003על האבוד ועל השרוף\u0004 הריהי \u0003קשיא\u0004 \u0005[קשה]\u0006 להסבר זה, שכן ממנה נלמד שמועילה המחשבה בזריקה אף על אלה שאינם בעולם כלל! \u0003אמר רבא\u0004 בתשובה לדבר: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן כך לשונה של ברייתא זו: מחשבים \u0003על העומד לאיבוד, ועל העומד לישרף,\u0004 אבל עדיין לא אבד ולא נשרף, והריהו עומד לפנינו, שבאלו פועלת מחשבת הפיגול, אבל לא באלו שכבר יצאו אל מחוץ לעזרה, שאינם נחשבים כעומדים לפנינו.","א ועוד בשיטת ר' עקיבא במשנתנו, שמועילה מחשבת פיגול, וכן לענין מעילה אף שיצא הבשר אל מחוץ לעזרה לפני הזריקה, \u0003אמר רב פפא: לא אמר ר' עקיבא\u0004 את שיטתו זו שה\u0003זריקה מועלת\u0004 (מועילה) \u0003ל\u0004פגל ולפטור ממעילה את ה\u0003יוצא אלא\u0004 רק בזמן \u0003שיצא בשר\u0004 הקרבן, ונזרק עליו הדם, \u0003אבל\u0004 אם יצא ה\u0003דם\u0004 עצמו, אף שחזר ונכנס למקדש, ונזרק — \u0003אין זריקה\u0004 זו \u0003מועלת ליוצא.\u0004","ומביאים ראיה לדברי רב פפא, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003שחט בשתיקה,\u0004 שלא חשב מחשבת פסול בשעת השחיטה, \u0003ויצא\u0004 ה\u0003דם\u0004 מחוץ לעזרה, \u0003אף על פי שחזר\u0004 והכניסו \u0003וזרקו\u0004 — \u0003לא עשה ולא כלום.\u0004 שאם היה הדבר \u0003ב\u0004בשר \u0003קדשי קדשים\u0004 שיצא — עדיין \u0003מועלין בו,\u0004 משום שלא הותר הבשר בזריקה זו, ואם \u0003בקדשים קלים\u0004 — אין זריקה זו מועילה להחיל על אימוריהם דין מעילה, ולכן \u0003אין מועלין בו,\u0004 כמו לפני זריקה זו.","ודנים עוד בשיטת ר' עקיבא. שנינו במשנה שכראיה לשיטתו \u0003אמר ר' עקיבא: הא\u0004 \u0005[הרי]\u0006 מקרה \u0003זה\u0004 של בשר קרבן היוצא אל מחוץ לעזרה לפני זריקה ונזרק עליו הדם, \u0003למה\u0004 הוא \u0003דומה?\u0004 — למפריש בהמה לחטאת, ואבדה, והפריש בהמה אחרת במקומה, ולאחר מכן נמצאה הראשונה, ומעתה הרי יכול הוא לקיים מצוותו בכל אחת, ותיפסל חברתה משום מותר חטאת. שדינן של אלו, שאם נזרק דמה של האחת, הרי כשם שזריקת דמה של זו פוטרת את בשרה מדין מעילה, הרי היא פוטרת בכך אף את בשר חברתה. ומכאן נלמד שאם נפטרת זו (הפסולה) בזריקת דמה של זו הכשרה, בוודאי שזריקת דמו של הקרבן עצמו פוטרת את בשרו שלו מן המעילה, אף שנפסל הבשר ביציאתו אל מחוץ לעזרה.","ובהסבר דברים אלה של ר' עקיבא, \u0003אמר ר' אלעזר: כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' עקיבא\u0004 שזריקת דמה של החטאת האחת פוטרת את השניה מדין מעילה, הרי זה דווקא כאשר נשחטו שתיהן \u0003בבת אחת\u0004 (באותו זמן), וכגון שנשחטו על ידי כהנים שונים, \u0003אבל\u0004 כשנשחטו \u0003בזה אחר זה\u0004 — \u0003לא אמר ר' עקיבא\u0004 שפקע מהשניה דין מעילה, שכן בשעה ששחט את הראשונה, נפסלה השניה כמותר חטאת, ולא היתה לה שעת היתר אכילה לכהנים, ולא פקע ממנה דין מעילה.","ובענין זה מביאים עוד, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 שכך \u0003אמר ר' שמעון: כשהלכתי לכפר פאני, מצאני זקן\u0004 (חכם) \u0003אחד, ואמר לי\u0004 בתמיהה: האם אכן \u0003אומר היה ר' עקיבא\u0004 ש\u0003זריקה מועלת ליוצא\u0004 מן העזרה קודם זריקה ונפסל בכך? \u0003אמרתי לו: הן. וכשבאתי והרציתי דברים\u0004 אלו של הזקן, שהביע תמיהה על כך, \u0003לפני חבירי שבגליל, אמרו לי\u0004 כחיזוק לתמיהת אותו חכם: אכן כיצד יכול ר' עקיבא לומר זאת, ו\u0003הלא פסול הוא\u0004 היוצא, ו\u0003היאך מרצה\u0004 זריקת הדם \u0003על הפסול?\u0004","\u0003וכשיצאתי\u0004 מלפני חכמים ובאתי \u0003והרציתי דברים\u0004 אלה ששאלוני והקשו עלי \u0003לפני ר' עקיבא, אמר לי:\u0004 ואתה \u0003בני, אי\u0004 \u0005[אין]\u0006 \u0003אתה אומר כן\u0004 כשיטתי, שמועילה הזריקה בדין המעילה אף לפסול? \u0003והרי המפריש חטאתו ואבדה, והפריש אחרת תחתיה, ואחר כך נמצאת הראשונה, והרי שתיהן עומדות\u0004 ויכול להקריב כל אחת מהן, ובכך תיפסל חברתה — \u0003מועלין\u0004 (יש דין מעילה) \u0003בשתיהן,\u0004 שהרי הן עדיין בגדר \"קדשי ה' \" הנאמר בדין המעילה. וכמו כן אף אם \u0003שחטן\u0004 את שתיהן, \u0003והרי דמן\u0004 של השתיים הללו \u0003מונח בכוסות\u0004 ועומדת האחת מהן להיזרק על המזבח — \u0003מועלין בשתיהן.\u0004"],["ואם \u0003נזרק דם של אחד מהם\u0004 מהחטאות הללו, האם \u0003אי\u0004 \u0005[אין] אתה מודה שכשם ש\u0006זריקת \u0003דמה\u0004 של אותה חטאת כשם שהוא \u0003פוטר את בשרה מן המעילה, אף יפטור\u0004 את \u0003בשר חבירתה מן המעילה?\u0004","ומעתה נדון: \u0003אם הציל\u0004 דם חטאת אחת את \u0003בשר חבירתה מן המעילה, אף על פי ש\u0004בשר זה הרי \u0003הוא פסול\u0004 (כדין מותר חטאת), \u0003דין\u0004 (קל וחומר) \u0003הוא שיציל\u0004 הדם הנזרק \u0003את בשרה\u0004 של אותה בהמת קרבן שממנה נלקח, אף שנפסל ביציאה אל מחוץ לעזרה!","על תשובתו זו של ר' עקיבא \u0003אמר ריש לקיש משום\u0004 \u0005[בשם]\u0006 \u0003רב אושעיא: תשובה גנובה\u0004 (שאינה שלמה וראויה) \u0003השיבו ר' עקיבא לאותו תלמיד\u0004 (ר' שמעון תלמידו), כי מתוך דבריו אתה לומד שאם שחטן לחטאות הללו \u0003בבת אחת\u0004 — אין \u0005[כן],\u0006 זריקת דמה של האחת מועילה לפטור את בשר חבירתה מן המעילה, אבל אם נשחטו \u0003בזה אחר זה\u0004 — לא. והלא \u0003כיון\u0004 שבין אם נשחטו בבת אחת ובין אם נשחטו בזה אחר זה —","\u0003פסול הוא\u0004 הקרבן האחר, זה שדמו לא נזרק, כמותר חטאת, אם כן \u0003מה לי\u0004 אם היתה שחיטת השתיים \u0003בבת אחת, מה לי\u0004 אם היתה שחיטתן \u0003בזה אחר זה,\u0004 והלא בשני המקרים, לשיטת ר' עקיבא, צריך שתהא זריקת הדם של האחת פוטרת את בשרה של האחרת מדין מעילה?!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 בתשובה לדבריו אלה: \u0003ואתה\u0004 התמה על כך, \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה אומר כן\u0004 שיש להבחין בין אם שחטן בבת אחת שהן כגוף אחד (ותפטור זריקת דמה של זו את בשר האחרת מן המעילה) לבין אם שחטן בזה אחר זה שהן כגופים נפרדים (ולא פוטרת זריקת דמה של זו את בשרה של האחרת), והלא","\u0003אילו הפריש\u0004 אדם \u0003שתי\u0004 בהמות לקרבן \u0003אשמות\u0004 (אשם) שהוא חייב בו, ועשה כן \u0003ל\u0004צורך \u0003אחריות\u0004 (בטחון תשלום חובו), שאם יאבד אחד — יקריב את השני. \u0003ושחט את שניהן, וקדם והעלה\u0004 למזבח להקרבה את ה\u0003אימורין של אחד מהן קודם\u0004 ה\u0003זריקה\u0004 של דמו, אף שסדר ההקרבה הוא שקודם זורקים את הדם ורק אחר כך מעלים את האימורים להקטרה, ואחר כך זרק את דמו של הקרבן השני (שלא עלו אימוריו למזבח), האם במקרה זה \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה מודה ש\u0004אף \u0003אם עלו\u0004 אימוריו של האשם הזה שלא נזרק דמו לראש המזבח — \u0003ירדו\u0004 מן המזבח, בלא שיקטירו אותם.","\u0003ו\u0004מעתה יש לדון בדבר: \u0003אי סלקא דעתך חד גופא\u0004 \u0005[אם עולה בדעתך\u0006 לומר שאף אם נשחטו בזה אחר זה כ\u0005גוף אחד]\u0006 \u0003הוא\u0004 שני הקרבנות הללו, \u0003אמאי\u0004 \u0005[מדוע]\u0006 דינם הוא ש\u0003אם עלו\u0004 — \u0003ירדו? האמר\u0004 \u0005[הרי אמר] עולא: אימורי קדשים קלים שהעלן\u0006 על המזבח \u0003לפני זריקת דם\u0004 אף שעדיין אינם ראויים להקרבה — \u0003לא ירדו,\u0004 ויוקרבו, משום ש\u0003נעשה\u0004 האמורים הללו \u0003לחמו של מזבח\u0004 בעצם ההעלאה!","\u0003אישתיק\u0004 \u0005[שתק]\u0006 ריש לקיש, שלא היתה בפיו תשובה לדברי ר' יוחנן. \u0003אמר\u0004 על כך \u0003ר' יוחנן: קצצתינון לרגלוהי דינוקא\u0004 \u0005[קצצתי את רגליו של התינוק,\u0006 כינוי של ריש לקיש בפי ר' יוחנן\u0005],\u0006 כלומר, שהשיב לו תשובה ניצחת ששמטה את הבסיס לטענתו.","\u0003יש\u0004 ב\u0003מעשה\u0004 (כלומר, בזריקת) ה\u0003דמים\u0004 ש\u0003בקדשי קדשים\u0004 קביעת דין המעילה בהם, גם צד \u0003להקל ו\u0004גם צד \u0003להחמיר. ו\u0004אילו \u0003ב\u0004זריקת דמם של \u0003קדשים קלים כולהו\u0004 \u0005[כולם,\u0006 כל צדדיהם\u0005]\u0006 הריהם רק \u0003להחמיר.\u0004","ומסבירים: \u0003כיצד?\u0004 דין \u0003קדשי קדשים\u0004 הוא ש\u0003לפני זריקת דמים\u0004 — מועלין באימוריהן, חלקי הקרבן העתידים להיקרב על המזבח, \u0003ובבשר\u0004 שעתיד להיאכל על ידי הכהנים. שכן לפני הזריקה, אף הבשר אסור באכילה לכהנים, והכל בכלל ההגדרה \"קדשי ה' \" הקובעת לענין חלות דין המעילה בקדשים. ואילו \u0003לאחר זריקת דמים\u0004 של קדשי קדשים — עדיין \u0003מועלין\u0004 (יש דין מעילה) \u0003באימוריהן,\u0004 שהם בכלל \"קדשי ה' \" שאין בהם היתר אכילה, \u0003ו\u0004אולם \u0003אין מועלין\u0004 עוד בבשר שמותר עתה באכילה לכהנים. נמצא איפוא שזריקת הדם בקדשי הקדשים יש בה צד להקל.","\u0003ו\u0004מצד אחר, הן \u0003על זה\u0004 (האימורים) \u0003ו\u0004הן \u0003על זה\u0004 (הבשר) לאחר זריקת הדם — \u0003חייב\u0004 עליהם \u0003משום פיגול,\u0004 ואם אכל מבשרם במזיד — חייב כרת. וכמו כן חייב משום \u0003נותר\u0004 אם אכלו לאחר זמן אכילתו הראוי, \u0003ו\u0004משום \u0003טמא\u0004 אם אכלם בטומאת הגוף. ו\u0003נמצא\u0004 אם כן, שיש ב\u0003מעשה\u0004 (זריקת) ה\u0003דמים בקדשי קדשים\u0004 צד \u0003להקל ו\u0004צד \u0003להחמיר.\u0004","\u0003ובקדשים קלים כולן,\u0004 כל צידי זריקת הדם הם רק \u0003להחמיר.\u0004 ומפרטים: \u0003כיצד?\u0004 \u0003קדשים קלים לפני זריקת דמים\u0004 — \u0003אין מועלין לא באימורין\u0004 \u0003ולא בבשר,\u0004 ואילו \u0003לאחר זריקת דמים\u0004 — \u0003מועלין באימורין ואין מועלין בבשר.\u0004 נמצא איפוא שזריקת הדם בקדשים קלים החמירה בדין מעילה.","וכמו כן הן \u0003על זה\u0004 (האימורים) \u0003ו\u0004הן \u0003על זה\u0004 (הבשר) \u0003חייבין עליו\u0004 לאחר זריקת הדמים \u0003משום פיגול, נותר, וטמא. נמצא\u0004 איפוא ש\u0003מעשה\u0004 זריקת ה\u0003דמים בקדשים קלים כולן להחמיר.\u0004","שנינו בתחילת המשנה כי אין דין מעילה בבשר קדשי קדשים לאחר שנזרק דמם. ודנים בדבר. \u0003קתני\u0004 \u0005[שנה]\u0006 התנא במשנה כי \u0003\"אין מועלין בבשר\",\u0004 ונדייק מכאן: דווקא \u0003מעילה\u0004 להתחייב עליו כדיני המועל בקרבן ובתשלומים, \u0003הוא דליכא\u0004 \u0005[שאין כאן],\u0006 \u0003הא איסורא איכא\u0004 \u0005[הרי איסור\u0006 אכילה לכהן \u0003יש כאן]! ו\u0004על כך יש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 יש בכך איסור? \u0003הא ממונא\u0004 \u0005[הרי ממון,\u0006 רכוש\u0005]\u0006 של ה\u0003כהן הוא\u0004 בשר קדשי הקדשים לאחר זריקת הדם!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שאין דיוק זה נכון, וטעם הדבר ששנה התנא במשנתנו לשון זו \"אין מועלים\" \u0003משום דנסיב רישא\u0004 \u0005[שנקט בראש,\u0006 בתחילת המשנה\u0005]\u0006 בלשון \u0003\"מועלין\", נסיב סיפא\u0004 \u0005[נקט\u0006 גם \u0005בסוף,\u0006 בהמשך המשנה\u0005]\u0006 לשון \u0003\"אין מועלין\",\u0004 ולכן אין לדייק מלשון זו דבר, ואולם הוא הדין שאין איסור בדבר.","ובהמשך לדיון זה דנים עוד בדברי המשנה, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]\u0006 ששנינו בה: \u0003\"בקדשים קלים כולהו\u0004 \u0005[כולם]\u0006 \u0003להחמיר. כיצד? בשר קדשים קלים לפני זריקת דמים\u0004 — \u0003אין מועלין בהן ובאימוריהן, ואין חייבין עליהן משום פיגול, נותר, וטמא. לאחר זריקת דמים\u0004 — \u0003מועלין באימוריהן ואין מועלין בבשר.\u0004","ונדייק מכאן בדומה לכך: דווקא \u0003מעילה\u0004 בקרבן ובתשלומים, \u0003הוא דליכא\u0004 \u0005[שאין כאן],\u0006 \u0003הא איסורא איכא\u0004 \u0005[הרי איסור\u0006 אכילה לבעלים \u0003יש כאן]! ו\u0004על כך יש לשאול: לאחר זריקת הדם \u0003אמאי\u0004 \u0005[מדוע]\u0006 יש בבשר איסור? \u0003הא ממונא\u0004 \u0005[הרי ממון,\u0006 רכוש\u0005]\u0006 של ה\u0003בעלים הוא,\u0004 ואינו שייך עוד להקדש!","\u0003אמר ר' חנינא:\u0004 מדובר כאן \u0003ליוצאין.\u0004 שיצא בשר הקדשים אל מחוץ למקומם לפני שנזרק הדם, ואחר כך נזרק דמם, ואכן אלה אסורים באכילה. \u0003ו\u0004לשיטת \u0003ר' עקיבא\u0004 שבמשנה למעלה (ו,ב) הסבור כי הזריקה מועילה להוציא מדין מעילה את בשר קדשי הקדשים שיצא אל מחוץ לעזרה \u0003היא\u0004 משנתנו.","וללמדנו באה ש\u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' עקיבא\u0004 את שיטתו זו ש\u0003זריקה מועלת\u0004 (מועילה) להוציא מדין מעילה פיגול נותר וטמא, לא לענין השריפה אמר כן, שיישרף מייד (כשאר קדשים שנפסלו) אלא יש להמתין עד שתעובר צורתו ואז \u0003יוצא\u0004 הוא \u0003לשריפה,\u0004"],["\u0003אבל ל\u0004התירו ב\u0003אכילה\u0004 משום שנזרק הדם, \u0003הוא דלא מרצה.\u0004 חטאת העוף, \u0003מועלין בה מ\u0004שעה \u0003שהוקדשה\u0004 בדיבור להיות קריבה על גבי המזבח, \u0003נמלקה\u0004 — \u0003הוכשרה\u0004 (הותקנה) \u0003להפסל\u0004 מהקרבה \u0003ב\u0004נגיעה שנגע בה \u0003טבול יום\u0004 (הטמא שכבר טבל ועדיין לא העריבה עליו השמש), \u0003וב\u0004נגיעת \u0003מחוסר כפורים\u0004 (הטמא, כגון הזב והמצורע, שכבר טבל ועדיין לא הביא את קרבנות כפרתו), \u0003ו\u0004כן נפסלת \u0003בלינה\u0004 של דמה (אם לא הוזה על קיר המזבח עד שקיעת החמה), או בלינת בשרה (אם לא נאכל ביום ולילה מזמן המליקה).","","","ואם \u0003הוזה דמה\u0004 כדינה — מעתה \u0003חייבין עליו\u0004 בעונש כרת \u0003משום\u0004 \u0003פיגול\u0004 (אם חשב הכהן בשעת המליקה לאוכלה לאחר הזמן הראוי), ומשום \u0003נותר\u0004 (אם נאכלה לאחר זמן אכילתה הראוי), \u0003ו\u0004כן חייב עליה האוכלה כשהוא \u0003טמא,\u0004 ככל האוכל קדשים בטומאה. \u0003ואין בה\u0004 עוד דין \u0003מעילה,\u0004 שכן בהזאת דמה הותרה באכילה לכהנים, ואין היא עוד בכלל \"קדשי ה' \" שבהם נאמר דין מעילה.","\u0003קתני\u0004 \u0005[שנינו]\u0006 במשנה כי משנמלקה חטאת העוף \u0003הוכשרה\u0004 בכך \u0003ליפסל בטבול יום\u0004 \u0003ובמחוסר כפורים ובלינה. ומדייקים:\u0004 \u0003ליפסל\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אבל לטמויי\u0004 \u0005[לטמא]\u0006 שתהיה טמאה ומטמאה דבר אחר בנגיעתה — \u0003לא.\u0004","ומכאן מסיקים כי \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003רבנן\u0004 \u0005[חכמים] היא, דתניא\u0006 \u0005[ש\u0006כן \u0005שנויה ברייתא],\u0006 \u0003אבא שאול אומר: טבול יום\u0004"],["הריהו נחשב \u0003תחלה,\u0004 כלומר, כראשון לטומאה, \u0003ל\u0004ענין בשר ה\u0003קדש,\u0004 שבנגיעתו בקודש הריהו מטמא אותו ועושה אותו שני לטומאה.","ר' מאיר \u0003אומר:\u0004 טבול יום נחשב כשני לטומאה, ולכן כשנוגע בקודש הריהו \u0003מטמא את הקדש\u0004 בדרגה של שלישי לטומאה, \u0003ו\u0004אולם טבול יום הנוגע בתרומה אינו מטמא אותה (שתטמא אחרים בנגיעתה), אלא \u0003פוסל את התרומה\u0004 עצמה שאסורה באכילה. \u0003וחכמים אומרים:\u0004 \u0003כשם שהוא,\u0004 הטבול יום, אינו מטמא אלא \u0003פוסל\u0004 בלבד את \u0003משקה\u0004 ה\u0003תרומה ואוכלי\u0004 (מאכלי) ה\u0003תרומה, כך\u0004 \u0003הוא\u0004 אינו מטמא אלא \u0003פוסל\u0004 בלבד את \u0003משקה\u0004 ה\u0003קדש ואוכלי\u0004 ה\u0003קדש.\u0004 שלדעת חכמים אין טבול יום נחשב אף כשני לטומאה (המטמא את הקודש). נמצא כי משנתנו האומרת כי חטאת העוף שנמלקה נפסלת (ולא נטמאת) בנגיעתו של טבול יום — הריהי שלא כדעת אבא שאול ור' מאיר, אלא כדעת חכמים.","\u0003אמר רבא\u0004 בדחיית הדברים: אין להסיק כי משנתנו אינה כדעת אבא שאול ור' מאיר, שיתכן לומר שאף לדעתם אין טבול יום מטמא את הקודש מן התורה אלא פוסלו בלבד, ואולם \u0003ל\u0004דעת \u0003אבא שאול מעלה\u0004 (תוספת קדושה) \u0003עשו\u0004 חכמים \u0003בקדשים,\u0004 ש\u0003שוינהו רבנן\u0004 \u0005[עשו,\u0006 החשיבו \u0005אותם חכמים],\u0006 שנגיעת \u0003טבול יום\u0004 בהם תחשב כנגיעתו של ה\u0003ראשון\u0004 לטומאה.","ו\u0003ל\u0004דעת \u0003ר' מאיר\u0004 החשיבו חכמים את נגיעת טבול יום בקודש \u0003כ\u0004נגיעתו של \u0003אוכל\u0004 (מאכל) הטמא בדרגת \u0003שני\u0004 לטומאה. ואילו \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 יש להעמיד את דינו של טבול יום על דין תורה, וסבורים הם כי \u0003כיון\u0004 שטבול היום כבר \u0003טבל\u0004 מטומאתו — אף שלא הסתלקה לגמרי טומאתו, כבר \u0003קלש\u0004 \u0005[נחלשה] ה\u0006\u0003טומאה\u0004 שהיתה בו, ומשום כך ל\u0003פסול\u0004 את הקודש בנגיעתו — הריהו \u0003משוי\u0004 \u0005[עושה],\u0006 אבל ל\u0003טמא\u0004 את הקודש בנגיעתו — \u0003לא משוי\u0004 \u0005[אין הוא עושה].\u0006","שנינו במשנתנו בדין חטאת העוף, שאם כבר \u0003הוזה דמה\u0004 — \u0003חייבין\u0004 עליה משום פיגול נותר וטמא, ואין בה דין מעילה. ומדייקים מלשון המשנה: דווקא דין \u0003מעילה הוא דליכא\u0004 \u0005[שאין]\u0006 בה משעת הזאה, \u0003אבל איסורא\u0004 \u0005[איסור]\u0006 ליהנות ממנה — \u0003איכא\u0004 \u0005[יש]\u0006 בה לאחר הזאה. ותמוה הוא: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא ממונא\u0004 \u0005[הרי ממון]\u0006 של ה\u0003כהנים הוא\u0004 לאחר הזאת הדם, והם רשאים לאכול ממנה!","\u0003אמר ר' חנינא\u0004 בהסבר הדבר: מדובר פה \u0003ליוצאין\u0004 מחוץ למחיצתם, מקום אכילתם הראוי, \u0003ו\u0004כשיטת \u0003ר' עקיבא היא\u0004 ש\u0003אמר\u0004 כי ה\u0003זריקה\u0004 של הדם על המזבח \u0003מועלת\u0004 (מועילה) \u0003ל\u0004פטור את ה\u0003יוצא\u0004 מדין מעילה, וחייבים עליו משום פיגול נותר וטמא, ובאה המשנה ללמדנו שמכל מקום \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בת אכילה היא,\u0004 שאסורה באכילה. בודנים עוד בחטאת העוף. מדיני חטאת העוף שלאחר המליקה והזאת הדם לוחצים את העוף על קיר המזבח ודמו מתמצה ויורד אל יסוד המזבח.","ועל כך \u0003אמר רב הונא, אמר רב: מיצוי חטאת העוף\u0004 אף על פי שהוא מצוה, אם לא נעשה — \u0003אינו מעכב\u0004 את הכפרה. \u0003דתני\u0004 \u0005[ש\u0006כך \u0005שנה]\u0006 \u0003רב\u0004 בגירסת משנתנו: \u0003\"הוזה דמה\u0004 חייבין עליה...\", שמשעת הזאה הריהי מכפרת וראויה לאכילה. ומשמע מכאן שאין המיצוי מעכב את הכפרה אלא ההזאה בלבד.","ואילו \u0003רב אדא בר אהבה אמר\u0004 שכך אמר \u0003רב: מיצוי חטאת העוף מעכב. ו\u0004לדעתו \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב\u0004 בגירסת משנתנו: \u0003\"מיצה דמה\u0004 חייבין עליה...\", שרק אז היא מכפרת וראויה לאכילה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לכאורה צריכה להיות מה דעת רב בדין זה, ממה שנאמר בתורה בדין מיצוי הדם \u0003\"והנשאר בדם ימצה אל יסוד המזבח חטאת היא\"\u0004 (ויקרא ה, ט). ודנים בדבר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003רב אדא בר אהבה\u0004 בשיטת רב שהמיצוי מעכב את הכפרה, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"והנשאר בדם ימצה... חטאת היא\"\u0004 — שרק לאחר שנמצה דמה היא נקראת חטאת. \u0003אלא לרב הונא\u0004 הסבור בשיטת רב כי אין המיצוי מעכב, \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"והנשאר\u0004 בדם ימצה... חטאת הוא\"?","ומשיבים: בא הכתוב ללמדנו, \u0003כדתניא דבי\u0004 \u0005[כמו ששנויה\u0006 בברייתא \u0005בבית מדרשו]\u0006 של \u0003ר' ישמעאל: שאם נשאר\u0004 דם בגוף העוף לאחר ההזאה — ימצה, ואולם אין חובה מלכתחילה להשאיר דם לצורך זה, ולכך אם לא נשאר, ולכן גם לא נמצה הדם — אין זה מעכב. \u0003ומאי\u0004 \u0005[ומה]\u0006 משמעות האמור בסוף הפסוק \u0003\"חטאת היא\"?\u0004 — \u0003ארישא\u0004 \u0005[על\u0006 האמור ב\u0005תחילת\u0006 הכתוב\u0005],\u0006 בדין המליקה וההזאה, שאין הקרבן מכפר אלא לאחר שנעשו אלה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: אלא מעתה,\u0004 שכך יש לפרש את האמור \"והנשאר\" — שאם נשאר, אם כן אף \u0003גבי\u0004 \u0005[אצל]\u0006 ה\u0003מנחה דכתיב\u0004 \u0005[שנאמר]\u0006 בה, לאחר שנתפרטו דיניה בקמיצה ובהקטרה על המזבח: \u0003\"והנותרת\u0004 מן המנחה לאהרן ולבניו...\" (שם ב, ג), האם \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תפרש בה, \u0003ש\u0004רק \u0003אם ניתותר\u0004 \u0005[נשאר]\u0006 הריהי ניתנת לכהנים, אבל אין להשאיר מלכתחילה? \u0003וכי תימא: הכי נמי\u0004 \u0005[ואם תאמר:\u0006 אכן \u0005כך הוא גם כן]\u0006 הדין אף במנחה,"],["\u0003ו\u0004אולם אי אפשר לומר כך, שכן \u0003התניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005]\u0006 על האמור בתורה בדין המנחה \"...וקמץ משם מלא קומצו \u0003מסלתה ומשמנה על כל לבונתה\u0004 והקטיר הכהן את אזכרתה המזבחה...\" (ויקרא ב, ב), הדגיש הכתוב \"מסלתה ומשמנה\" ולא אמר \"מסולת ומשמן\", ללמדנו שאין הכהן מקטיר את האזכרה (חלק המנחה המוקטר) אלא אם כן נשארו בה לאחר הקמיצה סולת ושמן ולבונה, \u0003פרט\u0004 (למעט) שאין מקטירים על המזבח בזמן \u0003שחסרה סלתה, וחסרה שמנה, וחסרה לבונתה,\u0004 ומשמע שחייבים להותיר!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לדברי רב אחא בנו של רבא: אכן ככלל נדרשת צורת לשון זו \"והנשאר\" (והדומה לה, כמו \"והנותרת\") — שאם נשאר, ואולם \u0003התם כתיב\u0004 \u0005[שם,\u0006 בפרשת המנחה, \u0005הכתוב]\u0006 הזה \u0003\"והנותרת\"\u0004 (\"והנותרת מן המנחה לאהרן ולבניו...\" שם ג) שהוא \u0003קרא יתירא כתיב\u0004 \u0005[מקרא יתר כתוב],\u0006 שיכול היה לומר \"מן המנחה לאהרן ולבניו...\" בלבד, אלא ודאי בא כתוב זה ללמדנו כי במנחה חובה היא שיוותר, מה שאין כן בחטאת העוף שאפשר לפרש: אם נשאר.","\u0003מתיב אבוה\u0004 \u0005[מקשה אביו]\u0006 של \u0003שמואל לרב הונא\u0004 הסבור שלדעת רב אין מיצוי הדם מעכב, ממה ששנינו במשנה: \u0003אחד\u0004 \u0003חטאת העוף ואחד עולת העוף\u0004 \u0003שמלקן\u0004 או \u0003מיצה דמן\u0004 במחשבה לאוכלן \u0003חוץ למקומן\u0004 הראוי — הרי זה \u0003פסול ואין בו\u0004 חיוב \u0003כרת\u0004 על האוכלן. ואם בשעת המליקה או מיצוי הדם חשב לאוכלן \u0003חוץ לזמנן\u0004 הראוי — הרי זה \u0003פיגול, וחייבין עליו כרת.\u0004 ונדייק: משנה זו עוסקת בחטאת העוף ובעולת העוף, ו\u0003קתני מיהת\u0004 \u0005[שנה\u0006 התנא \u0005על כל פנים]\u0006 יחד עם זה שמלקם אף את זה ש\u0003מיצה\u0004 את \u0003דמן,\u0004 שמחשבת חוץ לזמנו בהן מחילה דין פיגול, והרי איפוא שהמיצוי מעכב!","ומעירים: \u0003הוא\u0004 (אביו של שמואל) זה ש\u0003מותיב לה\u0004 \u0005[הקשה אותה]\u0006 קושיה, \u0003והוא\u0004 עצמו זה ש\u0003מפרק לה\u0004 \u0005[שמתרץ אותה].\u0006 ובאופן זה: דברי המשנה הללו \u0003לצדדין\u0004 (לשני צדדים שונים) \u0003קתני\u0004 \u0005[שנה]\u0006 אותם התנא: שמה ששנינו במליקה מתייחס לחטאת העוף ולעולת העוף, ואילו מה ששנינו במיצוי הדם אינו מתייחס אלא לעולת העוף שאין בה הזאה אלא מיצוי הדם בלבד ובודאי שאינו יכול אם כן לפגל בהזאה.","למעלה הובאו דברי החכם בבית מדרשו של ר' ישמעאל, ועתה דנים ל\u0003גופא\u0004 \u0005[גופה]\u0006 של הלכה זו. \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם של \u0005בית]\u0006 מדרשו של \u0003ר' ישמעאל:\u0004 מן הכתוב בדין חטאת העוף \"והנשאר בדם ימצה אל יסוד המזבח\" (שם ה, ט) למדנו \u0003ש\u0004רק \u0003אם נשאר ב\u0004עוף \u0003דם\u0004 לאחר ההזאה דינו שימצה אל יסוד המזבח. ואולם אין חובה מלכתחילה להשאיר דם בגוף העוף לשם כך, ומכאן הסקנו כי לדעת ר' ישמעאל אין המיצוי מעכב את הכפרה.","ומקשים על כך: \u0003והא תנא דבי\u0004 \u0005[והרי שנה\u0006 החכם \u0005של בית]\u0006 מדרשו של \u0003ר' ישמעאל התם\u0004 \u0005[שם\u0006 במסכת זבחים\u0005]\u0006 בדינן של החטאות הפנימיות כי ה\u0003שיריים מעכבין\u0004 (שאם לא נשפך דם השיריים ליסוד המזבח, אין הקרבן מכפר), ונחלק שם על ר' עקיבא הסבור שאין השיריים מעכבים. \u0003ואמר רב פפא\u0004 באותה סוגיה בהסבר מחלוקתם זו שלא נחלקו בשיירי שאר הקרבנות, אלא \u0003מיצוי\u0004 דמה של \u0003חטאת העוף\u0004 שהם השיריים \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שלדעת ר' ישמעאל הריהו מעכב ולדעת ר' עקיבא אינו מעכב, ומכאן סתירה לשיטתו האמורה למעלה! ומשיבים: \u0003תרי תנאי\u0004 \u0005[שני תנאים]\u0006 הם שחלקו בדבר, \u0003ו\u0004שניהם אמרו דבריהם \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' ישמעאל.\u0004","\u0003עולת העוף מועלין בה\u0004 (יש בה דין מעילה) \u0003משהוקדשה\u0004 בפה לקרבן. ומשעה ש\u0003נמלקה\u0004 עולת העוף — \u0003הוכשרה\u0004 (הותקנה) בכך לענין \u0003ליפסל ב\u0004מגעו של \u0003טבול יום,\u0004 \u0003וב\u0004מגעו של \u0003מחוסר כפורים,\u0004 שהוא הטמא (כזב וכמצורע) שטבל לטהרתו, ואולם עדיין לא הביא את קרבנותיו למחרת יום הטבילה, \u0003ו\u0004כן נפסלת עולת העוף לאחר מליקתה \u0003בלינה\u0004 של דמה. \u0003מיצה\u0004 את \u0003דמה,\u0004 אם חשב הכהן שמלקה בשעת המליקה לאכול מבשרה לאחר זמן אכילתה הראוי, \u0003חייבין עליו\u0004 על אכילתו כרת \u0003משום פיגול,\u0004 וכן אם לא נאכל בתוך זמן אכילתו הראוי, הריהו באיסור \u0003נותר, וטמא\u0004 אם אכלו בטומאת הגוף. \u0003ו\u0004מאחר שבעולת העוף אין שעת היתר כלל שהרי אסורה לעולם באכילה, לכן \u0003מועלין\u0004 (ומתקיימים כל דיני המעילה) \u0003בה\u0004 כל זמן שהיא קיימת \u0003עד\u0004 לזמן \u0003ש\u0004בו היא \u0003תצא לבית הדשן\u0004 מקום שריפתה ותישרף כולה.","\u0003פרים הנשרפים, ושעירים הנשרפים\u0004 — \u0003מועלין בהן מ\u0004שעה \u0003שהוקדשו\u0004 בפה. ומשעה ש\u0003נשחטו\u0004 — \u0003הוכשרו ליפסל בטבול יום ובמחוסר כפורים ובלינה.\u0004 ומשעה ש\u0003הוזה דמן\u0004 — \u0003חייבין עליהן משום פיגול נותר וטמא, ומועלין בהן\u0004 אף בהיותם \u0003בבית הדשן עד שיתיך הבשר\u0004 (יתעכל ויהיה לאפר).","\u0003העולה\u0004 הבאה מהבהמה, \u0003מועלין בה מ\u0004שעה \u0003שהוקדשה.\u0004 ומשעה ש\u0003נשחטה\u0004 — הוכשרה ליפסל בטבול יום, ובמחוסר כפורים, ובלינה. ו\u0003מ\u0004שעה \u0003שנזרק דמה\u0004 על המזבח — \u0003חייבין עליה משום פיגול נותר וטמא. ו\u0004אולם לענין מעילה שוב \u0003אין מועלין בעורות\u0004 של עולות הבהמה, לפי שהם מעתה נכסי הכהנים, ואין הם עוד בכלל \"קדשי ה' \" שבהם נאמר דין המעילה. \u0003אבל מועלין בבשר\u0004 לאחר זריקת הדם, שהרי אין בו חלק לכהנים שכן כולו נשרף על המזבח, והוא בכלל \"קדשי ה' \", ונוהג בהם דין זה \u0003עד שתצא\u0004 כולה \u0003ל\u0004שריפה ב\u0003בית הדשן.\u0004","ה\u0003חטאת, ו\u0004ה\u0003אשם, וזבחי שלמי ציבור\u0004 (שני כבשי העצרת, הבאים בחג השבועות, עם שתי הלחם) — \u0003מועלין בהן מ\u0004שעה \u0003שהוקדשו\u0004 בפה לקרבן. ומשעה ש\u0003נשחטו\u0004 — \u0003הוכשרו\u0004 בכך \u0003ליפסל ב\u0004מגע \u0003טבול יום, ובמחוסר כפורים, ובלינה\u0004 של הבשר אם לא נזרק הדם. ומשעה ש\u0003נזרק דמן\u0004 — \u0003חייבין עליהן משום פיגול נותר וטמא.\u0004 ו\u0003אין מועלין בבשר\u0004 שלהם לאחר שנזרק הדם, שהרי מותר הוא מעתה באכילה לכהנים, ושוב אינו בכלל \"קדשי ה' \", \u0003אבל מועלין באימוריהן\u0004 (בחלק המוקרב על המזבח) \u0003עד ש\u0004יתעכלו על המזבח ו\u0003יצאו\u0004 (אפרם) \u0003לבית הדשן\u0004 לאחר שריפתם על המזבח.","\u0003שתי הלחם\u0004 הבאות בחג השבועות — \u0003מועלין בהן מ\u0004שעה \u0003שהוקדשו\u0004 בפה. ומשעה ש\u0003קרמו\u0004 (התכסה בצקם בקרום) בזמן אפייתם \u0003בתנור\u0004 — הרי זה נחשב כתחילת עשייתם בשחיטה בקדשי קדשים, ונקראים הם משעה זו \"לחם\" ו\u0003הוכשרו\u0004 בכך \u0003ליפסל ב\u0004מגע \u0003טבול יום, ובמחוסר כפורים, ולישחוט עליהן את הזבח\u0004 (כבשי העצרת) הבאים אתם. ומשעה ש\u0003נזרק דמן של\u0004 ה\u0003כבשים,\u0004 כבשי עצרת — \u0003חייבין עליהן,\u0004 על שתי הלחם, \u0003משום פיגול, נותר, וטמא, ואין בהן\u0004 מעתה עוד דין \u0003מעילה,\u0004 שהרי בזריקת דם כבשי העצרת הותרו שתי הלחם באכילה לכהנים.","\u0003לחם הפנים\u0004 אותו עורכים על השולחן שבהיכל מדי שבת — \u0003מועלין בו מ\u0004שעה \u0003שהוקדש.\u0004 ומשעה ש\u0003קרם בתנור\u0004 — \u0003הוכשר\u0004 \u0003ליפסל ב\u0004מגע \u0003טבול יום ובמחוסר כפורים, ולהסדר\u0004 \u0003על גבי השולחן\u0004 שבהיכל.","ומשעה ש\u0003קרבו\u0004 (הוקטרו) \u0003הבזיכין\u0004 של לבונה שניתנו בשבת שעברה על הלחם — \u0003חייבין עליו,\u0004 על לחם הפנים, \u0003משום פיגול\u0004 (אם חשב הכהן בשעת הקטרתם של הבזיכים לאכול למחרת את הלחם), וכן חייבים עליו משום איסור \u0003נותר וטמא. ו\u0004משעה זו שהוקטרו הבזיכים, הותר הלחם באכילה, ושוב \u0003אין בו\u0004 דין \u0003מעילה.\u0004","\u0003המנחות\u0004 — \u0003מועלין בהן מ\u0004שעה \u0003שהוקדשו\u0004 בפה, שהוקדש הקמח לשם מנחה זו. ומשעה ש\u0003קדשו בכלי\u0004 שרת, שהוכנס הקמח בתוך הכלי — \u0003הוכשרו\u0004 בכך לענין \u0003ליפסל ב\u0004מגע \u0003טבול יום, ובמחוסר כפורים, ובלינה.\u0004","ומשעה ש\u0003קרב הקומץ\u0004 של המנחה — \u0003חייבין עליו,\u0004 על המנחות, \u0003משום פיגול\u0004 (אם חשב הכהן בשעת הקמיצה לאכול את שיירי המנחה למחרת, או להקטיר את הקומץ למחרת), וכן חייבים על המנחה משעה זו באיסור \u0003נותר ו\u0004באיסור \u0003טמא. ו\u0004משעת הקמיצה שוב \u0003אין מועלין בשירים\u0004 שהרי מהקמיצה ואילך הריהם מותרים באכילה לכהנים, \u0003אבל מועלין בקומץ,\u0004 שהרי הוא מוקטר לגבוה, \u0003עד שיצא לבית הדשן.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדינו של \u0003הנהנה מאפר תפוח\u0004 (ערימת האפר) \u0003ש\u0004נותרה \u0003על גבי המזבח\u0004 לאחר שהכהן קיים מצות \"תרומת הדשן\" בנטילתו מן הדשן הנמצא שם, אם יש בו עדיין דין מעילה, \u0003רב אמר:\u0004 שוב \u0003אין מועלין בו, ור' יוחנן אמר:\u0004 עדיין \u0003מועלין בו.\u0004","ומסבירים את מחלוקתם: \u0003לפני תרומת הדשן כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שעדיין \u0003מועלין בו,\u0004 שהרי טרם נגמרה מצוותו. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — הרי זה \u0003לאחר תרומת הדשן.\u0004","וטעמם של החולקים: \u0003רב אמר\u0004 כי \u0003אין מועלין בו\u0004 — ש\u0003הרי\u0004 כבר \u0003נעשה מצותו\u0004 וכל השאר אינו אלא להוצאה משם. \u0003ו\u0004אילו \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 שמועלים בו, טעמו: \u0003כיון דכתיב\u0004 \u0005[שנאמר]\u0006 בתורה בדין הוצאת הדשן מהמזבח \u0003\"ולבש הכהן מדו בד\"\u0004 (ויקרא ו, ג), ומעתה \u0003כיון\u0004 ש\u0003צריך\u0004 לעבודה זו \u0003לבגדי כהונה\u0004 (\"מדו בד\") משמע כי \u0003בקדושתיה\u0004 \u0005[בקדושתו]\u0006 עדיין הוא \u0003קאי\u0004 \u0005[עומד].\u0006","ומעירים: \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנתנו: \u0003מועלין בהן עד שתצא לבית הדשן,\u0004 ומשמע שבהיות האפר במזבח עדיין נוהג בו דין מעילה, והרי זה \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003לרב\u0004 הסבור שאין מועלים באפר התפוח! ומשיבים: \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך רב\u0004 כי הכוונה היא \u0003עד\u0004 לזמן \u0003שתראה\u0004 (שתהיה ראויה) להוצאתה \u0003לבית הדשן,\u0004 שהוא משעה שהוציא ממנו את תרומת הדשן, אף שעדיין הוא על המזבח."],["\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על הסבר זה בשיטת רב, ממה ששנינו במשנה במסכת זבחים בדינם של חלקי קרבן העולה שאינם ראויים למזבח (כגון הצמר, העצמות, הגידים, הקרניים והטלפיים) שבזמן שהם מחוברים לבשר הזבח — הריהם עולים על המזבח וקרבים עם הזבח עצמו, אבל אם נפרדו ממנו — אין הם עולים להקרבה. \u0003וכולן,\u0004 בין אם הם מחוברים לבשר הזבח ובין אם נפרדו ממנו, כיון \u0003שפקעו\u0004 (ניתזו) מחום האש \u0003מעל גבי המזבח\u0004 — \u0003לא יחזיר\u0004 אותם הכהן למזבח, \u0003וכן גחלת שפקעה מעל גבי המזבח\u0004 — \u0003לא יחזיר\u0004 אותה הכהן למזבח. ונדייק מכאן: דווקא כאשר פקעה הגחלת מעל המזבח אין מחזירים אותה למזבח, \u0003הא\u0004 \u0005[הרי]\u0006 מכאן שאם היתה עדיין \u0003על גבי המזבח\u0004 ופקעה מצדו האחד לצדו האחר — \u0003יחזיר\u0004 אותה הכהן למקומה.","ומעתה יש לדון בדבר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' יוחנן\u0004 הסבור שאף לאחר תרומת הדשן יש קדושה באפר הנתון על המזבח עד להוצאתו אל מחוץ למחנה — \u0003ניחא\u0004 \u0005[נוח]\u0006 הדבר, שכן אף גחלת זו שעל המזבח בקדושתה עומדת. \u0003אלא לרב\u0004 הסבור כי לאחר תרומת הדשן אין עוד קדושה באפר, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדוע מחזירים גחלת זו למקום ממנו פקעה, והרי אף הגחלת בכלל האפר! ומשיבים: \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך רב\u0004 בתשובה כי \u0003שאני\u0004 \u0005[שונה]\u0006 הוא דינה של \u0003גחלת\u0004 מדין האפר, משום \u0003דאית ביה מששא\u0004 \u0005[שיש בה ממשות],\u0006 ועדיין ראויה היא להקטרה.","\u0003איכא דאמר לה להך גיסא\u0004 \u0005[יש שאומר,\u0006 ששונה \u0005אותה,\u0006 סוגיה זו, \u0005לצד אחר],\u0006 לא כקושיה על שיטת רב אלא כקושיה על שיטת ר' יוחנן, וכך יש לדייק בה: \u0003טעמא\u0004 \u0005[הטעם]\u0006 שיש להחזיר את הגחלת שפקעה ממקומה חזרה למקומה על המזבח, הריהו \u0003משום\u0004 ששונה היא ה\u0003גחלת דאית ביה מששא\u0004 \u0005[ש\u0006כן \u0005יש בה ממשות],\u0006 ונסיק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 איפוא \u0003אפר דלית ביה מששא\u0004 \u0005[שאין בו ממשות],\u0006 \u0003אפילו\u0004 בהיותו \u0003לגבי\u0004 \u0005[אצל,\u0006 על גבי\u0005]\u0006 ה\u0003מזבח\u0004 — אין בו קדושה ו\u0003אין מועלין בו.\u0004 ומעתה נדון בדבר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב\u0004 הסבור שאין קדושה באפר לאחר תרומת הדשן — \u0003ניחא\u0004 \u0005[נוח]\u0006 הדבר, \u0003אלא ל\u0004שיטת \u0003ר' יוחנן\u0004 הסבור שעדיין יש בו קדושה \u0003קשיא\u0004 \u0005[קשה]!\u0006","ומשיבים: \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך ר' יוחנן\u0004 בתשובה כי אין לדייק כך מהמשנה, שכן כך \u0003הוא הדין אפילו\u0004 ב\u0003אפר\u0004 שפקע, \u0003ו\u0004אולם \u0003היינו טעמא דקתני\u0004 \u0005[זהו הטעם ששנה]\u0006 התנא את הדין ב\u0003גחלת\u0004 ולא באפר, כי \u0003קאתי לאשמועינן\u0004 \u0005[הוא בא להשמיע לנו],\u0006 ש\u0003אפילו גחלת דאית בה מששא\u0004 \u0005[ש\u0006כן \u0005יש בה ממשות],\u0006 בכל זאת \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003פקעה\u0004 לגמרי \u0003מעל גבי המזבח\u0004 — \u0003לא יחזיר.\u0004","מדיני המעילה שהמועל משלם קרן וחומש. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בענין \u0003הנהנה מבשר\u0004 קרבנות \u0003קדשי קדשים לפני זריקת דמים,\u0004 או מ\u0003אמורי קדשים קלים לאחר זריקת דמים,\u0004 והריהו חייב בתשלום קרן וחומש (מלבד קרבן אשם מעילות), \u0003רב אמר:\u0004 אותן מעות הבאות על \u0003מה שנהנה\u0004 מקדשי המזבח — \u0003יפלו\u0004 \u0003לנדבה\u0004 לקרבן עולה. \u0003ו\u0004אילו \u0003לוי אמר: יביא\u0004 במעות הללו \u0003דבר שכולו\u0004 עולה \u0003למזבח,\u0004 כגון קטורת, ואל יביא קרבן עולה שאינו עולה כולו למזבח, שהרי עורה של העולה ניתן לכהנים. ודנים בשיטות הללו.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003לוי: מעילה זו\u0004 (תשלומיה) \u0003להיכן הולכת?\u0004 החכמים המכונים \u0003\"הלמידין לפני חכמים\" אומרים: יביא\u0004 בהם \u0003דבר שכולו למזבח,\u0004 ו\u0003מאי ניהו\u0004 \u0005[מהו זה]?\u0006 — \u0003קטרת,\u0004 שכולה עולה למזבח ואין בה שיור.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא גם \u0005כשיטתו]\u0006 של \u0003רב:\u0004 \u0003הנהנה מדמי חטאת ומדמי אשם\u0004 (המעות שהפריש לקנות בהן קרבן חטאת או אשם), והרי זה מעל וחייב בתשלומים, אם בא לשלם \u0003עד שלא\u0004 (בטרם) \u0003קרבה חטאתו\u0004 — \u0003יוסיף\u0004 את סכום כסף המעילה (קרן וחומש) על סכום הכסף הנותר \u0003ויביא\u0004 עתה בהמה משובחת יותר ל\u0003חטאתו.\u0004 \u0003ו\u0004כן הדין באשם, שאם בא לשלם \u0003עד שלא קרבה אשמו\u0004 — \u0003יוסיף\u0004 את סכום המעילה וחומשו \u0003ויביא\u0004 בהמה משובחת יותר ל\u0003אשמו.\u0004 ואם בא לשלם לאחר שכבר \u0003קרב חטאתו\u0004 בטרם נודע לו שמעל — \u0003ילכו\u0004 דמי תשלומי המעילה \u0003לים המלח,\u0004 כלומר, לאבדון. ובאשם אם בא לשלם לאחר ש\u0003כבר קרב אשמו\u0004 — \u0003יפלו\u0004 דמי המעילה \u0003לנדבה\u0004 לקרבן עולה.","ואולם זה \u0003הנהנה מקדשי קדשים\u0004 עצמם \u0003לפני זריקת דמים, ו\u0004זה הנהנה מ\u0003אימורי קדשים קלים לאחר זריקת דמים\u0004 — \u0003מה שנהנה יפלו לנדבה.\u0004 ומסכמת הברייתא את דיני תשלומי המעילה לענין ייעודם: דמי המעילה ב\u0003כל קרבנות המזבח\u0004 — \u0003למזבח;\u0004 דמי המעילה ב\u0003קרבנות קדשי בדק הבית\u0004 — \u0003לבדק הבית;\u0004 דמי מעילה ב\u0003קרבנות צבור\u0004 — \u0003לנדבת צבור.\u0004 נמצא אם כן בברייתא זו כי דמי המעילה בקדשי מזבח הריהם לנדבה, וכשיטת רב.","ושואלים: \u0003הא גופה קשיא\u0004 \u0005[\u0006ברייתא \u0005זו עצמה קשה,\u0006 יש בה עצמה סתירה\u0005],\u0006 שכן בתחילה שנינו בה, שאם הוא בא לשלם את דמי המעילה \u0003עד שלא קרבה חטאתו\u0004 — \u0003יוסיף\u0004 את סכום המעילה וחומשו \u0003ויביא\u0004 בהמה משובחת יותר ל\u0003חטאתו,\u0004 ואם הוא בא לשלם \u0003משקרבה\u0004 כבר \u0003חטאתו\u0004 — \u0003ילכו\u0004 המעות \u0003לים המלח.\u0004 הרי שמחלקת הברייתא בדין בין האופן שעדיין לא הובא הקרבן וטרם התכפרו בו הבעלים ובין האופן שכבר הובא הקרבן והתכפרו בו הבעלים. \u0003ו\u0004אולם בסופה של הברייתא \u0003קתני\u0004 \u0005[שנינו]\u0006 שדמי המעילה ב\u0003כל קרבנות המזבח\u0004 — הריהם מיועדים \u0003למזבח,\u0004 ונשנה דין זה ללא הבחנה, \u0003ולא שנא\u0004 \u0005[ואין שוני]\u0006 בדין בין המקרה \u0003דאיכפור\u0004 \u0005[שהתכפרו]\u0006 כבר ה\u0003בעלים\u0004 בקרבן, \u0003ולא שנא היכא דלא איכפור\u0004 \u0005[ואין שוני היכן שלא התכפרו]!\u0006","ומתרצים: \u0003רישא\u0004 \u0005[תחילתה]\u0006 של הברייתא כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: כל חטאת שכיפרו\u0004 (שהתכפרו) כבר \u0003בעליה\u0004 בחטאת אחרת — \u0003תמות,\u0004 ולכן לשיטתו גם דמי מעילתה של החטאת שהתכפרו בעליה באחרת הולכים לים המלח (שזה כעין מיתה)."],["\u0003ו\u0004אילו \u0003סיפא\u0004 \u0005[סופה]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא, הסבורים שאין חטאת מתה אלא זו שאבדה ונמצאה לאחר שכבר נתכפרו בעליה באחרת?! \u0003אמר רב גביהא\u0004 מ\u0003בי\u0004 \u0005[בית]\u0006 \u0003כתיל לרב אשי\u0004 בתשובה, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר אביי\u0004 בהסבר ברייתא זו: אכן, \u0003רישא\u0004 \u0005[תחילתה]\u0006 כשיטת \u0003ר' שמעון וסיפא\u0004 \u0005[וסופה]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006","\u0003אמר רבא: הכל מודים,\u0004 בין רב ובין ר' יוחנן, \u0003שאם נהנה מבשר קדשי קדשים שנטמא קודם\u0004 ה\u0003זריקה\u0004 של דם הקרבן, \u0003ו\u0004כן אם נהנה \u0003מאימורי קדשים קלין לאחר שהעלן\u0004 על המזבח — אין זו מעילה, ואף לשיטת ר' יוחנן הריהו \u0003פטור\u0004 מקרבן ומתשלומים. שכן שריפתם של קדשי הקדשים שנטמאו, או היפוך באימורי הקדשים הקלים על מנת שיישרפו יפה אינן נחשבות כעבודה.","ותוהים על דברי רבא: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא דבר זה, ואין צורך להשמיענו, שהרי \u0003מאי קא\u0004 \u0005[מה הוא]\u0006 הנהנה מהם \u0003מפסיד\u0004 בכך להקדש, שהרי אין בשר קדשי הקדשים שנטמא ואימורי קדשים קלים שקרבו ראויים מלכתחילה להקרבה?","ומשיבים: חידוש יש בדברי רבא, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כיון שב\u0003בשר קדשי קדשים שנטמא\u0004 — \u0003אית ליה\u0004 \u0005[יש בו]\u0006 \u0003מצות שריפה לכהנים,\u0004 וכן ב\u0003אימורי קדשים קלין\u0004 — \u0003איכא\u0004 \u0005[יש]\u0006 \u0003מצוה להפוכי בצינורא\u0004 \u0005[להפוך במזלג]\u0006 כדי שיישרפו יפה, והיה מקום לומר שינהג בה דין מעילה, לכן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 ש\u0003לא,\u0004 שאין בהם מעילה, שכן מעשים אלה הם דין מיוחד שאמרה התורה שיש לעשות בהם, ואין בכך כדי לחייבו במעילה.","א ומביאים עוד את מה ש\u0003אמר רבא\u0004 בהסבר דברי הברייתא שהובאה למעלה: \u0003הא דאמרת\u0004 \u0005[זה שאמרת]\u0006 בברייתא שאם מעל בדמי החטאת ובא לשלם את דמי המעילה וחומשה לאחר ש\u0003כבר קרבה\u0004 ה\u0003חטאת\u0004 ש\u0003ילכו\u0004 המעות \u0003לים המלח, הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003דאתידע ליה קמי\u0004 \u0005[שנודע לו\u0006 שמעל \u0005לפני]\u0006 ה\u0003כפרה\u0004 בקרבן החטאת. והיתה אפשרות לצרף את דמי המעילה (קרן וחומש) לחטאת, וכיון שלא נעשה כן — הרי אלה הולכים לים המלח. \u0003אבל\u0004 אם נודע לו שמעל רק \u0003לאחר\u0004 ה\u0003כפרה\u0004 — \u0003יפלו\u0004 (יעברו) דמי המעילה \u0003לנדבה,\u0004 ולא יילכו לאיבוד בים המלח. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שכן כלל הוא ש\u0003אין מפרישין מתחלה\u0004 (מלכתחילה, ביודעין) כסף להקדש באופן שילך \u0003לאיבוד.\u0004","המשנה ממשיכה לעסוק בדין המעילה במיני הקדשים. וכאן בקדשים הקרבים כליל על המזבח, ואין בהם חלק לכהנים: \u0003הקומץ\u0004 (החלק הנקמץ מן המנחה ומוקטר על המזבח), \u0003והלבונה\u0004 אותה מקטירים על המזבח עם קומץ המנחה, \u0003והקטורת\u0004 המוקטרת כל יום על מזבח הזהב (המזבח הפנימי), \u0003ומנחת כהנים\u0004 שאינה נקמצת אלא נשרפת כליל על המזבח, \u0003ומנחת כהן משיח\u0004 (הכהן הגדול, המשוח בשמן המשחה) המביא בכל יום מנחת חביתין, \u0003ומנחת נסכים\u0004 (מנחה הבאה עם קרבן שיש בו נסכים) שעולה כליל על המזבח — דינם של אלה ש\u0003מועלין בהם מ\u0004שעה \u0003שהוקדשו\u0004 בפה.","\u0003קדשן בכלי,\u0004 שניתנו בכלי השרת הראוי להם — \u0003הוכשר\u0004 (הוכן) בכך לענין \u0003ליפסל\u0004 מכאן ואילך \u0003ב\u0004מגעו של \u0003טבול יום, וב\u0004מגעו של \u0003מחוסר כפורים,\u0004 שהוא הטמא (כזב וכמצורע) שטבל מטהרתו, ואולם עדיין לא הביא את קרבנותיו לכפרתו, \u0003ו\u0004כן להפסל \u0003בלינה,\u0004 אם לא הוקטרו עד הבוקר כדינם, וחייבים על אכילתם משום איסור \u0003נותר\u0004 (אם נותרו לאחר זמנם), \u0003ו\u0004משום איסור אכילת קדשים בטומאה כשהאוכל \u0003טמא\u0004 בטומאת הגוף. אבל דין \u0003פיגול אין בה\u0004 בכל אלה, שאם חשב בשעת נתינתן בכלי להקטירן לאחר זמנן הראוי — אינו חייב.","וטעם הדבר, ש\u0003זה הכלל\u0004 בדין הפיגול: \u0003כל\u0004 הקדש \u0003שיש לו מתירין,\u0004 שיש דבר אחר שהקטרתו מתירה אותו לאכילת מזבח או לאכילת אדם — \u0003אין חייבין עליו משום פיגול ונותר וטמא עד שיקריבו\u0004 ה\u0003מתירין\u0004 אותו כראוי להם.","\u0003וכל שאין לו מתירין\u0004 כגון הקומץ והלבונה שהם עצמם מתירים, ואין דבר אחר המתיר אותם, \u0003כיון שקידש בכלי\u0004 — \u0003חייבין עליו משום נותר וטמא, ופיגול אין בה.\u0004"],["שנינו במשנה שחייבים על אכילת הנותר או בטומאת הגוף מן הקדשים בין בדבר שיש לו מתירים (משיקרבו מתיריו), ובין בדבר שאין לו מתירים. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין אלה הדברים,\u0006 מה מקורם בתורה\u0005]?\u0006 ומשיבים: לימוד מיוחד יש לדבר, וכפי \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003יכול\u0004 יהא הדין ש\u0003אין חייבין משום\u0004 אכילת קדשים ב\u0003טומאה אלא בדבר שיש לו מתירין,\u0004 כשם שהוא בדין פיגול,","\u0003ו\u0004מצד הסברה נראה כן, שהרי \u0003דין\u0004 (קל וחומר) \u0003הוא:\u0004 \u0003ומה\u0004 דין אכילת \u0003פיגול שהוא\u0004 חמור מאיסור אכילת הקדשים בטומאה, שהרי החיוב על אכילת פיגול קיים אף \u0003בידיעה אחת\u0004 (שנודע לאוכל שהינו פיגול, בין לפני אכילתו ובין לאחר אכילתו). \u0003ו\u0004עוד, ש\u0003קרבנו קבוע,\u0004 שהאוכל פיגול בשגגה מביא לחטאתו כבשה או שעירה (והוא חמור מקרבן עולה ויורד שמשתנה בהתאם למצבו הכספי של האוכל). \u0003ולא הותר מכללו,\u0004 שאיסור אכילת פיגול הריהו איסור מוחלט, ואילו טומאה שהותרה בציבור — \u0003אין חייבין\u0004 בה \u0003אלא על דבר שיש לו מתירין.\u0004","אם כן איסור האכילה ב\u0003טומאה,\u0004 שהוא קל מאיסור אכילת הפיגול, \u0003ש\u0004כן חייבים על האכילה בטומאה רק כש\u0003היא בשתי ידיעות\u0004 (שידע האוכל בתחילה שהוא טמא, ונשכחה ממנו ידיעה זו ואכל בטומאתו, ולאחר מכן נודע לו שוב שהוא טמא), \u0003ו\u0004עוד, \u0003קרבנו\u0004 של האוכל קדשים בטומאה אינו קבוע, אלא הריהו \u0003עולה ויורד,\u0004 \u0003והותרה מכללה,\u0004 כאשר רוב הציבור טמא — \u0003אינו דין שלא יהא חייב אלא על דבר שיש לו מתירין?!\u0004","לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב) בדינו של הטמא האוכל בקדשים: \u0003\"אמר אלהם לדרתיכם כל איש אשר יקרב מכל זרעכם\u0004 אל הקדשים אשר יקדישו בני ישראל לה' וטומאתו עליו ונכרתה הנפש ההיא\" (ויקרא כב, ג) — \u0003בכל הקדשים\u0004 (בין אלה שיש להם מתירים, ובין אלה שאין להם מתירים) \u0003הכתוב מדבר.\u0004 ומעתה יש לדון: \u0003יכול יהו חייבין עליהן מיד\u0004 משעה שהקדישם בפיו, לפני שהתקדשו בכלי שרת? — \u0003תלמוד לומר: \"אשר יקרב\",\u0004 ומשמעה של קריבה זו הריהי נגיעה.","ועל כך \u0003אמר ר' אלעזר: וכי יש נוגע שהוא חייב\u0004 כרת על נגיעתו?! אלא \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד,\u0004 איך נפרש כתוב זה \"אשר יקרב\"? — עד שיוכשר להיות מוקרב. והרי זה בא ללמדנו שאין חייב על אכילת הקדשים בטומאה אלא בכשרים להקרבה. ומכאן, ש\u0003כל דבר שיש לו מתירין\u0004 — \u0003אינו חייב עד שיקרבו מתירין, וכל דבר שאין לו מתירין\u0004 — \u0003אינו חייב עד שיקדש בכלי.\u0004","\u0003א משנה\u0004 משנה זו (שנשנתה במסכת תמורה), נשנית כאן בשל דיני מעילה שבה. המשנה עוסקת בדין \"חמש חטאות המתות\".","שלוש מהן, ה\u0003ולד\u0004 הנולד לקרבן \u0003חטאת, ו\u0004כן הבהמה שהיא \u0003תמורת חטאת, ו\u0004כן קרבן ה\u0003חטאת שמתו בעליה\u0004 קודם שקרב בין אם כבר נתכפרו בעליהן באחרת, בין לא נתכפרו — \u0003ימותו. ו\u0004אילו השתים האחרות, החטאת שאבדה ונמצאה לאחר","\u0003שעיברה\u0004 (עברה) \u0003שנתה\u0004 (כי אין החטאת באה אלא בתוך שנה מאז נולדה), \u0003ו\u0004כן החטאת \u0003שאבדה ונמצאת\u0004 לאחר מכן כשהיא \u0003בעלת מום, אם משכיפרו\u0004 (התכפרו) \u0003הבעלים\u0004 כבר בהקרבת חטאת אחרת — \u0003תמות, ו\u0004כן דינה ש\u0003אינה עושה תמורה,\u0004 כלומר, אם המירו עליה בהמת חולין — אין זו תמורה. שמאחר שהיא פסולה ונתכפרו הבעלים באחרת, שאינה נחשבת לא כקדושת הגוף למזבח ולא כקדושת דמים להתפיס אחרת בה, לכך אין בה דין תמורה. \u0003ולא נהנין\u0004 ממנה לכתחילה, אבל אם נהנים ממנה — \u0003לא מועלין\u0004 בה."],["\u0003ואם עד שלא כיפרו\u0004 (התכפרו) \u0003הבעלים\u0004 באחרת — הרי דינה של זו שנמצאה לאחר שעברה שנתה ש\u0003תרעה עד שתסתאב\u0004 (שיפול בה מום הפוסלה מהקרבה), \u0003ותמכר ויקחו (ויביאו) בדמיה אחרת,\u0004 ושל זו שאבדה ונמצאה בעלת מום, שתימכר מיד, ויביא בדמיה אחרת. \u0003ו\u0004כן דינה של זו ושל זו שהיא \u0003עושה תמורה\u0004 אם המירו בה בהמת חולין, \u0003ו\u0004הנהנים ממנה \u0003מועלין בה.\u0004","המשנה דנה בתחילתה בנפרד בדינן של שלוש מכלל חמש החטאות המתות (ולד החטאת, תמורת החטאת, וחטאת שמתו בעליה), ובסופה בדינן של השתיים האחרות (שאבדה ונמצאה לאחר שעברה שנתה, ושנמצאה בעלת מום) בנפרד. ושואלים: \u0003מאי שנא רישא, דלא קא מיפלגי\u0004 \u0005[\u0006ב\u0005מה שונה תחילת\u0006 המשנה, \u0005שאין הן,\u0006 החטאות המתות, \u0005חלוקות]\u0006 ובכל אופן הן מתות, \u0003ומאי שנא סיפא דקא מיפלגי\u0004 \u0005[ו\u0006ב\u0005מה שונה סוף\u0006 המשנה, בדין שתי החטאות הנוספות, שהרי הן \u0005חלוקות\u0006 בדינן\u0005]?\u0006","ומשיבים: ב\u0003רישא\u0004 \u0005[תחילת]\u0006 המשנה, בדינן של השלוש הראשונות — \u0003פסיקא ליה\u0004 \u0005[פסוקה לו,\u0006 קבוע\u0005]\u0006 דינן של אלה, שאין מקום לחלק בהן, ואילו ב\u0003סיפא\u0004 \u0005[סוף,\u0006 המשך\u0005]\u0006 המשנה, בדינן של השתיים האחרות — \u0003לא פסיקא ליה\u0004 \u0005[אינה פסוקה לו]\u0006 דינן, שהרי תלוי הוא אם התכפרו הבעלים.","ושואלים עוד: ו\u0003הא תנא ליה גבי\u0004 \u0005[\u0006ו\u0005הרי\u0006 כבר \u0005שנה אותה\u0006 משנה \u0005אצל,\u0006 בענין\u0005]\u0006 \u0003תמורה,\u0004 שכן משנה זו כלשונה, מופיעה אף במסכת תמורה (בתחילת פרק רביעי), ומדוע שב ושנה אותה כאן במסכת מעילה? ומשיבים: \u0003תנא התם\u0004 \u0005[שנה\u0006 משנה זו \u0005שם\u0006 במסכת תמורה\u0005]\u0006 משום דין ה\u0003תמורה\u0004 השנוי בה, ואגב כך אף שנה בה דין המעילה. \u0003תנא הכא\u0004 \u0005[\u0006חזר ו\u0005שנה\u0006 אותה \u0005כאן]\u0006 \u0003משום\u0004 דין \u0003מעילה\u0004 השנוי בה, ואגב כך גם שנה בה את דין התמורה.","נזיר המשלים את ימי נזירותו חייב בשלושה קרבנות: חטאת, עולה ושלמים. ודנה המשנה בענין \u0003המפריש מעות ל\u0004קרבנות אלו של \u0003נזירותו,\u0004 ולא פירש אלו מהם לחטאת, אלו לעולה ואלו לשלמים, שמאחר ואין ייעודם ידוע \u0003לא נהנין\u0004 מהן לכתחילה, \u0003ו\u0004אולם אם עבר ונהנה מהן, \u0003לא מועלין\u0004 בהם (אין מתחייבים בהם בדיני המעילה). וטעם הדבר: \u0003מפני שהן\u0004 (המעות הללו) \u0003ראוין לבא\u0004 (להביא מהן) \u0003כולן\u0004 קרבן \u0003שלמים,\u0004 ובשלמים אין דין מעילה לפני זריקת דמם, ואם","\u0003מת\u0004 הנזיר \u0003והיו לו מעות סתומין,\u0004 שלא פירש אלו מהן מיועדות לחטאת, לעולה ולשלמים — \u0003יפלו\u0004 (יועברו) כל המעות \u0003ל\u0004הקרבת עולות \u0003נדבה.\u0004 ואם מת הנזיר והיו לו \u0003מעות מפורשים\u0004 שאמר במפורש לאיזה קרבן הן מיועדות, \u0003דמי חטאת\u0004 — \u0003ילכו לים המלח\u0004 לאבדם, שלא יבואו בני אדם ליהנות מהן כלל, שדמי חטאת שמתו בעליה \u0003לא נהנין\u0004 מהן, \u0003ו\u0004אולם אם לא הוליכום לים המלח לאבדם ועברו ונהנו מהן — \u0003לא מועלין\u0004 בהן.","\u0003דמי עולה\u0004 — \u0003יביאו\u0004 בהם \u0003עולה\u0004 (עולת נדבה), \u0003ומועלין בהן. דמי שלמים\u0004 — \u0003יביאו\u0004 בהם \u0003שלמים\u0004 (שלמי נדבה), \u0003ונאכלין ליום אחד\u0004 בלבד, כדין שלמי נזיר שזמן אכילתם יום ולילה בלבד, שלא כשאר שלמים שזמן אכילתם הוא שני ימים ולילה אחד. \u0003ו\u0004שלמים אלה \u0003אין טעונין\u0004 (חייבים בהבאת) \u0003לחם,\u0004 כשלמי נזיר החייבים בהבאת לחם אתם, שהרי בהבאת הלחם עם שלמי הנזיר נאמר \"ונתן על כפי הנזיר\" (במדבר ו, יט), וכאן הרי מת הנזיר. ג גמרא שנינו במשנתנו בדינם של המעות שהופרשו לקרבנות הנזיר ולא פורש בהן איזו לשלמים ואיזו לעולה ולחטאת שאין בכל המעות דין מעילה, משום שיש בכללן מעות שלמים שאין בה דין מעילה עד לאחר זריקת דמם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ריש לקיש: וליתני נמי\u0004 \u0005[ושישנה\u0006 התנא \u0005גם כן]\u0006 דין נוסף בדומה לזה: \u0003המפריש מעות ל\u0004צורך הבאת \u0003קינים\u0004 (קרבנות הבאים מזוג עופות, תורים או בני יונה, אחד לחטאת ואחד לעולה) שהוא חייב בהבאתם, וכגון היולדת והמצורע ולא פירש אלו מהן לחטאת ואלו לעולה —","\u0003לא נהנין\u0004 לכתחילה במעות הללו, \u0003ו\u0004אולם אם עברו ונהנו \u0003לא מועלין\u0004 בהן. וטעם הדבר: \u0003מפני שהן\u0004 (המעות הללו) \u0003ראוין להביא\u0004 מהן \u0003תורין ש\u0004עדיין \u0003לא הגיע\u0004 עדיין \u0003זמנן\u0004 (שאין התורים כשרים אלא כשהם גדולים) \u0003ובני יונה ש\u0004כבר \u0003עבר זמנן\u0004 (שאין בני היונה כשרים אלא כשהם קטנים), שמאחר ואינם ראויים להקרבה לא נהנים ולא מועלים בהם!","\u0003אמר רבא\u0004 בתשובה: לא נשנה דין זה במשנתנו, שכן אין דין המפריש מעות לקינו כדין המפריש מעות לנזירותו. שהרי \u0003אמרה תורה ב\u0004מפריש לגמר ימי נזירותו \u0003מעות סתומין: הבא\u0004 ממעות אלה בין השאר גם קרבן \u0003שלמים,\u0004 ומאחר ויכול לקנות בכולן שלמים, דינם כדין השלמים שאין מועלים בהם. ואולם המפריש מעות לקינו, האם \u0003אמרה\u0004 בו ה\u0003תורה: הבא\u0004 ממעות אלה \u0003תורין שלא הגיע זמנן?\u0004 והלא אלה \u0003אינן ראויין\u0004 כלל \u0003למזבח!\u0004 אלא ודאי אין לומר במעות הללו שהן מיועדות לדבר שאין בו מעילה.","\u0003ר' שמעון אומר:\u0004 לענין המעילה דינו של \u0003הדם\u0004 הבא מן הקרבנות ונזרק על המזבח — שהריהו \u0003קל בתחלה וחמור בסופו.\u0004 ואילו דין יינות ה\u0003נסכין\u0004 הבאים עם הקרבנות לענין מעילה — יש \u0003חומר בתחלתן וקל בסופן.\u0004","ומפרטים: ה\u0003דם, בתחלתו,\u0004 כלומר, קודם שנזרק על המזבח — \u0003אין מועלין\u0004 בו. ואולם בסופו, לאחר שנשפכו שייריו אל יסוד המזבח ו\u0003יצא\u0004 דרך תעלה שעברה במקדש \u0003לנחל קדרון\u0004 שבתחתית הר הבית — \u0003מועלין בו\u0004 מדברי חכמים. ואילו ה\u0003נסכין, בתחלתן,\u0004 משעה שהוקדשו למצוותם — \u0003מועלין בהן.\u0004 ואילו בסופם, כאשר ירדו לשיתין (יסודות המזבח) ומשם יצאו החוצה — שוב \u0003אין מועלין בהן,\u0004 שכן כבר נעשתה מצוותם, ופקעה קדושתם. שנינו במשנתנו כי מועלים בדם הקרבנות משעה שירד לנחל קדרון. ובענין זה \u0003תנו\u0004","\u0003רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מועלין בדמים\u0004 של הקרבנות משירדו לנחל קדרון, אלו \u0003דברי ר' מאיר ור' שמעון. וחכמים אומרים: אין מועלין\u0004 בהם.","ומבררים: והלא הדם קדוש בקדושת הקרבן, ואם כן \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם של מי שאומר]\u0006 ש\u0003אין מועלין\u0004 בו? \u0003אמר עולא:\u0004 אין הדם קודש אלא חולין, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"כי נפש הבשר בדם היא \u0003ואני נתתיו לם\u0004 על המזבח לכפר על נפשותיכם\" (ויקרא יז, יא), ו\"לכם\" משמע: \u0003שלכם הוא,\u0004 שאין הוא קנין ההקדש. \u0003דבי\u0004 \u0005[\u0006החכם \u0005של בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]\u0006 בדומה לכך, זה שנאמר בדם \u0003\"לכפר\"\u0004 — הרי זה בא להורות כי \u0003לכפרה נתתיו, ולא למעילה.\u0004","ו\u0003ר' יוחנן אמר\u0004 בטעם הדבר, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי הדם הוא בנפש יכפר\"\u0004 (שם), ו\"הוא\" משמעו: בהווייתו יהא, שדינו \u0003לפני כפרה כ\u0004דינו \u0003לאחר כפרה הוא. מה לאחר כפרה\u0004 לדעת הכל \u0003אין בו\u0004 עוד \u0003מעילה,\u0004 שהרי כבר נעשתה מצוותו — \u0003אף לפני כפרה אין בו מעילה.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ו\u0006שמא \u0005אמור]\u0006 על בסיס השוואה זו של לפני כפרה לאחר כפרה, להיפך: \u0003מה לפני כפרה\u0004 — \u0003יש בו מעילה, אף לאחר כפרה\u0004 — \u0003יש בו מעילה!\u0004","ודוחים: אין זה מסתבר לומר כן, \u0003וכי יש לך דבר שנעשית מצותו ו\u0004עדיין \u0003יש בו מעילה?\u0004 ותוהים על כך: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא,\u0004 וכי אין דבר כזה?!"],["ו\u0003הרי תרומת הדשן,\u0004 (אפר הקרבנות שנשרפו כבר על המזבח), שהרי זה דבר \u0003שנעשה מצותו, ו\u0004בכל זאת \u0003יש בו\u0004 עדיין דין \u0003מעילה!\u0004","ומשיבים: אין ללמוד מדין תרומת הדשן לענין מעילה בדבר שנעשתה מצוותו, \u0003משום דהוה ליה\u0004 \u0005[שהריהם]\u0006 דין זה של \u0003תרומת הדשן ו\u0004דין \u0003איברי\u0004 ה\u0003שעיר המשתלח\u0004 לעזאזל ביום הכיפורים, (לאחר שנזרק השעיר מן ההר ונעשה גופו אברים אברים) \u0003שני כתובין הבאין כאחד,\u0004 שיש בהם דין מיוחד, שאסורים בהנאה, אף שכבר נעשתה מצוותם, \u0003ו\u0004כלל הוא כי \u0003כל שני כתובין הבאין כאחד\u0004 — \u0003אין מלמדין\u0004 לשאר הלכות שבתורה.","ושואלים על תירוץ זה: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006תירוץ \u0005זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003איברי שעיר המשתלח\u0004 — \u0003אין נהנין מהן,\u0004 והרי זה איפוא דבר שנעשתה מצוותו ויש בו דין מעילה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003נהנין מהן,\u0004 ואין בהם דין מעילה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 מדוע לא נלמד מתרומת הדשן?!","ומשיבים: \u0003משום דהוה ליה\u0004 \u0005[שהריהם]\u0006 דין זה של \u0003תרומת הדשן ו\u0004דינם של \u0003בגדי כהונה\u0004 (בגדי הלבן שלובש הכהן הגדול בעבודת המקדש ביום הכיפורים), \u0003שני כתובין הבאין כאחד,\u0004 שבשניהם מועלים בהם אף לאחר שנעשתה מצוותם, \u0003ו\u0004כלל הוא כי \u0003כל שני כתובין הבאין כאחד\u0004 — \u0003אין מלמדין.\u0004","וחוזרים ושואלים: \u0003הניחא לרבנן דאמרי\u0004 \u0005[זה נוח ל\u0006שיטת \u0005חכמים שאומרים]\u0006 כי מה שנאמר בעבודת הכהן הגדול ביום הכיפורים \"ופשט את בגדי הבד אשר לבש בבואו אל הקודש \u0003והניחם שם\"\u0004 (ויקרא טז, כג) — \u0003מלמד שהן,\u0004 הבגדים, \u0003טעונין\u0004 (חייבים) \u0003גניזה\u0004 ואינם ראויים עוד לשימוש אחר, לפי זה \u0003שפיר\u0004 \u0005[יפה]\u0006 הוא התירוץ שאמרנו.","\u0003אלא לר' דוסא\u0004 ש\u0003אמר\u0004 ש\u0003מותר להשתמש בהן\u0004 בבגדי כהונה אלה \u0003כהן הדיוט,\u0004 שהרי בגדי הלבן שלובש הכהן הגדול ביום הכיפורים הם בגדי הכהן ההדיוט במשך השנה, ואינם טעונים גניזה, ואין בהם דין מעילה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי לפי זה אין דין תרומת הדשן אלא כתוב אחד בלבד, המלמד!","ומשיבים: \u0003משום דהוה\u0004 \u0005[שהריהם]\u0006 דין זה של \u0003תרומת הדשן ו\u0004דין \u0003עגלה ערופה\u0004 (שאסורה בהנאה גם לאחר שהתקיימה מצוותה) \u0003שני כתובין הבאין כאחד,\u0004 ואינם מלמדים.","ושואלים מצד אחר: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006תירוץ \u0005זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 ששני כתובים הבאים כאחד \u0003אין מלמדין, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שאף שני כתובים הבאים כאחד \u0003מלמדין, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \u0003תרי מיעוטי כתיבי\u0004 \u0005[שני\u0006 לשונות \u0005מיעוט כתובים\u0006 בשני דינים אלו\u0005],\u0006 ללמדנו שהלכה זו נוהגת רק בהם. \u0003כתיב התם\u0004 \u0005[כתוב שם]\u0006 בעגלה ערופה \"העגלה \u0003הערופה\"\u0004 (דברים כא, ו), ובאה ה_ה' היתירה שבראש המלה \"העגלה\" לומר: בזו נוהג דין זה ולא בדבר אחר.","\u0003וכתיב התם\u0004 \u0005[וכתוב שם]\u0006 בתרומת הדשן \u0003\"ושמו אצל המזבח\"\u0004 (ויקרא ו, ג), להורות: שישים אותו ולא אחר. ומכאן כי דווקא \u0003הני\u0004 \u0005[אלה]\u0006 — \u0003אין\u0004 \u0005[כן],\u0006 נוהג בהם דין מעילה אף שנעשתה מצוותם, ואילו ב\u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא.\u0004","שנינו במשנתנו בדין ה\u0003נסכים\u0004 כי \u0003בתחילה\u0004 (משהוקדשו) \u0003מועלין בהן,\u0004 ואולם משירדו לשיתין — אין מועלין בהם. ומציעים: \u0003לימא מתניתין\u0004 \u0005[האם\u0006 יש מקום \u0005לומר\u0006 ש\u0005משנתנו]\u0006 היא ש\u0003לא כ\u0004דעת \u0003ר' אלעזר בר ר' צדוק,\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר בר ר' צדוק אומר: לול\u0004 (חלל) \u0003קטן היה\u0004 במקדש \u0003בין\u0004 ה\u0003כבש למזבח, במערבו של כבש.\u0004 ו\u0003אחת לשבעים שנה\u0004 היו \u0003פרחי כהונה\u0004 (צעירי הכהנים) \u0003יורדין בו\u0004 בתוך הלול הזה אל השיתים, \u0003ומביאין\u0004 משם \u0003יין קרוש\u0004 שהצטבר שם משאריות הנסכים, \u0003שהוא דומה\u0004 בצורתו \u0003לעגולי דבילה\u0004 (תאנה יבישה), \u0003ו\u0004היו \u0003שורפין אותה בקדושה,\u0004 בעזרה. \u0003ש\u0004כן \u0003נאמר: \"בקדש הסך נסך שכר לה' \"\u0004(במדבר כח, ז), לומר: \u0003כשם שניסוכה בקדושה\u0004 — \u0003כך שריפתה בקדושה.\u0004","ותחילה שואלים על ראיה זו: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כיצד למדים מכתוב זה ענין שריפה שלא נאמר בו? \u0003ואמר רבינא: אתיא\u0004 \u0005[באה]\u0006 נלמד הדבר בגזירה שווה, מהמילים \u0003\"קדש\" \"קדש\".\u0004 שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן],\u0006 בענין הנסכים \u0003\"בקדש\u0004 הסך נסך שכר\" (במדבר כח, ז)\", \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בענין הנותר מן הקרבנות לאחר זמן אכילתם הראוי \u0003\"ושרפת את הנותר באש לא יאכל כי קדש הוא\"\u0004 (שמות כט, לד), ללמד:","\u0003מה נותר\u0004 — \u0003שריפתו בקדושה, אף האי נמי\u0004 \u0005[זה,\u0006 נסכים, \u0005גם כן]\u0006 שריפתו \u0003בקדושה!\u0004 מכל מקום רואים כי לשיטת ר' אלעזר בר' צדוק בנסכים אף משירדו לשיתים נוהגים בהם מנהג קדושה ושורפים אותם, ושלא כשיטת משנתנו!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כדעת \u0003ר' אלעזר בר ר' צדוק\u0004 היא, ואולם יש לומר שכוונת משנתנו למקרה \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003קלט\u0004 חלל הלול חלק מן הנסכים, ולא הגיעו אל ריצפת השיתים — באלה אין מועלים, ואין מצוותם בשריפה אף לשיטת ר' אלעזר בר' צדוק. אבל בנסכים שירדו אל השיתים — נוהג דין שריפה, ומועלים בהם, שכן קרקע השיתים מקדשת אותם.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 באופן זה את מהלך הסוגיה, שבתחילה מציעים: \u0003לימא מתניתין\u0004 \u0005[האם\u0006 יש מקום \u0005לומר\u0006 ש\u0005משנתנו]\u0006 היא \u0003כ\u0004דעת \u0003ר' אלעזר בר ר' צדוק,\u0004 ומדובר בה דווקא באופן \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003קלט\u0004 הלול את הנסכים לפני ירידתם לשיתים, ובאופן זה הוא שאין בנסכים דין מעילה, אבל אם ירדו לשיתים ונתקדשו כתוצאה מכך — דינם בשריפה, ומועלים בהם?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיית ההצעה: \u0003לא,\u0004 אין לומר כן, שכן אפשר לומר שאף אם לא נקלטו בלול, אלא ירדו ישר לשיתים, סבור ר' אלעזר בר' צדוק שאין בהם דין מעילה, לפי שמן התורה אכן אין בהם עוד קדושה, \u0003ו\u0004מה שאמר ר' אלעזר בר' צדוק את דינו לענין שריפתם, זה אינו אלא דין \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 בלבד. ושואלים על כך: \u0003והא קרא קנסיב לה\u0004 \u0005[והרי מקרא הוא\u0006 ר' אלעזר בר' צדוק \u0005מביא לה]\u0006 כראיה שיש לשרפם? ומשיבים: מקרא זה מובא כ\u0003אסמכתא\u0004 בלבד ואין בכך כדי להוכיח שדין זה מן התורה.","\u0003דישון מזבח הפנימי,\u0004 כלומר, האפר שנשאר על גבי המזבח הפנימי (מזבח הקטורת) ומוצא למקום הנחת תרומת הדשן שבמזבח החיצון, \u0003ו\u0004כיוצא בו הדישון של פתילות \u0003המנורה\u0004 — \u0003לא נהנין\u0004 מהם לכתחילה, \u0003ו\u0004אולם אם עברו ונהנו מהם \u0003לא מועלין\u0004 בהם. \u0003המקדיש\u0004 את ה\u0003דישון\u0004 מהמזבח הפנימי \u0003בתחלה,\u0004 שחזר והקדישו במקום הנחתו אצל המזבח החיצון — \u0003מועלין בה.\u0004 אם הקדיש \u0003תורין ש\u0004עדיין \u0003לא הגיע זמנן\u0004 משום שהם צעירים מדי, או \u0003בני יונה ש\u0004כבר \u0003עבר זמנן\u0004 שהם מבוגרים מידי — \u0003לא נהנין\u0004 מהם \u0003ולא מועלין\u0004 בהם.","שנינו במשנתנו בדין הדשן של המזבח הפנימי, שאין מועלים בו לאחר שניתן במקום הדשן ליד המזבח החיצון. הרי איפוא שלפני שנותן אצל מזבח החיצון יש בדשן המזבח הפנימי דין מעילה. ודנים בדבר: \u0003בשלמא\u0004 \u0005[נניח]\u0006"],["הדשן שעל ה\u0003מזבח החיצון\u0004 הריהו בדין מעילה, משום \u0003דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"ושמו אצל המזבח\"\u0004 (ויקרא ו, ג), ולהורות שיש לגנוז את הדשן אף שכבר נעשתה מצוות ההרמה בו, ולכן יש בו דין מעילה. ואולם הדשן שעל ה\u0003מזבח הפנימי מנלן\u0004 \u0005[מנין לנו]\u0006 שצריך להניחו במקום הדשן של המזבח החיצון, ואף בו יש דין מעילה?","\u0003אמר ר' אלעזר:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדינה של עולת העוף \u0003\"והסיר את מראתו בנצתה\u0004 והשליך אותה אצל המזבח קדמה אל מקום הדשן\" (שם א, טז). הרי שאותו מקום אליו מושלך זפק עולת העוף (\"מוראתו\") מכונה \"מקום הדשן\", שהוא מקום נתינת הדשן מעל המזבח. ומעתה, \u0003אם\u0004 כתוב זה \u0003אינו ענין ל\u0004דשנו של ה\u0003מזבח החיצון,\u0004 שהרי כבר למדנו דינו מהכתוב \"ושמו אצל המזבח\", \u0003תנהו ענין ל\u0004דשן שעל ה\u0003מזבח הפנימי,\u0004 שאף הוא בכלל המצוה להינתן באותו מקום, ודוחים:","\u0003אימא\u0004 \u0005[אמור]\u0006 כי \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 שני הכתובים הללו עניינם \u0003ב\u0004דשן שעל ה\u0003מזבח החיצון, ו\u0004נצרך כתוב נוסף זה שמצויין בו \"מקום הדשן\" על מנת \u0003לקבוע לו\u0004 לדשן \u0003מקום\u0004 מוגדר להניחו. ואם כן אין מקור לדין דשן המזבח הפנימי!","ומשיבים: \u0003אם כן,\u0004 שעניינם של שני המקראות הללו הוא בדשן המזבח החיצון ובא הכתוב הנוסף הזה לקבוע לו מקום, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק \"והסיר את מוראתה בנוצתה והשליך אותה \u0003אצל המזבח\",\u0004 והיינו מבינים שהוא באותו מקום כ\"אצל המזבח\" האמור בדשן המזבח החיצון. ולא היה צורך איפוא בתוספת הכתוב \"אל מקום הדשן\", ומעתה \u0003מאי\u0004 \u0005[מה]\u0006 מלמדתנו התוספת \"אל מקום \u0003הדשן\"?\u0004 — ש\u0003אפילו\u0004 הדשן של ה\u0003מזבח הפנימי\u0004 ניתן שם.","ושואלים עוד: ודין דישון ה\u0003מנורה\u0004 ששנינו במשנה שלאחר שנעשתה מצוותו אין מועלים בו \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים: הדבר נלמד מן הה\"א היתירה שבכתוב \"הדשן\", שכן היה יכול להיאמר בכתוב רק \u0003\"דשן\",\u0004 ונאמר \u0003\"הדשן\"\u0004 — הרי זה בא לרבות גם את דשן המנורה.","שנינו במשנה הקודמת שתורים שלא הגיע זמנם, וכן בני יונה שעבר זמנם אין נהנים מהם לכתחילה, ואולם העובר ונהנה מהם — אין בו דין מעילה. על דברים אלה חולק \u0003ר' שמעון\u0004 ו\u0003אומר\u0004 כי אף \u0003תורין שלא הגיע זמנן\u0004 — \u0003מועלין בהן,\u0004 אבל \u0003בני יונה שעבר זמנן לא נהנין ולא מועלין בהן.\u0004","מן המשנה הקודמת וממשנתנו זו רואים שנחלקו חכמים ור' שמעון אם יש דין מעילה בתורים שעדיין לא הגיע זמנם, ומבררים את השיטות: \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובנת\u0005]\u0006 שיטתו של \u0003ר' שמעון, כדקתני טעמא\u0004 \u0005[כמו שהוא\u0006 עצמו, \u0005שנה טעם]\u0006 שיטתו במקום אחר, שכן שנינו במשנה במסכת זבחים (קיב,ב): \u0003שהיה ר' שמעון אומר\u0004 בטעם שיטתו זו, שכלל הוא, כי \u0003כל הראוי\u0004 להיות קרב \u0003לאחר זמן\u0004 וכגון תורים אלה שיוכשרו להקרבה לכשיגדלו, \u0003והקדישו בתוך זמנו,\u0004 לפני שהגיע זמנו להיקרב, ושחטו בחוץ — הרי הוא עובר \u0003בלא תעשה, ו\u0004אולם \u0003אין בו\u0004 חיוב \u0003כרת.\u0004 וטעם זה הוא אף הסברה של שיטת ר' שמעון במשנתנו, שיש דין מעילה בתורים שלא הגיע זמנם.","\u0003אלא\u0004 לשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 הסבורים שאין דין מעילה בתורים שלא הגיע זמנם, יש לשאול: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 דין זה \u0003מ\u0004דין בהמה שהוא \u0003מחוסר זמן\u0004 (שטרם הגיע זמנה הראוי להקרבה), שחלה עליה קדושה, וכפי ששנינו בענין מעשר בהמה שאף בהמה שלא הגיע זמנה ועדיין אינה ראויה להקרבה נכנסת לדיר להתעשר?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לדבר: אין להשוות אלה לאלה, שכן המקדיש מן הבהמה \u0003מחוסר זמן\u0004 — הרי זה \u0003מידי דהוה\u0004 \u0005[כמו שהינו]\u0006 מקדיש \u0003בעל מום,\u0004 שחלה עליו קדושה לענין זה \u0003דבר\u0004 \u0005[שבן]\u0006 \u0003פדיון\u0004 מקדושה לחולין \u0003הוא.\u0004 ומתוך שככלל חלה קדושה בבהמה בעלת מום, אף חלה בה קדושה כשהיא מחוסרת זמן. \u0003אבל הני\u0004 \u0005[אלה]\u0006 \u0003עופות, כיון\u0004 ש\u0003אין מום פוסל בעופות\u0004 — \u0003אין\u0004 איפוא \u0003לעופות\u0004 דין \u0003פדיון\u0004 בבעל מום, ואי אפשר לומר שפדיונם מוכיח על קדושתם, ואין אם כן מקום לומר שמתוך כך אף תחול קדושה במחוסר זמן בעופות.","ועוד לענין תורים שלא הגיע זמנם ובני יונה שעבר זמנם, \u0003אמר עולא, אמר ר' יוחנן: קדשים שמתו,\u0004 כיון שאינם ראויים עוד להקרבה, ויצאו בכך מכלל \"קדשי ה' \", שכן אף לפדותם אינו יכול (שכן אין פודים את הקדשים שהאכילם לכלבים) ומשום כך אף \u0003יצאו מידי מעילה דבר\u0004 (מדין) \u0003תורה.\u0004","ומסופר כי \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003עולא\u0004 בבית המדרש \u0003וקאמר להא שמעתא\u0004 \u0005[ואמר את ההלכה הזו]\u0006 בשמו של ר' יוחנן, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: מאן שמע\u0004 \u0005[מי שומע,\u0006 יקבל\u0005]\u0006 \u0003לך ולר' יוחנן רבך\u0004 בהלכה זו, שאין בהם עוד דין מעילה מן התורה?! \u0003וכי קדושה ש\u0004היתה \u0003בהן\u0004 עד שמתו \u0003להיכן הלכה\u0004 שיצאו מידי מעילה?!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא לרב חסדא: לשיטתך \u0003תיקשי מתניתין\u0004 \u0005[תוקשה\u0006 לך הלכה מפורשת ב\u0005משנתנו]\u0006 ששנינו בה כי \u0003תורין שלא הגיע זמנן ובני יונה שעבר זמנן\u0004 — \u0003לא נהנין ולא מועלין\u0004 בהם, \u0003הכא נמי נימא\u0004 \u0005[כאן גם כן נאמר]:\u0006 \u0003קדושה שבהן\u0004 בבני יונה שעבר זמנם \u0003להיכן הלכה,\u0004 ומדוע אין בהם מעילה?!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לעולא בתשובה: אכן גם בקדשים שמתו וגם בבני יונה שעבר זמנם פקעה לה הקדושה שמן התורה, ואולם \u0003מודינא\u0004 \u0005[מודה אני]\u0006 \u0003לך דאיכא\u0004 \u0005[שיש]\u0006 בקדשים שמתו דין \u0003מעילה מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 ואף בבני יונה שעבר זמנם כך הדין, ואין מקום לשאול על הקדושה להיכן הלכה. \u0003ו\u0004אולם דבר זה \u0003קשיא\u0004 \u0005[היה קשה]\u0006 \u0003לי: מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 \u0003דמעיקרא\u0004 \u0005[שמתחילה],\u0006 בשעה שהוקדשו, עדיין \u0003לא אית ביה\u0004 \u0005[אין בו]\u0006 דין \u0003מעילה\u0004 מן התורה, \u0003ולבסוף אית ביה\u0004 \u0005[יש בו]\u0006 דין \u0003מעילה\u0004 (מדברי חכמים) כגון תורים שלא הגיע זמנם?","ותוהים: \u0003ולא?\u0004 והאם אין דבר כזה שבתחילה אין בו דין מעילה ולבסוף יש בו דין מעילה? \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003דם, דמעיקרא לית\u0004 \u0005[שמתחילה אין]\u0006 \u0003בה\u0004 דין \u0003מעילה, ולבסוף אית\u0004 \u0005[יש]\u0006 \u0003בה\u0004 דין \u0003מעילה, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה בדף הקודם\u0005]:\u0006 \u0003דם, בתחלה\u0004 — \u0003אין מועלין בו, יצא לנחל קדרון\u0004 — \u0003מועלין בו!\u0004","ודוחים: \u0003אמרי\u0004 \u0005[אומרים]:\u0006 אין זו ראיה, שכן \u0003התם נמי\u0004 \u0005[שם,\u0006 בדם, \u0005גם כן]\u0006 \u0003איכא\u0004 \u0005[יש]\u0006 \u0003מעילה מעיקרא\u0004 \u0005[מתחילה],\u0006"],["\u0003דאמר\u0004 \u0005[ש\u0006כן \u0005אמר]\u0006 \u0003רב: המקיז דם לבהמת קדשים\u0004 החיה, הדם שהוקז \u0003אסור בהנאה, ומועלין בו\u0004 מן התורה אם נהנו ממנו. ומשום כך, יש בו גם דין מעילה מדברי חכמים אף בסופו, כשירד אל נחל קדרון. ואין זה דומה לתורים שלא הגיע זמנם שמעיקרם אין בהם דין מעילה.","למעלה הובא דינו של דם שהוקז מבהמת קדשים, ועתה דנים בהלכה זו \u0003גופא\u0004 \u0005[לגופה].\u0006 \u0003אמר רב הונא, אמר רב: המקיז דם לבהמת קדשים\u0004 — אסור הדם \u0003בהנאה, ומועלין בו. מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב המנונא\u0004 מההלכה השנויה במשנה (לקמן) ש\u0003חלב\u0004 הבא מבהמות \u0003המוקדשין\u0004 לקרבן, \u0003ו\u0004כן \u0003ביצי\u0004 ה\u0003תורין\u0004 שהוקדשו לקרבן העוף — \u0003לא נהנין\u0004 מהם, \u0003ו\u0004אם עבר ונהנה מהם — \u0003לא מועלין\u0004 בהם, אף שבבהמה ובתורים עצמם מועלים. הרי שהדבר היוצא מגופו של המוקדש אינו נחשב כגוף המוקדש לדין מעילה, ובמה שונה דין הדם מדין החלב והביצים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב בתשובה: \u0003כי קאמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 שדבר היוצא מגוף בעל החיים, יש בו דין מעילה, הרי זה דווקא \u0003לגבי\u0004 \u0005[אצל]\u0006 \u0003דם,\u0004 וטעם הדבר: \u0003דלא\u0004 \u0005[ש\u0006הרי \u0005אין]\u0006 \u0005הבהמה\u0006 \u0003מתקיימת בלא דם,\u0004 ואם כן הדם כגופה של הבהמה. \u0003אבל חלב, דקא מקיימא\u0004 \u0005[ש\u0006היא \u0005יכולה להתקיים]\u0006 \u0003בלא חלב\u0004 — הריהו \u0003לא\u0004 נחשב כגופה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב משרשיא\u0004 ממה ששנינו בברייתא: \u0003הזבל\u0004 (גללי בהמות שנדרסו ונהפכו לזבל) \u0003והפרש\u0004 (הגללים) של בהמות הקדשים \u0003ש\u0004נמצאים \u0003בחצר\u0004 ההקדש — \u0003אין נהנין\u0004 בהם, \u0003ו\u0004אולם אם עברו ונהנו \u0003אין מועלין\u0004 בהם. \u0003ויפלו דמיה\u0004 של הזבלים הללו \u0003ללשכה,\u0004 שניתנים למקדש.","ולפי הבחנה זו שבין הדם לחלב, יש להקשות: \u0003אמאי\u0004 \u0005[מדוע]\u0006 אין בפרש דין מעילה, \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 הרי \u0003לא מקיים\u0004 \u0005[אין מתקיים]\u0006 בעל החיים \u0003בלא פרש,\u0004 ואם כן יתחייב גם על הפרש במעילה! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיית השאלה: \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 זה לזה, אין להשוות בין הפרש לבין הדם, שכן \u0003הדין\u0004 \u0005[זה]\u0006 ה\u0003פרש דמן עלמא קאתי לה\u0004 \u0005[שמן החוץ הוא בא]\u0006 \u0003לה,\u0004 לבהמה, מהמאכלים שאכלה, ו\u0003אזיל האי\u0004 — \u0003אתי אחרינא\u0004 \u0005[הולך זה\u0006 האוכל בצורת פרש, ו\u0005בא אחר\u0006 במקומו\u0005].\u0006 \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003דם,\u0004 שהוא \u0003מגופה\u0004 של הבהמה ואין אחר בא במקומו.","ומעירים: \u0003הא קתני\u0004 \u0005[הרי שנינו]\u0006 בברייתא זו בדין הזבל והפרש של בהמות ההקדש כי \u0003לא נהנין ולא מועלין\u0004 בו \u0003ודמיו ללשכה.\u0004 והרי דין זה \u0003מסייעא ליה\u0004 \u0005[מסייע לו]\u0006 \u0003לר' אלעזר,\u0004 שכן \u0003אמר ר' אלעזר: כל מקום שאמרו חכמים\u0004 על דבר מסויים דין ממנו נראה כי הדבר \u0003קדוש ואינו קדוש,\u0004 וכגון זה שאין נהנים ממנו ואולם הנהנה ממנו אין בו דין מעילה — \u0003דמיו יפלו ללשכה.\u0004","\u0003חלב\u0004 הבא מבהמות נקבות \u0003המוקדשין, ו\u0004כן \u0003ביצי\u0004 ה\u0003תורין\u0004 של הקדש — \u0003לא נהנין\u0004 מהם, שאסורים הם בהנאה, \u0003ו\u0004אולם אם עברו ונהנו מהם — \u0003לא מועלין\u0004 בכך.","ומסייגים הלכה זו: \u0003במה דברים אמורים\u0004 שאין מועלים בחלב ובביצי המוקדשים — שהקדישם \u0003בקדשי מזבח\u0004 (להקרבה על המזבח), שכיון שאין החלב והביצים קרבים על המזבח, הרי הם חלוקים מקדשי מזבח ואין בהם דין מעילה. \u0003אבל\u0004 אם היו אלה חלב וביצים הבאים מן המוקדשים \u0003בקדשי בדק הבית,\u0004 כגון שהעוף ש\u0003הקדיש\u0004 הוא \u0003תרנגולת\u0004 שאינה עולה למזבח ואין בה קדושת הגוף אלא קדושת דמים בלבד — הרי אין לחלק בינה ובין ביצתה, שבשתיהן קדושת דמים בלבד ו\u0003מועלין בה ובביצתה,\u0004 וכן אם הקדיש \u0003חמורה\u0004 (אתון) — \u0003מועלין בה ובחלבה,\u0004 שאף היא וחלבה קדושים בקדושת דמים בלבד.","שנינו במשנה כי בקדשי מזבח אין דין מעילה בחלב ובביצים, ולשון כוללת זו משמעה שבכל אופני קדשי המזבח אין בהם דין מעילה, ותוהים על כך: \u0003אלא\u0004 מעתה האם \u0003גבי\u0004 \u0005[אצל]\u0006 קדשי \u0003מזבח, כי אקדשה\u0004 \u0005[כאשר הקדיש אותה],\u0006 את הבהמה או העוף, לא בקדושת הגוף (שתיקרב היא עצמה על המזבח) אלא ב\u0003קדושת דמים\u0004 (שבדמים שיתקבלו ממכירתה, יביאו קרבן למזבח, וכגון שאמר \"דמי בהמה זו לקרבן פלוני\"), אכן \u0003לא אית\u0004 \u0005[אין]\u0006 \u0003בה,\u0004 בחלב או ביצים היוצאים ממנה, דין \u0003מעילה?\u0004","\u0003רב פפא: חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 היא לשון המשנה, \u0005וכך היא שנויה\u0006 במלואה\u0005]:\u0006 \u0003במה דברים אמורים\u0004 שאין מועלים בחלב ובביצי המוקדשים לקדשי מזבח? — דווקא \u0003כשהקדיש\u0004 אותם ב\u0003קדושת הגוף לגבי\u0004 \u0005[אצל]\u0006 \u0003מזבח, אבל\u0004 אם \u0003הקדישו קדושת דמים לגבי\u0004 \u0005[אצל]\u0006 \u0003מזבח\u0004 — \u0003נעשה כמי שהקדישו לבדק הבית,\u0004 ומועלים בהם. ואיך מועלים בגידוליהם של המוקדשים לקדשי בדק הבית? — \u0003הקדיש תרנגולת\u0004 — \u0003מועלין בה ובביצתה, חמורה\u0004 (אתון) — \u0003מועלין בה ובחלבה\u0004.","\u0003כל\u0004 שהוקדש לבית המקדש, \u0003הראוי ל\u0004הקרבה על ה\u0003מזבח\u0004"],["\u0003ולא\u0004 ראוי \u0003לבדק הבית,\u0004 וכן הראוי \u0003לבדק הבית ולא\u0004 ראוי \u0003ל\u0004הקרבה על ה\u0003מזבח,\u0004 וכן שאינו ראוי \u0003לא למזבח ולא לבדק הבית\u0004 — \u0003מועלין בה,\u0004 שחלים עליהם דין המעילה. ומפרטים: \u0003כיצד\u0004 הוא הראוי לבדק הבית ואינו ראוי למזבח?","— כגון ש\u0003הקדיש בור מלא מים,\u0004 ומי בורות אינם ראויים למזבח, שכן אין מנסכים אלא ממי השילוח, ואולם ראויים הם לבדק הבית, כגון לגבל בהם טיט לבנין המקדש. וכיצד הוא שאינו ראוי לא למזבח ולא לבדק הבית? — כגון המקדיש \u0003אשפות\u0004 (מקום השלכת זבל) ה\u0003מלאות זבל,\u0004 שאין המקום עצמו ולא הזבל ראויים לא למזבח ולא לבדק הבית, אלא יש למוכרם ודמיהם ינתנו להקדש. למזבח ולא לבדק הבית — המקדיש \u0003שובך מלא יונים,\u0004 שהיונים ראויות להקרבה והשובך אינו ראוי אף לבדק הבית, או","\u0003אילן מלא פירות,\u0004 כשהאילן עצמו אינו ראוי לבדק הבית, ואילו הפירות ראויים למזבח. כגון גפן שאין ענפיה ראויים לבנין ואולם יינו ראוי לניסוך. ושאינו ראוי לא למזבח ולא לבדק הבית — \u0003שדה מלאה עשבים\u0004 — בכל אלה","\u0003מועלין בהם ובמה שבתוכה,\u0004 שאף אלה שבעצמם אינם ראויים לקודש — יכולים להימכר ויפלו דמיהם למזבח או לבדק הבית.","\u0003אבל אם הקדיש בור\u0004 ריק \u0003ואחר כך\u0004 בהיות הבור מוקדש \u0003נתמלא מים,\u0004 וכן המקדיש \u0003אשפה\u0004 ריקה \u0003ו\u0004רק \u0003אחר כך נתמלא זבל,\u0004 וכן המקדיש \u0003שובך\u0004 ריק מיונים \u0003ו\u0004רק \u0003אחר כך נתמלא יונים,\u0004 וכן \u0003אילן\u0004 ללא פירות \u0003ואחר כך נתמלא פירות,\u0004 וכן \u0003שדה\u0004 ריקה \u0003ואחר כך נתמלאה עשבים\u0004 — בכל אלה \u0003מועלין בהם\u0004 עצמם, \u0003ואין מועלין במה שבתוכה,\u0004 שהרי אין דין מעילה בדבר שהושבח ברשות ההקדש.","על שנים מהדברים שאמר התנא קמא שאין מועלים במה שבתוכה חולק \u0003ר' יוסי\u0004 ו\u0003אומר: המקדיש את השדה\u0004 ונתמלאה עשבים, \u0003ו\u0004כן המקדיש את \u0003האילן\u0004 ונתמלא פירות — \u0003מועלין בהן ו\u0004אף \u0003בגידולה\u0004 (גידוליהם) אף שצמחו בהיותם ברשות ההקדש, \u0003מפני ש\u0004סוף סוף \u0003הן גידולי הקדש.\u0004","ומביאים דינים נוספים בגידולי הקדש: \u0003ולד המעושרת,\u0004 שהתקדשה כמעשר בהמה ולפני כן ילדה אותו ולד, והריהו חולין — \u0003לא ינוק מן\u0004 אמו \u0003המעושרת,\u0004 שהרי הוא חולין ואסור בהנאה מן ההקדש. ויש בני אדם \u0003אחרים\u0004 ה\u0003מתנדבים\u0004 (המתנים תנאי) \u0003כן\u0004 לפני שמכניסים את הבהמה לדיר להתעשר שיהא החלב הבא ממנה חולין ולא הקדש, על מנת שיוכל ולדה לינוק ממנה. ואותו דין יש ל\u0003ולד\u0004 הנולד מן \u0003ה\u0004בהמות שהן \u0003מוקדשין\u0004 לפני שהוקדשו — ש\u0003לא ינוק מן המוקדשין, ו\u0004אולם גם בכגון זה \u0003אחרים מתנדבים כן.\u0004","\u0003הפועלים\u0004 (שכרגיל זכאים לאכול משל בעל הבית) אם היו עובדים במקדש \u0003לא יאכלו מן גרוגרות\u0004 (תאנים מיובשות) של ה\u0003הקדש,\u0004 אלא מקבלים מגזבר המקדש כסף, וקונים בו את מזונותיהם מן החולין. \u0003וכן פרה\u0004 העובדת בשל המקדש (כגון בדישה) לא תאכל \u0003מכרשיני\u0004 (צמח מספוא) של ה\u0003הקדש.\u0004","\u0003קתני\u0004 \u0005[שנה]\u0006 במשנתנו: \u0003ולד\u0004 הבהמה \u0003המעושרת\u0004 שנולד לה לפני שהתעשרה \u0003לא ינק מן המעושרת,\u0004 ובדומה לכך אף ולד הבהמה המוקדשת שנולד לה לפני שהתקדשה לא יינק ממנה. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו,\u0006 מה מקורה של הלכה זו\u0005]? אמר רב אחדבוי בר אמי: אתיא\u0006","\u0005[באה,\u0006 נלמדת\u0005]\u0006 גזירה שווה של המלה \u0003\"העברה\"\u0004 הנאמרת במעשר בהמה (\"וכל מעשר בקר וצאן כל אשר יעבור תחת השבט העשירי יהיה קודש לה' \", ויקרא כז, לב) ו\u0003\"העברה\" מ\u0004הנאמר בדין קרבן ה\u0003בכור\u0004 (\"והעברת כל פטר רחם לה' וכל פטר שגר בהמה אשר יהיה לך הזכרים לה' \", שמות יג, יב), ללמד: \u0003מה בכור מועלין בו\u0004 — \u0003אף\u0004 במעשר בהמה מועלים בכל אשר יש בה. ואף \u0003חלב\u0004 הבא מן \u0003המעושרת מועלין בו,\u0004 ואין ולדה שהוא חולין יונק ממנה.","ובדומה לכך \u0003חלב\u0004 הבא מבהמת \u0003המוקדש נמי\u0004 \u0005[גם כן]\u0006 איסורו לולדה החולין \u0003אתיא\u0004 \u0005[באה]\u0006 בגזירה שווה של המלה \u0003\"אמו\"\u0004 הנאמרת במוקדשים (\"...והיה שבעת ימים תחת אמו ומיום השמיני והלאה ירצה לקרבן...\". ויקרא כב, כז) ו\u0003\"אמו\" מ\u0004הנאמר בקרבן \u0003בכור\u0004 (\"שבעת ימים יהיה עם אמו ביום השמיני תתנו לי\", שמות כב, כט). ללמד שחלב המוקדשין אסור לולדה שהוא חולין כמו שהבכור אסור כולו.","עוד שנינו במשנתנו כי \u0003הפועלין\u0004 העובדים במקדש \u0003לא יאכלו\u0004 מגרוגרות ההקדש. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם,\u0006 מהו המקור לכך\u0005]? אמר רב אחדבוי בר אמי,\u0006 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]: \"לא תחסם שור בדישו\"\u0006 (דברים כה, ד) — ללמדנו: ב\u0003\"דישו\" שלך\u0004 ההדיוט, אין אתה חוסם את השור, \u0003ולא\u0004 ב\u0003דישו של הקדש,\u0004 שההקדש אסור בהוצאה לחולין ולכן עליך לחוסמו כדי שלא יאכל משל ההקדש.","ועוד בענין זה של הדישה בהקדש, שנינו: \u0003הדש קלעילין\u0004 (סוג קטניות) שלו, שהן חולין, \u0003בשדה הקדש\u0004 — הרי זה \u0003מעל,\u0004 שהרי נהנה מן ההקדש. ושואלים על כך: \u0003והא\u0004 \u0005[והרי]\u0006 על מנת להתחייב במעילה, הנאה \u0003בתלוש בעינן\u0004 \u0005[מצריכים אנו],\u0006 ולא מן המחובר לקרקע! \u0003אמר רבינא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאבקה של השדה \u0003מעלי לה\u0004 \u0005[מועיל להם]\u0006 לקטניות הנידושות, וכיון שדש זה נהנה מהאבק (שהוא תלוש) — הריהו מתחייב במעילה."],["\u0003שרשי אילן של הדיוט\u0004 (חולין) \u0003הבאין\u0004 (המתפשטים) \u0003ב\u0004קרקע \u0003של הקדש, ו\u0004כן \u0003של\u0004 אילן \u0003הקדש שבאין ב\u0004קרקע \u0003של הדיוט\u0004 — \u0003לא נהנין\u0004 מהם לכתחילה, ואולם אם עברו ונהנו — \u0003לא מועלין\u0004 בכך. \u0003מעין\u0004 מים \u0003ש\u0004נובע בשדה חולין ו\u0003הוא\u0004 נמשך ו\u0003יצא\u0004 ועובר \u0003מתוך השדה של הקדש,\u0004 כל זמן שהוא בשדה ההקדש — \u0003לא נהנין\u0004 ממנו לכתחילה, \u0003ו\u0004אם עברו ונהנו — \u0003לא מועלין.\u0004 ובזמן שהמעין \u0003יצא חוץ לשדה\u0004 ההקדש ונמשך לתוך שדה חולין — \u0003נהנין ממנו\u0004 לכתחילה ממקום יציאתו והלאה.","\u0003המים ש\u0004ניתנו \u0003בכד של זהב,\u0004 שהיו ממלאים בכד מים מן השילוח למצות ניסוך המים על המזבח בחג הסוכות, ולא היה כד זה מקודש ככלי שרת — \u0003לא נהנין\u0004 מאותם מים לכתחילה, שכן נתמלאו לצורך הקדש, \u0003ו\u0004אולם העוברים ונהנים מהם \u0003לא מועלין\u0004 בכך, בהיותם בכלי שאיננו כלי שרת. ומשעה ש\u0003נתנו\u0004 למים אלו מן החבית \u0003בצלוחית\u0004 (שהיא מכלי השרת) על מנת לנסכם, והמים שבתוכה התקדשו בכך — \u0003מועלין בהן.\u0004","ענפי ה\u0003ערבה\u0004 שהיו מעמידים אותם בצידי המזבח בחג הסוכות — \u0003לא נהנין\u0004 מהם לכתחילה קודם שהעמידום בצידי המזבח, שזוהי מצוותם, \u0003ו\u0004אולם העוברים ונהנים מהם \u0003לא מועלין\u0004 בכך. ומשעה שהעמידום וכבר נעשתה מצוותם — אף מותרים לכתחילה בהנאה. \u0003ר' אלעזר בר' צדוק אומר: נוהגין היו הזקנים שנהנים ממנו\u0004 מענפי עץ ערבה זה, אף קודם שהועמדו הענפים בצד המזבח, \u0003בלולביהן,\u0004 שהיו קוטפים מעצי ערבה אלה ענפים למצות ארבעת המינים שלהם. ב גמרא שנינו במשנתנו כי המים המיועדים לניסוך, כל עוד הם בתוך הכד של זהב אין מועלים בהם.","ובענין זה \u0003אמר ריש לקיש: אין מועלין בכולן,\u0004 בכל המים שבכד, אם היו בו יותר משלושה לוגים \u0003אבל מועלין בשלש לוגין\u0004 שבכד, אם היו המים שבכד בדיוק כשיעור זה שהוא הנחוץ למצות ניסוך המים.","ומקשים עליו: והקתני סיפא \u0005[והרי שנה\u0006 ב\u0005סוף\u0006 המשנה\u0005]\u0006 כי רק כאשר \u0003נתנו\u0004 את המים מן הכד \u0003לצלוחית\u0004 — \u0003מועלין בהן, מכלל דרישא\u0004 \u0005[מכאן נסיק ש\u0006במקרה המדובר \u0005בתחילת\u0006 המשנה, כשהמים נתונים בכד\u0005]\u0006 בכל מקרה, ו\u0003אפילו ב\u0004זמן ששיעור המים הוא רק \u0003שלשה לוגין נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 מועלים בהם. ונדחו אם כן דברי ריש לקיש!","ומסבירים: \u0003אלא אי איתמר אסיפא איתמר\u0004 \u0005[אם נאמר\u0006 דין זה של ריש לקיש, לא על תחילת המשנה נאמר, אלא \u0005על סוף\u0006 המשנה \u0005נאמר].\u0006 שכן שנינו שמשעה שניתנו המים בצלוחית דינם ש\u0003מועלין בהן,\u0004 ועל כך \u0003אמר ריש לקיש: אין מועלין אלא ב\u0004זמן שניתנו בצלוחית מים בשיעור \u0003שלשה לוגין,\u0004 כשיעור הנצרך למצוה, שבכגון זה מתקיימת מצוותם. ואולם אם ניתנו לצלוחית מים יותר מכדי שיעור זה — אין מועלים בהם, שכאשר שיעורם מרובה משלושה לוגים לא התקדשו כלל.","\u0003ו\u0004חלוק עליו בכך \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 כי אף אם ניתנו לצלוחית מים בשיעור המרובה משלושה לוגים — \u0003מועלין בכולן,\u0004 שכן לדעתו אין שיעור למים, והתקדשו למצוותם אף אם שיעורם מרובה. ושואלים: \u0003למימרא דקסבר\u0004 \u0005[האם\u0006 אכן יש מקום \u0005לומר שסבור]\u0006 \u0003ריש לקיש\u0004 שיש שיעור קבוע \u0003ל\u0004כמות המים שאין להוסיף עליו? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 בעניין המקריבים מחוץ לבית המקדש, \u0003אמר ר' אליעזר\u0004 (ר' אלעזר. ראה גרסות): \u0003המנסך\u0004 מ\u0003מי חג\u0004 (הסוכות), מהמים שנשאבו לצורך ניסוכם על המזבח, \u0003בחג\u0004 הסוכות \u0003בחוץ\u0004 למקדש — \u0003חייב\u0004 כרת, כשאר המקריבים מחוץ למקדש.","\u0003ואמר\u0004 על כך ר' יוחנן משום (בשם) החכם \u0003מנחם יודאפה:\u0004 דין זה ששנה \u0003ר' אלעזר, בשיטת ר' עקיבא\u0004 רבו \u0003אמר. דדריש\u0004 \u0005[ש\u0006כך \u0005דרש]\u0006 ר' עקיבא את הנאמר בקרבנות חג הסוכות \u0003\"נסכיהם\"\u0004 (במדבר כט, לא), בלשון רבים, ללמדנו כי בשני ניסוכים הכתוב מדבר: ה\u0003אחד\u0004 הוא \u0003ניסוך המים,\u0004 שהיא מצוה המיוחדת לחג הסוכות, \u0003ואחד\u0004 הוא \u0003ניסוך היין\u0004 הנלווה לקרבן התמיד בכל יום.","\u0003ואמר ריש לקיש\u0004 לר' יוחנן: \u0003אי\u0004 \u0005[אם]\u0006 על כך מסתמך ר' אלעזר לחייב את המנסך מים מחוץ למקדש, יש להשוות בין מים ליין לשיטתו של ר' אלעזר ולומר: \u0003מה\u0004 בניסוך ה\u0003יין\u0004 שיעור המצוה הוא \u0003שלש לוגין, אף\u0004 מצות ניסוך ה\u0003מים\u0004 יהיה שיעורה \u0003שלש לוגין!\u0004 ו\u0003מכלל\u0004 דבריו שאמר ריש לקיש לר' יוחנן נלמד כי \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003ריש לקיש\u0004 עצמו ש\u0003אין שיעור למים!\u0004 ומשיבים: ריש לקיש עצמו סבור שיש שיעור למים, ואולם \u0003לטעמא\u0004 \u0005[לטעמו]\u0006 של \u0003מנחם יודאפה\u0004 כפי שמסר ר' יוחנן, \u0003קאמר\u0004 \u0005[הוא אמר]\u0006 את קושייתו זו.","\u0003הקן\u0004 של ציפור \u0003ש\u0004נמצא \u0003בראש האילן של הקדש\u0004 — \u0003לא נהנין\u0004 ממנו לכתחילה, \u0003ו\u0004אולם העוברים ונהנים \u0003לא מועלין\u0004 בכך. הקן \u0003ש\u0004נמצא \u0003ב\u0004ראש אילן של \u0003אשירה\u0004 (עץ המשמש לעבודה זרה), והריהו אסור בהנאה, ואף לטפס עליו אסור, ומה יעשה כדי להוריד את הקן שמעליו? — \u0003יתיז\u0004 (ינתק בהכאה) את הקן ממקומו \u0003ב\u0004אמצעות \u0003קנה\u0004 (מקל). האדם \u0003המקדיש את החורש\u0004 (יער) השייך לו — \u0003מועלין בכולו,\u0004 בכל מה שיש בחורש."]]};
